window.TOPICS=[{"id": "620f982081e3e73e", "n": 1, "title": "IB Accounting (BIWS) EN-RU", "sections": ["IB Accounting (BIWS) EN-RU", "IB Accounting (BIWS) EN-RU::1. Key Rules — Ключевые правила", "IB Accounting (BIWS) EN-RU::2. Basic Concepts — Базовые понятия", "IB Accounting (BIWS) EN-RU::3. Single-Step Scenarios — Одношаговые сценарии", "IB Accounting (BIWS) EN-RU::4. Multi-Step Scenarios — Многошаговые сценарии", "IB Accounting (BIWS) EN-RU::5. Advanced Concepts — Продвинутые понятия", "IB Accounting (BIWS) EN-RU::6. Advanced Scenarios — Продвинутые сценарии"]}];
window.CARDS=[{"id": 1790385598251, "topic": "620f982081e3e73e", "sec": "IB Accounting (BIWS) EN-RU::1. Key Rules — Ключевые правила", "q": "Key Rules · Ключевые правила Which items NEVER appear on the Income Statement? Какие статьи НИКОГДА не попадают в ОПУ?", "a": ["Answer (EN) Capital Expenditures, purchasing or selling Investments and PP&E, Dividends, issuing or repaying Debt principal, issuing or repurchasing shares, and changes to Balance Sheet items (Cash, Debt, AR, AP, etc.). They either don't affect taxes or don't correspond to the current period. Ответ (RU) Капвложения, покупка и продажа инвестиций и ОС, дивиденды, привлечение и погашение тела долга, выпуск и выкуп акций, изменения статей баланса (деньги, долг, дебиторка, кредиторка). Они либо не влияют на налог, либо не относятся к текущему периоду. Пояснение Это обратная сторона правила двух условий (текущий период + уменьшает налог). У Молчанова в задаче 7-2 все операции 14–23 (оплаты) — из этого списка: ни одна не расход."], "frontHtml": "<div><div>Key Rules · Ключевые правила</div>\n<div>Which items NEVER appear on the Income Statement?</div>\n<div>Какие статьи НИКОГДА не попадают в ОПУ?</div></div>", "backHtml": "<div>\n\n<div><div>Answer (EN)</div>Capital Expenditures, purchasing or selling Investments and PP&amp;E, Dividends, issuing or repaying Debt principal, issuing or repurchasing shares, and changes to Balance Sheet items (Cash, Debt, AR, AP, etc.). They either don&#x27;t affect taxes or don&#x27;t correspond to the current period.</div>\n<div><div>Ответ (RU)</div>Капвложения, покупка и продажа инвестиций и ОС, дивиденды, привлечение и погашение тела долга, выпуск и выкуп акций, изменения статей баланса (деньги, долг, дебиторка, кредиторка). Они либо не влияют на налог, либо не относятся к текущему периоду.</div>\n<div><div>Пояснение</div>Это обратная сторона правила двух условий (текущий период + уменьшает налог). У Молчанова в задаче 7-2 все операции 14–23 (оплаты) — из этого списка: ни одна не расход.</div>\n</div>"}, {"id": 1790385598253, "topic": "620f982081e3e73e", "sec": "IB Accounting (BIWS) EN-RU::1. Key Rules — Ключевые правила", "q": "Key Rules · Ключевые правила If an Asset goes up, what happens to cash flow? If a Liability goes up? Растёт актив — что с денежным потоком? Растёт обязательство?", "a": ["Answer (EN) Asset up → cash flow down (and vice versa). Liability up → cash flow up (and vice versa). This rule is universal, with no exceptions. Ответ (RU) Актив растёт → денежный поток уменьшается (и наоборот). Обязательство растёт → денежный поток увеличивается (и наоборот). Правило универсально, исключений нет. Пояснение Интуиция: рост дебиторки или запасов — деньги «заморожены» в активе. Рост кредиторки — мы пользуемся чужими деньгами и ещё не заплатили. Именно так работает косвенный метод ОДДС в задаче 7-3."], "frontHtml": "<div><div>Key Rules · Ключевые правила</div>\n<div>If an Asset goes up, what happens to cash flow? If a Liability goes up?</div>\n<div>Растёт актив — что с денежным потоком? Растёт обязательство?</div></div>", "backHtml": "<div>\n\n<div><div>Answer (EN)</div>Asset up → cash flow down (and vice versa). Liability up → cash flow up (and vice versa). This rule is universal, with no exceptions.</div>\n<div><div>Ответ (RU)</div>Актив растёт → денежный поток уменьшается (и наоборот). Обязательство растёт → денежный поток увеличивается (и наоборот). Правило универсально, исключений нет.</div>\n<div><div>Пояснение</div>Интуиция: рост дебиторки или запасов — деньги «заморожены» в активе. Рост кредиторки — мы пользуемся чужими деньгами и ещё не заплатили. Именно так работает косвенный метод ОДДС в задаче 7-3.</div>\n</div>"}, {"id": 1790385598255, "topic": "620f982081e3e73e", "sec": "IB Accounting (BIWS) EN-RU::1. Key Rules — Ключевые правила", "q": "Key Rules · Ключевые правила In what order should you walk through a 3-statement scenario, and what tax rate do you assume? В каком порядке проходить сценарий по трём отчётам и какую ставку налога брать?", "a": ["Answer (EN) Income Statement → Cash Flow Statement → Balance Sheet, so you can check at the end that the Balance Sheet balances. Assume a 40% tax rate unless told otherwise, and state that assumption upfront. Ответ (RU) ОПУ → ОДДС → баланс, чтобы в конце проверить, что баланс сходится. Ставка налога 40%, если не сказано иное, — и об этом нужно сказать в начале ответа. Пояснение 40% — удобная учебная ставка (реальная федеральная ставка в США сейчас 21%, в России налог на прибыль 25% с 2025 года). Если интервьюер задаёт другую ставку, просто пересчитай."], "frontHtml": "<div><div>Key Rules · Ключевые правила</div>\n<div>In what order should you walk through a 3-statement scenario, and what tax rate do you assume?</div>\n<div>В каком порядке проходить сценарий по трём отчётам и какую ставку налога брать?</div></div>", "backHtml": "<div>\n\n<div><div>Answer (EN)</div>Income Statement → Cash Flow Statement → Balance Sheet, so you can check at the end that the Balance Sheet balances. Assume a 40% tax rate unless told otherwise, and state that assumption upfront.</div>\n<div><div>Ответ (RU)</div>ОПУ → ОДДС → баланс, чтобы в конце проверить, что баланс сходится. Ставка налога 40%, если не сказано иное, — и об этом нужно сказать в начале ответа.</div>\n<div><div>Пояснение</div>40% — удобная учебная ставка (реальная федеральная ставка в США сейчас 21%, в России налог на прибыль 25% с 2025 года). Если интервьюер задаёт другую ставку, просто пересчитай.</div>\n</div>"}, {"id": 1790385598257, "topic": "620f982081e3e73e", "sec": "IB Accounting (BIWS) EN-RU::1. Key Rules — Ключевые правила", "q": "Key Rules · Ключевые правила What are the 4 categories of changes on the financial statements? Какие 4 категории изменений в отчётах выделяет гайд?", "a": ["Answer (EN) (1) True cash items on the IS (Revenue, COGS, OpEx, Interest): Net Income, Cash and Retained Earnings change. (2) Non-cash or re-classified IS items (Depreciation, Amortization, SBC, Gains/Losses, Write-Downs): same, plus one more BS item. (3) Operational BS items (AR, Inventory, AP, Accrued Expenses, Prepaid, Deferred Revenue): may or may not hit the IS. (4) Non-operational BS/CFS items (investments, CapEx, debt, stock, dividends): only Cash and the related BS item change. Ответ (RU) (1) Денежные статьи ОПУ (выручка, себестоимость, операционные расходы, проценты): меняются чистая прибыль, деньги, нераспределённая прибыль. (2) Неденежные или переклассифицируемые статьи ОПУ (амортизация, SBC, прибыль/убыток от продажи, списания): то же плюс ещё одна статья баланса. (3) Операционные статьи баланса (дебиторка, запасы, кредиторка, начисления, РБП, авансы полученные): могут влиять или не влиять на ОПУ. (4) Неоперационные статьи (инвестиции, капвложения, долг, акции, дивиденды): меняются только деньги и соответствующая статья баланса. Пояснение Если ты сначала определишь категорию, ответ на любой сценарий строится почти автоматически. Например, «дивиденды» — категория 4: ОПУ не трогаем, деньги и нераспределённая прибыль −100."], "frontHtml": "<div><div>Key Rules · Ключевые правила</div>\n<div>What are the 4 categories of changes on the financial statements?</div>\n<div>Какие 4 категории изменений в отчётах выделяет гайд?</div></div>", "backHtml": "<div>\n\n<div><div>Answer (EN)</div>(1) True cash items on the IS (Revenue, COGS, OpEx, Interest): Net Income, Cash and Retained Earnings change. (2) Non-cash or re-classified IS items (Depreciation, Amortization, SBC, Gains/Losses, Write-Downs): same, plus one more BS item. (3) Operational BS items (AR, Inventory, AP, Accrued Expenses, Prepaid, Deferred Revenue): may or may not hit the IS. (4) Non-operational BS/CFS items (investments, CapEx, debt, stock, dividends): only Cash and the related BS item change.</div>\n<div><div>Ответ (RU)</div>(1) Денежные статьи ОПУ (выручка, себестоимость, операционные расходы, проценты): меняются чистая прибыль, деньги, нераспределённая прибыль. (2) Неденежные или переклассифицируемые статьи ОПУ (амортизация, SBC, прибыль/убыток от продажи, списания): то же плюс ещё одна статья баланса. (3) Операционные статьи баланса (дебиторка, запасы, кредиторка, начисления, РБП, авансы полученные): могут влиять или не влиять на ОПУ. (4) Неоперационные статьи (инвестиции, капвложения, долг, акции, дивиденды): меняются только деньги и соответствующая статья баланса.</div>\n<div><div>Пояснение</div>Если ты сначала определишь категорию, ответ на любой сценарий строится почти автоматически. Например, «дивиденды» — категория 4: ОПУ не трогаем, деньги и нераспределённая прибыль −100.</div>\n</div>"}, {"id": 1790385598259, "topic": "620f982081e3e73e", "sec": "IB Accounting (BIWS) EN-RU::1. Key Rules — Ключевые правила", "q": "Key Rules · Ключевые правила Why is the rule 'CFO = current items, CFI = long-term assets, CFF = long-term liabilities & equity' not accurate? Почему правило «CFO — оборотные статьи, CFI — внеоборотные, CFF — долгосрочные обязательства и капитал» неточное?", "a": ["Answer (EN) There are many exceptions: Deferred Revenue is often long-term but goes in CFO (customer payments); Short-Term Investments are current but go in CFI; the Revolver is a current liability but goes in CFF. Classify by type of activity, not by BS category. Ответ (RU) Много исключений: Deferred Revenue часто долгосрочная, но идёт в операционный поток (это платежи клиентов); краткосрочные инвестиции — оборотный актив, но в инвестиционном потоке; револьверный кредит — краткосрочное обязательство, но в финансовом потоке. Классифицировать нужно по виду деятельности, а не по разделу баланса. Пояснение Revolver (revolving credit facility) — возобновляемая кредитная линия, «кредитная карта» компании. Российский аналог — возобновляемая кредитная линия в банке."], "frontHtml": "<div><div>Key Rules · Ключевые правила</div>\n<div>Why is the rule &#x27;CFO = current items, CFI = long-term assets, CFF = long-term liabilities &amp; equity&#x27; not accurate?</div>\n<div>Почему правило «CFO — оборотные статьи, CFI — внеоборотные, CFF — долгосрочные обязательства и капитал» неточное?</div></div>", "backHtml": "<div>\n\n<div><div>Answer (EN)</div>There are many exceptions: Deferred Revenue is often long-term but goes in CFO (customer payments); Short-Term Investments are current but go in CFI; the Revolver is a current liability but goes in CFF. Classify by type of activity, not by BS category.</div>\n<div><div>Ответ (RU)</div>Много исключений: Deferred Revenue часто долгосрочная, но идёт в операционный поток (это платежи клиентов); краткосрочные инвестиции — оборотный актив, но в инвестиционном потоке; револьверный кредит — краткосрочное обязательство, но в финансовом потоке. Классифицировать нужно по виду деятельности, а не по разделу баланса.</div>\n<div><div>Пояснение</div>Revolver (revolving credit facility) — возобновляемая кредитная линия, «кредитная карта» компании. Российский аналог — возобновляемая кредитная линия в банке.</div>\n</div>"}, {"id": 1790385598261, "topic": "620f982081e3e73e", "sec": "IB Accounting (BIWS) EN-RU::1. Key Rules — Ключевые правила", "q": "Key Rules · Ключевые правила Why do you subtract a Gain on the sale of PP&E in Cash Flow from Operations if it's real cash? Почему прибыль от продажи ОС вычитают из операционного потока, если это реальные деньги?", "a": ["Answer (EN) Because you re-classify it: the full sale proceeds are shown in Cash Flow from Investing, so the gain is removed from CFO to avoid double-counting. Ответ (RU) Это переклассификация: вся выручка от продажи показывается в инвестиционном потоке, поэтому прибыль убирают из операционного, чтобы не учесть её дважды. Пояснение Пример: ОС продано за $120 при стоимости $100. В CFI — $120, в CFO — минус $20 прибыли. Иначе $20 попали бы в деньги дважды: через чистую прибыль и через CFI."], "frontHtml": "<div><div>Key Rules · Ключевые правила</div>\n<div>Why do you subtract a Gain on the sale of PP&amp;E in Cash Flow from Operations if it&#x27;s real cash?</div>\n<div>Почему прибыль от продажи ОС вычитают из операционного потока, если это реальные деньги?</div></div>", "backHtml": "<div>\n\n<div><div>Answer (EN)</div>Because you re-classify it: the full sale proceeds are shown in Cash Flow from Investing, so the gain is removed from CFO to avoid double-counting.</div>\n<div><div>Ответ (RU)</div>Это переклассификация: вся выручка от продажи показывается в инвестиционном потоке, поэтому прибыль убирают из операционного, чтобы не учесть её дважды.</div>\n<div><div>Пояснение</div>Пример: ОС продано за $120 при стоимости $100. В CFI — $120, в CFO — минус $20 прибыли. Иначе $20 попали бы в деньги дважды: через чистую прибыль и через CFI.</div>\n</div>"}, {"id": 1790385598263, "topic": "620f982081e3e73e", "sec": "IB Accounting (BIWS) EN-RU::1. Key Rules — Ключевые правила", "q": "Key Rules · Ключевые правила What are the 7 steps to link the 3 statements? Какие 7 шагов связывания трёх отчётов?", "a": ["Answer (EN) (1) Net Income becomes the top of the CFS. (2) Add back non-cash expenses and flip signs of gains/losses. (3) Reflect changes in operational BS items (Asset up → cash down, Liability up → cash up). (4) Investments and PP&E purchases/sales in CFI. (5) Dividends, debt and shares in CFF. (6) Net change in cash links to Cash on the next BS. (7) Update the BS for Cash, Debt, Equity, Investments, PP&E, etc. Ответ (RU) (1) Чистая прибыль — первая строка ОДДС. (2) Прибавить неденежные расходы, развернуть знак у прибылей/убытков от продаж. (3) Отразить изменения операционных статей баланса (актив растёт → деньги уменьшаются, обязательство растёт → деньги растут). (4) Покупка/продажа инвестиций и ОС — в инвестиционном потоке. (5) Дивиденды, долг, акции — в финансовом. (6) Изменение денег связать со строкой «Деньги» следующего баланса. (7) Обновить баланс: деньги, долг, капитал, инвестиции, ОС и т. д. Пояснение Это алгоритм построения трёхфакторной модели (3-statement model) — основы любой финансовой модели в IB. Плюс три универсальных правила: каждую статью баланса отражать в ОДДС ровно один раз; рост актива уменьшает деньги, рост обязательства увеличивает; баланс всегда сходится."], "frontHtml": "<div><div>Key Rules · Ключевые правила</div>\n<div>What are the 7 steps to link the 3 statements?</div>\n<div>Какие 7 шагов связывания трёх отчётов?</div></div>", "backHtml": "<div>\n\n<div><div>Answer (EN)</div>(1) Net Income becomes the top of the CFS. (2) Add back non-cash expenses and flip signs of gains/losses. (3) Reflect changes in operational BS items (Asset up → cash down, Liability up → cash up). (4) Investments and PP&amp;E purchases/sales in CFI. (5) Dividends, debt and shares in CFF. (6) Net change in cash links to Cash on the next BS. (7) Update the BS for Cash, Debt, Equity, Investments, PP&amp;E, etc.</div>\n<div><div>Ответ (RU)</div>(1) Чистая прибыль — первая строка ОДДС. (2) Прибавить неденежные расходы, развернуть знак у прибылей/убытков от продаж. (3) Отразить изменения операционных статей баланса (актив растёт → деньги уменьшаются, обязательство растёт → деньги растут). (4) Покупка/продажа инвестиций и ОС — в инвестиционном потоке. (5) Дивиденды, долг, акции — в финансовом. (6) Изменение денег связать со строкой «Деньги» следующего баланса. (7) Обновить баланс: деньги, долг, капитал, инвестиции, ОС и т. д.</div>\n<div><div>Пояснение</div>Это алгоритм построения трёхфакторной модели (3-statement model) — основы любой финансовой модели в IB. Плюс три универсальных правила: каждую статью баланса отражать в ОДДС ровно один раз; рост актива уменьшает деньги, рост обязательства увеличивает; баланс всегда сходится.</div>\n</div>"}, {"id": 1790385598265, "topic": "620f982081e3e73e", "sec": "IB Accounting (BIWS) EN-RU::1. Key Rules — Ключевые правила", "q": "Key Rules · Ключевые правила What is Goodwill, and how is it different from Other Intangible Assets? Что такое гудвил и чем он отличается от прочих нематериальных активов?", "a": ["Answer (EN) Goodwill is the premium paid over the target's Shareholders' Equity (book value) in an acquisition. It is not amortized; it stays constant unless impaired. Other Intangible Assets (patents, trademarks, IP), usually from acquisitions, amortize (decrease) over time as they 'expire'. Ответ (RU) Гудвил — премия, уплаченная сверх собственного капитала (балансовой стоимости) покупаемой компании. Он не амортизируется и не меняется, пока не обесценится. Прочие нематериальные активы (патенты, товарные знаки, IP), обычно тоже из приобретений, амортизируются со временем, по мере «истечения». Пояснение В российском учёте гудвил называется «деловая репутация». Амортизация нематериальных активов — это amortization, а материальных — depreciation; в русском это одно слово «амортизация»."], "frontHtml": "<div><div>Key Rules · Ключевые правила</div>\n<div>What is Goodwill, and how is it different from Other Intangible Assets?</div>\n<div>Что такое гудвил и чем он отличается от прочих нематериальных активов?</div></div>", "backHtml": "<div>\n\n<div><div>Answer (EN)</div>Goodwill is the premium paid over the target&#x27;s Shareholders&#x27; Equity (book value) in an acquisition. It is not amortized; it stays constant unless impaired. Other Intangible Assets (patents, trademarks, IP), usually from acquisitions, amortize (decrease) over time as they &#x27;expire&#x27;.</div>\n<div><div>Ответ (RU)</div>Гудвил — премия, уплаченная сверх собственного капитала (балансовой стоимости) покупаемой компании. Он не амортизируется и не меняется, пока не обесценится. Прочие нематериальные активы (патенты, товарные знаки, IP), обычно тоже из приобретений, амортизируются со временем, по мере «истечения».</div>\n<div><div>Пояснение</div>В российском учёте гудвил называется «деловая репутация». Амортизация нематериальных активов — это amortization, а материальных — depreciation; в русском это одно слово «амортизация».</div>\n</div>"}, {"id": 1790385598267, "topic": "620f982081e3e73e", "sec": "IB Accounting (BIWS) EN-RU::1. Key Rules — Ключевые правила", "q": "Key Rules · Ключевые правила Match the Russian terms: Accounts Receivable, Accounts Payable, Deferred Revenue, Prepaid Expenses, Accrued Expenses, Accumulated Depreciation, Retained Earnings, PP&E. Сопоставьте англоязычные статьи с российскими терминами.", "a": ["Answer (EN) AR — receivables owed by customers; AP — payables to suppliers; Deferred Revenue — cash received before delivery; Prepaid Expenses — expenses paid in advance; Accrued Expenses — expenses recognized but not paid (wages, rent); Accumulated Depreciation — contra-asset reducing PP&E; Retained Earnings — saved after-tax profits; PP&E — fixed assets. Ответ (RU) AR — дебиторская задолженность (Дебиторы); AP — кредиторская задолженность (Кредиторы); Deferred Revenue — авансы полученные / доходы будущих периодов; Prepaid Expenses — расходы будущих периодов (РБП) / авансы выданные; Accrued Expenses — начисленные обязательства (задолженность по зарплате, аренде); Accumulated Depreciation — накопленная амортизация (счёт 02, контрактивный); Retained Earnings — нераспределённая прибыль (84); PP&E — основные средства (01). Пояснение Именно этими счетами ты пользовался в главе 7 Молчанова. Связка терминов пригодится и в кейсах, и при чтении отчётности по МСФО на английском."], "frontHtml": "<div><div>Key Rules · Ключевые правила</div>\n<div>Match the Russian terms: Accounts Receivable, Accounts Payable, Deferred Revenue, Prepaid Expenses, Accrued Expenses, Accumulated Depreciation, Retained Earnings, PP&amp;E.</div>\n<div>Сопоставьте англоязычные статьи с российскими терминами.</div></div>", "backHtml": "<div>\n\n<div><div>Answer (EN)</div>AR — receivables owed by customers; AP — payables to suppliers; Deferred Revenue — cash received before delivery; Prepaid Expenses — expenses paid in advance; Accrued Expenses — expenses recognized but not paid (wages, rent); Accumulated Depreciation — contra-asset reducing PP&amp;E; Retained Earnings — saved after-tax profits; PP&amp;E — fixed assets.</div>\n<div><div>Ответ (RU)</div>AR — дебиторская задолженность (Дебиторы); AP — кредиторская задолженность (Кредиторы); Deferred Revenue — авансы полученные / доходы будущих периодов; Prepaid Expenses — расходы будущих периодов (РБП) / авансы выданные; Accrued Expenses — начисленные обязательства (задолженность по зарплате, аренде); Accumulated Depreciation — накопленная амортизация (счёт 02, контрактивный); Retained Earnings — нераспределённая прибыль (84); PP&amp;E — основные средства (01).</div>\n<div><div>Пояснение</div>Именно этими счетами ты пользовался в главе 7 Молчанова. Связка терминов пригодится и в кейсах, и при чтении отчётности по МСФО на английском.</div>\n</div>"}, {"id": 1790385598269, "topic": "620f982081e3e73e", "sec": "IB Accounting (BIWS) EN-RU::1. Key Rules — Ключевые правила", "q": "Key Rules · Ключевые правила What do Common Stock & APIC and Treasury Stock represent? Do they change when the share price changes? Что означают Common Stock & APIC и Treasury Stock? Меняются ли они при изменении цены акций?", "a": ["Answer (EN) Common Stock & APIC = market value of shares at the time they were issued. Treasury Stock = cumulative value of shares the company has repurchased. Neither changes when the share price changes afterward. Ответ (RU) Common Stock & APIC — рыночная стоимость акций на момент их выпуска (уставный капитал + добавочный/эмиссионный доход). Treasury Stock — накопленная стоимость выкупленных компанией собственных акций. Ни то ни другое не меняется при последующем изменении цены акций. Пояснение Treasury Stock уменьшает капитал (показывается со знаком минус). В России аналог — «собственные акции, выкупленные у акционеров» (счёт 81)."], "frontHtml": "<div><div>Key Rules · Ключевые правила</div>\n<div>What do Common Stock &amp; APIC and Treasury Stock represent? Do they change when the share price changes?</div>\n<div>Что означают Common Stock &amp; APIC и Treasury Stock? Меняются ли они при изменении цены акций?</div></div>", "backHtml": "<div>\n\n<div><div>Answer (EN)</div>Common Stock &amp; APIC = market value of shares at the time they were issued. Treasury Stock = cumulative value of shares the company has repurchased. Neither changes when the share price changes afterward.</div>\n<div><div>Ответ (RU)</div>Common Stock &amp; APIC — рыночная стоимость акций на момент их выпуска (уставный капитал + добавочный/эмиссионный доход). Treasury Stock — накопленная стоимость выкупленных компанией собственных акций. Ни то ни другое не меняется при последующем изменении цены акций.</div>\n<div><div>Пояснение</div>Treasury Stock уменьшает капитал (показывается со знаком минус). В России аналог — «собственные акции, выкупленные у акционеров» (счёт 81).</div>\n</div>"}, {"id": 1790385598271, "topic": "620f982081e3e73e", "sec": "IB Accounting (BIWS) EN-RU::1. Key Rules — Ключевые правила", "q": "Key Rules · Ключевые правила What is Accumulated Other Comprehensive Income (AOCI)? Что такое AOCI (накопленный прочий совокупный доход)?", "a": ["Answer (EN) A section of Shareholders' Equity for 'miscellaneous saved-up income', such as foreign currency translation effects and unrealized gains/losses on certain securities (e.g. Available-for-Sale) that haven't been sold yet. Ответ (RU) Раздел капитала для «прочего накопленного дохода»: эффекты пересчёта валют и нереализованные прибыли/убытки по некоторым ценным бумагам (например, AFS), которые ещё не проданы. Пояснение Логика: такие переоценки ещё не реализованы и могут развернуться, поэтому их не пропускают через ОПУ, а копят прямо в капитале. В российском учёте ближайший аналог — добавочный капитал в части переоценки."], "frontHtml": "<div><div>Key Rules · Ключевые правила</div>\n<div>What is Accumulated Other Comprehensive Income (AOCI)?</div>\n<div>Что такое AOCI (накопленный прочий совокупный доход)?</div></div>", "backHtml": "<div>\n\n<div><div>Answer (EN)</div>A section of Shareholders&#x27; Equity for &#x27;miscellaneous saved-up income&#x27;, such as foreign currency translation effects and unrealized gains/losses on certain securities (e.g. Available-for-Sale) that haven&#x27;t been sold yet.</div>\n<div><div>Ответ (RU)</div>Раздел капитала для «прочего накопленного дохода»: эффекты пересчёта валют и нереализованные прибыли/убытки по некоторым ценным бумагам (например, AFS), которые ещё не проданы.</div>\n<div><div>Пояснение</div>Логика: такие переоценки ещё не реализованы и могут развернуться, поэтому их не пропускают через ОПУ, а копят прямо в капитале. В российском учёте ближайший аналог — добавочный капитал в части переоценки.</div>\n</div>"}, {"id": 1790385598273, "topic": "620f982081e3e73e", "sec": "IB Accounting (BIWS) EN-RU::1. Key Rules — Ключевые правила", "q": "Key Rules · Ключевые правила Use cash timing and delivery timing to explain AR, Deferred Revenue, Prepaid Expenses and AP. Объясните AR, Deferred Revenue, Prepaid Expenses и AP через два вопроса: деньги уже прошли? услуга уже оказана?", "a": ["Answer (EN) Revenue side: delivered but not collected → AR (Asset); collected but not delivered → Deferred Revenue (Liability). Expense side: paid but not received → Prepaid Expenses (Asset); received but not paid → AP / Accrued Expenses (Liability). Ответ (RU) Сторона доходов: услугу оказали, деньги не получили → AR (актив); деньги получили, услугу не оказали → Deferred Revenue (обязательство). Сторона расходов: заплатили, но не получили → Prepaid Expenses (актив); получили, но не заплатили → AP / Accrued Expenses (обязательство). Пояснение Это матрица 2×2, в которую укладываются все четыре операционные статьи. Мнемоника: кто кому должен? Если нам должны (деньги или услугу) — это актив. Если мы должны — обязательство."], "frontHtml": "<div><div>Key Rules · Ключевые правила</div>\n<div>Use cash timing and delivery timing to explain AR, Deferred Revenue, Prepaid Expenses and AP.</div>\n<div>Объясните AR, Deferred Revenue, Prepaid Expenses и AP через два вопроса: деньги уже прошли? услуга уже оказана?</div></div>", "backHtml": "<div>\n\n<div><div>Answer (EN)</div>Revenue side: delivered but not collected → AR (Asset); collected but not delivered → Deferred Revenue (Liability). Expense side: paid but not received → Prepaid Expenses (Asset); received but not paid → AP / Accrued Expenses (Liability).</div>\n<div><div>Ответ (RU)</div>Сторона доходов: услугу оказали, деньги не получили → AR (актив); деньги получили, услугу не оказали → Deferred Revenue (обязательство). Сторона расходов: заплатили, но не получили → Prepaid Expenses (актив); получили, но не заплатили → AP / Accrued Expenses (обязательство).</div>\n<div><div>Пояснение</div>Это матрица 2×2, в которую укладываются все четыре операционные статьи. Мнемоника: кто кому должен? Если нам должны (деньги или услугу) — это актив. Если мы должны — обязательство.</div>\n</div>"}, {"id": 1790385598275, "topic": "620f982081e3e73e", "sec": "IB Accounting (BIWS) EN-RU::1. Key Rules — Ключевые правила", "q": "Key Rules · Ключевые правила What is a Revolver? Что такое Revolver?", "a": ["Answer (EN) A revolving credit facility — like a 'credit card' for a company: it borrows money as needed and must repay it quickly. It is a current liability but appears in Cash Flow from Financing. Ответ (RU) Возобновляемая кредитная линия — «кредитная карта» компании: берёт деньги по мере необходимости и должна быстро вернуть. Это краткосрочное обязательство, но в ОДДС отражается в финансовом потоке. Пояснение В моделях LBO revolver часто используется как «балансирующая» статья: если денег не хватает, модель автоматически берёт их из револьвера."], "frontHtml": "<div><div>Key Rules · Ключевые правила</div>\n<div>What is a Revolver?</div>\n<div>Что такое Revolver?</div></div>", "backHtml": "<div>\n\n<div><div>Answer (EN)</div>A revolving credit facility — like a &#x27;credit card&#x27; for a company: it borrows money as needed and must repay it quickly. It is a current liability but appears in Cash Flow from Financing.</div>\n<div><div>Ответ (RU)</div>Возобновляемая кредитная линия — «кредитная карта» компании: берёт деньги по мере необходимости и должна быстро вернуть. Это краткосрочное обязательство, но в ОДДС отражается в финансовом потоке.</div>\n<div><div>Пояснение</div>В моделях LBO revolver часто используется как «балансирующая» статья: если денег не хватает, модель автоматически берёт их из револьвера.</div>\n</div>"}, {"id": 1790385598277, "topic": "620f982081e3e73e", "sec": "IB Accounting (BIWS) EN-RU::2. Basic Concepts — Базовые понятия", "q": "Basic Concepts · Базовые понятия Walk me through the 3 financial statements. Расскажите о трёх финансовых отчётах.", "a": ["Answer (EN) The Income Statement shows revenue, expenses and taxes over a period and ends with Net Income. The Balance Sheet shows Assets, Liabilities and Shareholders' Equity at a specific point in time; Assets = Liabilities + Equity. The Cash Flow Statement starts with Net Income, adjusts for non-cash items and changes in operating assets and liabilities, then adds cash from Investing and Financing activities to get the net change in cash. Ответ (RU) Отчёт о прибылях и убытках (ОПУ) показывает выручку, расходы и налоги за период и заканчивается чистой прибылью. Баланс показывает активы, обязательства и собственный капитал на конкретную дату; активы = обязательства + капитал. Отчёт о движении денежных средств (ОДДС) начинается с чистой прибыли, корректирует её на неденежные статьи и изменения оборотных статей, затем добавляет инвестиционные и финансовые потоки — в итоге получается изменение денег за период. Пояснение Главное различие: ОПУ и ОДДС — это «кино» за период, а баланс — «фотография» на дату. Это ровно те три отчёта, которые ты составлял в задачах 7-3 и 7-4 Молчанова (ОФР, ОДДС, баланс). На собеседовании это разминка: отвечай за 30–40 секунд, по одному-два предложения на отчёт, без лишних деталей."], "frontHtml": "<div><div>Basic Concepts · Базовые понятия</div>\n<div>Walk me through the 3 financial statements.</div>\n<div>Расскажите о трёх финансовых отчётах.</div></div>", "backHtml": "<div>\n\n<div><div>Answer (EN)</div>The Income Statement shows revenue, expenses and taxes over a period and ends with Net Income. The Balance Sheet shows Assets, Liabilities and Shareholders&#x27; Equity at a specific point in time; Assets = Liabilities + Equity. The Cash Flow Statement starts with Net Income, adjusts for non-cash items and changes in operating assets and liabilities, then adds cash from Investing and Financing activities to get the net change in cash.</div>\n<div><div>Ответ (RU)</div>Отчёт о прибылях и убытках (ОПУ) показывает выручку, расходы и налоги за период и заканчивается чистой прибылью. Баланс показывает активы, обязательства и собственный капитал на конкретную дату; активы = обязательства + капитал. Отчёт о движении денежных средств (ОДДС) начинается с чистой прибыли, корректирует её на неденежные статьи и изменения оборотных статей, затем добавляет инвестиционные и финансовые потоки — в итоге получается изменение денег за период.</div>\n<div><div>Пояснение</div>Главное различие: ОПУ и ОДДС — это «кино» за период, а баланс — «фотография» на дату. Это ровно те три отчёта, которые ты составлял в задачах 7-3 и 7-4 Молчанова (ОФР, ОДДС, баланс). На собеседовании это разминка: отвечай за 30–40 секунд, по одному-два предложения на отчёт, без лишних деталей.</div>\n</div>"}, {"id": 1790385598279, "topic": "620f982081e3e73e", "sec": "IB Accounting (BIWS) EN-RU::2. Basic Concepts — Базовые понятия", "q": "Basic Concepts · Базовые понятия Can you give examples of major line items on each of the financial statements? Назовите основные статьи каждого отчёта.", "a": ["Answer (EN) IS: Revenue, COGS, SG&A, Operating Income, Pre-Tax Income, Net Income. BS: Cash, Accounts Receivable, Inventory, PP&E, Accounts Payable, Accrued Expenses, Debt, Shareholders' Equity. CFS: CFO (Net Income, D&A, Stock-Based Compensation, changes in operating assets & liabilities), CFI (CapEx, sale of PP&E, purchase/sale of investments), CFF (dividends, debt raised/repaid, shares issued/repurchased). Ответ (RU) ОПУ: выручка, себестоимость, коммерческие и управленческие расходы, операционная прибыль, прибыль до налога, чистая прибыль. Баланс: деньги, дебиторская задолженность, запасы, основные средства, кредиторская задолженность, начисленные обязательства, долг, капитал. ОДДС: операционный поток (чистая прибыль, амортизация, вознаграждение акциями, изменения оборотного капитала), инвестиционный (капвложения, продажа ОС, покупка/продажа инвестиций), финансовый (дивиденды, привлечение/погашение долга, выпуск/выкуп акций). Пояснение Расшифровка сокращений: COGS (Cost of Goods Sold) — себестоимость продаж; SG&A (Selling, General & Administrative) — коммерческие и управленческие расходы; PP&E (Plants, Property & Equipment) — основные средства; D&A — амортизация ОС и нематериальных активов; CapEx (Capital Expenditures) — капитальные вложения, т. е. покупка ОС; CFO / CFI / CFF — денежный поток от операционной / инвестиционной / финансовой деятельности."], "frontHtml": "<div><div>Basic Concepts · Базовые понятия</div>\n<div>Can you give examples of major line items on each of the financial statements?</div>\n<div>Назовите основные статьи каждого отчёта.</div></div>", "backHtml": "<div>\n\n<div><div>Answer (EN)</div>IS: Revenue, COGS, SG&amp;A, Operating Income, Pre-Tax Income, Net Income. BS: Cash, Accounts Receivable, Inventory, PP&amp;E, Accounts Payable, Accrued Expenses, Debt, Shareholders&#x27; Equity. CFS: CFO (Net Income, D&amp;A, Stock-Based Compensation, changes in operating assets &amp; liabilities), CFI (CapEx, sale of PP&amp;E, purchase/sale of investments), CFF (dividends, debt raised/repaid, shares issued/repurchased).</div>\n<div><div>Ответ (RU)</div>ОПУ: выручка, себестоимость, коммерческие и управленческие расходы, операционная прибыль, прибыль до налога, чистая прибыль. Баланс: деньги, дебиторская задолженность, запасы, основные средства, кредиторская задолженность, начисленные обязательства, долг, капитал. ОДДС: операционный поток (чистая прибыль, амортизация, вознаграждение акциями, изменения оборотного капитала), инвестиционный (капвложения, продажа ОС, покупка/продажа инвестиций), финансовый (дивиденды, привлечение/погашение долга, выпуск/выкуп акций).</div>\n<div><div>Пояснение</div>Расшифровка сокращений: COGS (Cost of Goods Sold) — себестоимость продаж; SG&amp;A (Selling, General &amp; Administrative) — коммерческие и управленческие расходы; PP&amp;E (Plants, Property &amp; Equipment) — основные средства; D&amp;A — амортизация ОС и нематериальных активов; CapEx (Capital Expenditures) — капитальные вложения, т. е. покупка ОС; CFO / CFI / CFF — денежный поток от операционной / инвестиционной / финансовой деятельности.</div>\n</div>"}, {"id": 1790385598281, "topic": "620f982081e3e73e", "sec": "IB Accounting (BIWS) EN-RU::2. Basic Concepts — Базовые понятия", "q": "Basic Concepts · Базовые понятия How do the 3 statements link together? Как три отчёта связаны между собой?", "a": ["Answer (EN) Net Income from the IS becomes the top line of the CFS. You add back non-cash charges like D&A and reflect changes in operating Balance Sheet items to get Cash Flow from Operations. Then you add investing and financing cash flows to get the net change in cash. Ending Cash on the BS = beginning Cash + net change in cash. Net Income also flows into Retained Earnings in Shareholders' Equity, so Assets still equal Liabilities + Equity. Ответ (RU) Чистая прибыль из ОПУ становится первой строкой ОДДС. К ней прибавляют неденежные расходы (амортизацию) и учитывают изменения оборотных статей баланса — получается операционный поток. Затем добавляют инвестиционный и финансовый потоки — получается изменение денег. Деньги на конец периода в балансе = деньги на начало + изменение денег из ОДДС. Чистая прибыль также попадает в нераспределённую прибыль в капитале, поэтому баланс сходится. Пояснение Самый важный вопрос раздела. Запомни два «моста»: (1) чистая прибыль идёт одновременно в верх ОДДС и в нераспределённую прибыль баланса; (2) итог ОДДС (изменение денег) идёт в строку «Деньги» баланса. Всё остальное — детали. Если ты понимаешь эти два моста, ты сможешь пройти любой сценарий «что происходит в трёх отчётах»."], "frontHtml": "<div><div>Basic Concepts · Базовые понятия</div>\n<div>How do the 3 statements link together?</div>\n<div>Как три отчёта связаны между собой?</div></div>", "backHtml": "<div>\n\n<div><div>Answer (EN)</div>Net Income from the IS becomes the top line of the CFS. You add back non-cash charges like D&amp;A and reflect changes in operating Balance Sheet items to get Cash Flow from Operations. Then you add investing and financing cash flows to get the net change in cash. Ending Cash on the BS = beginning Cash + net change in cash. Net Income also flows into Retained Earnings in Shareholders&#x27; Equity, so Assets still equal Liabilities + Equity.</div>\n<div><div>Ответ (RU)</div>Чистая прибыль из ОПУ становится первой строкой ОДДС. К ней прибавляют неденежные расходы (амортизацию) и учитывают изменения оборотных статей баланса — получается операционный поток. Затем добавляют инвестиционный и финансовый потоки — получается изменение денег. Деньги на конец периода в балансе = деньги на начало + изменение денег из ОДДС. Чистая прибыль также попадает в нераспределённую прибыль в капитале, поэтому баланс сходится.</div>\n<div><div>Пояснение</div>Самый важный вопрос раздела. Запомни два «моста»: (1) чистая прибыль идёт одновременно в верх ОДДС и в нераспределённую прибыль баланса; (2) итог ОДДС (изменение денег) идёт в строку «Деньги» баланса. Всё остальное — детали. Если ты понимаешь эти два моста, ты сможешь пройти любой сценарий «что происходит в трёх отчётах».</div>\n</div>"}, {"id": 1790385598283, "topic": "620f982081e3e73e", "sec": "IB Accounting (BIWS) EN-RU::2. Basic Concepts — Базовые понятия", "q": "Basic Concepts · Базовые понятия If you were stranded on a desert island and only had one financial statement to review a company's overall health, which would you use and why? Если бы у вас был только один отчёт для оценки финансового здоровья компании, какой бы вы выбрали?", "a": ["Answer (EN) The Cash Flow Statement, because it shows how much cash the company actually generates. The Income Statement can be misleading: it includes non-cash expenses and excludes real cash expenses such as Capital Expenditures. True cash flow is the #1 thing you care about. Ответ (RU) ОДДС, потому что он показывает, сколько денег компания реально генерирует. ОПУ может вводить в заблуждение: в нём есть неденежные расходы (амортизация), но нет реальных денежных трат вроде капитальных вложений. Реальный денежный поток — главное, что важно при анализе. Пояснение Вспомни задачу 7-3 Молчанова: компания получила убыток 4080, а денег стало на 5620 больше. Прибыль и деньги могут расходиться очень сильно. Банкиры особенно ценят денежный поток, потому что именно он идёт на обслуживание долга и выплаты акционерам, а в оценке DCF дисконтируют именно денежные потоки."], "frontHtml": "<div><div>Basic Concepts · Базовые понятия</div>\n<div>If you were stranded on a desert island and only had one financial statement to review a company&#x27;s overall health, which would you use and why?</div>\n<div>Если бы у вас был только один отчёт для оценки финансового здоровья компании, какой бы вы выбрали?</div></div>", "backHtml": "<div>\n\n<div><div>Answer (EN)</div>The Cash Flow Statement, because it shows how much cash the company actually generates. The Income Statement can be misleading: it includes non-cash expenses and excludes real cash expenses such as Capital Expenditures. True cash flow is the #1 thing you care about.</div>\n<div><div>Ответ (RU)</div>ОДДС, потому что он показывает, сколько денег компания реально генерирует. ОПУ может вводить в заблуждение: в нём есть неденежные расходы (амортизация), но нет реальных денежных трат вроде капитальных вложений. Реальный денежный поток — главное, что важно при анализе.</div>\n<div><div>Пояснение</div>Вспомни задачу 7-3 Молчанова: компания получила убыток 4080, а денег стало на 5620 больше. Прибыль и деньги могут расходиться очень сильно. Банкиры особенно ценят денежный поток, потому что именно он идёт на обслуживание долга и выплаты акционерам, а в оценке DCF дисконтируют именно денежные потоки.</div>\n</div>"}, {"id": 1790385598285, "topic": "620f982081e3e73e", "sec": "IB Accounting (BIWS) EN-RU::2. Basic Concepts — Базовые понятия", "q": "Basic Concepts · Базовые понятия If you could only look at 2 statements to assess a company's prospects, which 2 would you use and why? Если можно взять только два отчёта — какие и почему?", "a": ["Answer (EN) The Income Statement and the Balance Sheet, because you can build the Cash Flow Statement from them — as long as you have both the beginning and ending Balance Sheets for the same period as the Income Statement. Ответ (RU) ОПУ и баланс, потому что из них можно построить ОДДС — при условии, что есть баланс на начало и на конец того же периода, что и ОПУ. Пояснение Именно это ты делал в задаче 7-3 косвенным методом: взял убыток из ОФР, прибавил амортизацию и изменения дебиторки, запасов и кредиторки из двух балансов — и получил денежный поток 5620. Обрати внимание на ловушку: одного баланса недостаточно, нужны два, чтобы увидеть изменения."], "frontHtml": "<div><div>Basic Concepts · Базовые понятия</div>\n<div>If you could only look at 2 statements to assess a company&#x27;s prospects, which 2 would you use and why?</div>\n<div>Если можно взять только два отчёта — какие и почему?</div></div>", "backHtml": "<div>\n\n<div><div>Answer (EN)</div>The Income Statement and the Balance Sheet, because you can build the Cash Flow Statement from them — as long as you have both the beginning and ending Balance Sheets for the same period as the Income Statement.</div>\n<div><div>Ответ (RU)</div>ОПУ и баланс, потому что из них можно построить ОДДС — при условии, что есть баланс на начало и на конец того же периода, что и ОПУ.</div>\n<div><div>Пояснение</div>Именно это ты делал в задаче 7-3 косвенным методом: взял убыток из ОФР, прибавил амортизацию и изменения дебиторки, запасов и кредиторки из двух балансов — и получил денежный поток 5620. Обрати внимание на ловушку: одного баланса недостаточно, нужны два, чтобы увидеть изменения.</div>\n</div>"}, {"id": 1790385598287, "topic": "620f982081e3e73e", "sec": "IB Accounting (BIWS) EN-RU::2. Basic Concepts — Базовые понятия", "q": "Basic Concepts · Базовые понятия You have a new, unknown item that belongs on the Balance Sheet. How can you tell whether it is an Asset or a Liability? Как понять, актив новая неизвестная статья баланса или обязательство?", "a": ["Answer (EN) Ask which direction cash will move because of it. An Asset results in more cash or potential cash in the future (directly like AR or Investments, or indirectly like PP&E or Goodwill). A Liability results in less cash in the future (directly like Debt or AP, or indirectly like Deferred Revenue, which leads to future taxes and delivery costs). Ответ (RU) Нужно спросить, куда из-за неё будут двигаться деньги. Актив приведёт к притоку денег в будущем (напрямую, как дебиторка или инвестиции, или косвенно, как ОС или гудвил). Обязательство приведёт к оттоку денег в будущем (напрямую, как долг или кредиторка, или косвенно, как полученные авансы, которые потребуют затрат на исполнение и налогов). Пояснение Это то же определение, что в российском учёте: актив — ресурс, который принесёт экономические выгоды, обязательство — то, что приведёт к их оттоку. Правило удобно тем, что работает даже для незнакомых статей: не нужно помнить их наизусть, достаточно подумать о будущих деньгах."], "frontHtml": "<div><div>Basic Concepts · Базовые понятия</div>\n<div>You have a new, unknown item that belongs on the Balance Sheet. How can you tell whether it is an Asset or a Liability?</div>\n<div>Как понять, актив новая неизвестная статья баланса или обязательство?</div></div>", "backHtml": "<div>\n\n<div><div>Answer (EN)</div>Ask which direction cash will move because of it. An Asset results in more cash or potential cash in the future (directly like AR or Investments, or indirectly like PP&amp;E or Goodwill). A Liability results in less cash in the future (directly like Debt or AP, or indirectly like Deferred Revenue, which leads to future taxes and delivery costs).</div>\n<div><div>Ответ (RU)</div>Нужно спросить, куда из-за неё будут двигаться деньги. Актив приведёт к притоку денег в будущем (напрямую, как дебиторка или инвестиции, или косвенно, как ОС или гудвил). Обязательство приведёт к оттоку денег в будущем (напрямую, как долг или кредиторка, или косвенно, как полученные авансы, которые потребуют затрат на исполнение и налогов).</div>\n<div><div>Пояснение</div>Это то же определение, что в российском учёте: актив — ресурс, который принесёт экономические выгоды, обязательство — то, что приведёт к их оттоку. Правило удобно тем, что работает даже для незнакомых статей: не нужно помнить их наизусть, достаточно подумать о будущих деньгах.</div>\n</div>"}, {"id": 1790385598289, "topic": "620f982081e3e73e", "sec": "IB Accounting (BIWS) EN-RU::2. Basic Concepts — Базовые понятия", "q": "Basic Concepts · Базовые понятия How can you tell whether or not an expense should appear on the Income Statement? Как понять, должен ли расход попасть в ОПУ?", "a": ["Answer (EN) Two conditions must both be true: (1) it corresponds to the current period, and (2) it is tax-deductible. Salaries, marketing, Depreciation and Interest Expense meet both. Repaying debt principal does not, because it is not tax-deductible. (Technically 'deductible for book tax purposes'.) Ответ (RU) Должны выполняться два условия одновременно: (1) расход относится к текущему периоду и (2) он уменьшает налогооблагаемую прибыль. Зарплата, маркетинг, амортизация и проценты по долгу соответствуют обоим. Погашение тела кредита — нет, потому что оно не уменьшает налог. Пояснение Это упрощённое правило гайда для американских собеседований, но логика совпадает с методом начисления у Молчанова. Вспомни задачу 7-2: проценты по кредиту (оп. 11) — расход, а возврат кредита (оп. 22) — нет. Амортизация проходит оба условия: это распределение стоимости ОС на текущий период."], "frontHtml": "<div><div>Basic Concepts · Базовые понятия</div>\n<div>How can you tell whether or not an expense should appear on the Income Statement?</div>\n<div>Как понять, должен ли расход попасть в ОПУ?</div></div>", "backHtml": "<div>\n\n<div><div>Answer (EN)</div>Two conditions must both be true: (1) it corresponds to the current period, and (2) it is tax-deductible. Salaries, marketing, Depreciation and Interest Expense meet both. Repaying debt principal does not, because it is not tax-deductible. (Technically &#x27;deductible for book tax purposes&#x27;.)</div>\n<div><div>Ответ (RU)</div>Должны выполняться два условия одновременно: (1) расход относится к текущему периоду и (2) он уменьшает налогооблагаемую прибыль. Зарплата, маркетинг, амортизация и проценты по долгу соответствуют обоим. Погашение тела кредита — нет, потому что оно не уменьшает налог.</div>\n<div><div>Пояснение</div>Это упрощённое правило гайда для американских собеседований, но логика совпадает с методом начисления у Молчанова. Вспомни задачу 7-2: проценты по кредиту (оп. 11) — расход, а возврат кредита (оп. 22) — нет. Амортизация проходит оба условия: это распределение стоимости ОС на текущий период.</div>\n</div>"}, {"id": 1790385598291, "topic": "620f982081e3e73e", "sec": "IB Accounting (BIWS) EN-RU::2. Basic Concepts — Базовые понятия", "q": "Basic Concepts · Базовые понятия You have a non-cash expense (e.g. Depreciation) on the Income Statement. Why do you add back the ENTIRE expense on the Cash Flow Statement? Почему на ОДДС прибавляют всю сумму неденежного расхода, а не только его «посленалоговую» часть?", "a": ["Answer (EN) To reflect the tax savings from the non-cash expense. With a $10 non-cash expense and a 40% tax rate, Net Income falls by $6; adding back the full $10 makes cash go up by $4 — that $4 is the tax saving. Adding back only $6 would imply the expense had no effect on taxes or cash. Ответ (RU) Чтобы отразить экономию на налоге. При неденежном расходе $10 и ставке 40% чистая прибыль падает на $6; прибавляя все $10, получаем рост денег на $4 — это и есть сэкономленный налог. Если прибавить только $6, получится, что расход никак не повлиял на налоги и деньги, а это неверно. Пояснение Логика по шагам: расход $10 → прибыль до налога −$10 → налог −$4 (40% от 10) → чистая прибыль −$6. Денег расход не забрал, а налог мы заплатили на $4 меньше. Значит, денег стало на $4 больше. Технически: −6 (прибыль) + 10 (возврат неденежного расхода) = +4."], "frontHtml": "<div><div>Basic Concepts · Базовые понятия</div>\n<div>You have a non-cash expense (e.g. Depreciation) on the Income Statement. Why do you add back the ENTIRE expense on the Cash Flow Statement?</div>\n<div>Почему на ОДДС прибавляют всю сумму неденежного расхода, а не только его «посленалоговую» часть?</div></div>", "backHtml": "<div>\n\n<div><div>Answer (EN)</div>To reflect the tax savings from the non-cash expense. With a $10 non-cash expense and a 40% tax rate, Net Income falls by $6; adding back the full $10 makes cash go up by $4 — that $4 is the tax saving. Adding back only $6 would imply the expense had no effect on taxes or cash.</div>\n<div><div>Ответ (RU)</div>Чтобы отразить экономию на налоге. При неденежном расходе $10 и ставке 40% чистая прибыль падает на $6; прибавляя все $10, получаем рост денег на $4 — это и есть сэкономленный налог. Если прибавить только $6, получится, что расход никак не повлиял на налоги и деньги, а это неверно.</div>\n<div><div>Пояснение</div>Логика по шагам: расход $10 → прибыль до налога −$10 → налог −$4 (40% от 10) → чистая прибыль −$6. Денег расход не забрал, а налог мы заплатили на $4 меньше. Значит, денег стало на $4 больше. Технически: −6 (прибыль) + 10 (возврат неденежного расхода) = +4.</div>\n</div>"}, {"id": 1790385598293, "topic": "620f982081e3e73e", "sec": "IB Accounting (BIWS) EN-RU::2. Basic Concepts — Базовые понятия", "q": "Basic Concepts · Базовые понятия How do you decide when to capitalize rather than expense a purchase? Когда покупку капитализируют, а когда списывают в расходы?", "a": ["Answer (EN) If the purchase is an Asset with a useful life of over 1 year, it is capitalized (put on the Balance Sheet) and then Depreciated (tangible) or Amortized (intangible) over its life. Factories, equipment and land are capitalized; salaries and COGS 'last' only for the current period, so they are expensed on the IS. Ответ (RU) Если покупка — актив со сроком полезного использования больше года, её капитализируют (ставят на баланс), а затем амортизируют: материальные активы — через depreciation, нематериальные — через amortization. Заводы, оборудование, земля капитализируются; зарплата и себестоимость относятся только к текущему периоду, поэтому сразу идут в расходы. Пояснение Точно как в задаче 7-1: оборудование за 1400 поставили на баланс как ОС и списывали по 50 в месяц, а расклейку плакатов сразу отнесли в расходы. Важно: гайд пишет, что аренду не капитализируют. Это устарело: с 2019 года по МСФО 16 (и по ФСБУ 25 в России) почти все договоры аренды отражаются на балансе как «право пользования активом» и обязательство по аренде."], "frontHtml": "<div><div>Basic Concepts · Базовые понятия</div>\n<div>How do you decide when to capitalize rather than expense a purchase?</div>\n<div>Когда покупку капитализируют, а когда списывают в расходы?</div></div>", "backHtml": "<div>\n\n<div><div>Answer (EN)</div>If the purchase is an Asset with a useful life of over 1 year, it is capitalized (put on the Balance Sheet) and then Depreciated (tangible) or Amortized (intangible) over its life. Factories, equipment and land are capitalized; salaries and COGS &#x27;last&#x27; only for the current period, so they are expensed on the IS.</div>\n<div><div>Ответ (RU)</div>Если покупка — актив со сроком полезного использования больше года, её капитализируют (ставят на баланс), а затем амортизируют: материальные активы — через depreciation, нематериальные — через amortization. Заводы, оборудование, земля капитализируются; зарплата и себестоимость относятся только к текущему периоду, поэтому сразу идут в расходы.</div>\n<div><div>Пояснение</div>Точно как в задаче 7-1: оборудование за 1400 поставили на баланс как ОС и списывали по 50 в месяц, а расклейку плакатов сразу отнесли в расходы. Важно: гайд пишет, что аренду не капитализируют. Это устарело: с 2019 года по МСФО 16 (и по ФСБУ 25 в России) почти все договоры аренды отражаются на балансе как «право пользования активом» и обязательство по аренде.</div>\n</div>"}, {"id": 1790385598295, "topic": "620f982081e3e73e", "sec": "IB Accounting (BIWS) EN-RU::2. Basic Concepts — Базовые понятия", "q": "Basic Concepts · Базовые понятия If Depreciation is a non-cash expense, why does it affect the cash balance? Если амортизация — неденежный расход, почему она влияет на деньги?", "a": ["Answer (EN) Because it is tax-deductible. Higher Depreciation reduces taxable income and therefore the taxes you pay, which increases cash. Lower Depreciation does the opposite. Ответ (RU) Потому что она уменьшает налогооблагаемую прибыль. Больше амортизации — меньше налог — больше денег остаётся у компании. Меньше амортизации — наоборот. Пояснение Сама амортизация деньги не тратит (деньги ушли раньше, при покупке ОС). Но она влияет на деньги через налог: это так называемый «налоговый щит» (tax shield). При ставке 40% каждый доллар амортизации экономит 40 центов налога."], "frontHtml": "<div><div>Basic Concepts · Базовые понятия</div>\n<div>If Depreciation is a non-cash expense, why does it affect the cash balance?</div>\n<div>Если амортизация — неденежный расход, почему она влияет на деньги?</div></div>", "backHtml": "<div>\n\n<div><div>Answer (EN)</div>Because it is tax-deductible. Higher Depreciation reduces taxable income and therefore the taxes you pay, which increases cash. Lower Depreciation does the opposite.</div>\n<div><div>Ответ (RU)</div>Потому что она уменьшает налогооблагаемую прибыль. Больше амортизации — меньше налог — больше денег остаётся у компании. Меньше амортизации — наоборот.</div>\n<div><div>Пояснение</div>Сама амортизация деньги не тратит (деньги ушли раньше, при покупке ОС). Но она влияет на деньги через налог: это так называемый «налоговый щит» (tax shield). При ставке 40% каждый доллар амортизации экономит 40 центов налога.</div>\n</div>"}, {"id": 1790385598297, "topic": "620f982081e3e73e", "sec": "IB Accounting (BIWS) EN-RU::2. Basic Concepts — Базовые понятия", "q": "Basic Concepts · Базовые понятия Where does Depreciation usually appear on the Income Statement? Где обычно отражается амортизация в ОПУ?", "a": ["Answer (EN) It can be a separate line item or embedded in COGS or Operating Expenses — each company does it differently. For interview questions the result is the same: Depreciation always reduces Pre-Tax Income. Ответ (RU) Отдельной строкой или внутри себестоимости / операционных расходов — у каждой компании по-разному. Для вопросов на собеседовании это неважно: амортизация всегда уменьшает прибыль до налога. Пояснение В российской отчётности амортизация обычно «спрятана» в себестоимости и коммерческих/управленческих расходах, отдельной строки в ОФР нет. Поэтому для расчёта EBITDA российских компаний амортизацию берут из ОДДС или пояснений."], "frontHtml": "<div><div>Basic Concepts · Базовые понятия</div>\n<div>Where does Depreciation usually appear on the Income Statement?</div>\n<div>Где обычно отражается амортизация в ОПУ?</div></div>", "backHtml": "<div>\n\n<div><div>Answer (EN)</div>It can be a separate line item or embedded in COGS or Operating Expenses — each company does it differently. For interview questions the result is the same: Depreciation always reduces Pre-Tax Income.</div>\n<div><div>Ответ (RU)</div>Отдельной строкой или внутри себестоимости / операционных расходов — у каждой компании по-разному. Для вопросов на собеседовании это неважно: амортизация всегда уменьшает прибыль до налога.</div>\n<div><div>Пояснение</div>В российской отчётности амортизация обычно «спрятана» в себестоимости и коммерческих/управленческих расходах, отдельной строки в ОФР нет. Поэтому для расчёта EBITDA российских компаний амортизацию берут из ОДДС или пояснений.</div>\n</div>"}, {"id": 1790385598299, "topic": "620f982081e3e73e", "sec": "IB Accounting (BIWS) EN-RU::2. Basic Concepts — Базовые понятия", "q": "Basic Concepts · Базовые понятия Why is the Income Statement not affected by Inventory purchases? Почему покупка запасов не влияет на ОПУ?", "a": ["Answer (EN) Inventory is expensed on the IS (as COGS) only when the goods are manufactured and sold. While it sits in the warehouse, it is an Asset on the Balance Sheet, not an expense. Ответ (RU) Запасы списываются в ОПУ (как себестоимость) только тогда, когда из них произвели и продали товар. Пока они лежат на складе, это актив на балансе, а не расход. Пояснение Это принцип соответствия: расход признаётся в том же периоде, что и выручка, которую он помог получить. У Молчанова: моющие средства в задаче 7-1 при покупке — «Материалы» (актив), в расход — только когда израсходованы (Д-т Расходы К-т Материалы)."], "frontHtml": "<div><div>Basic Concepts · Базовые понятия</div>\n<div>Why is the Income Statement not affected by Inventory purchases?</div>\n<div>Почему покупка запасов не влияет на ОПУ?</div></div>", "backHtml": "<div>\n\n<div><div>Answer (EN)</div>Inventory is expensed on the IS (as COGS) only when the goods are manufactured and sold. While it sits in the warehouse, it is an Asset on the Balance Sheet, not an expense.</div>\n<div><div>Ответ (RU)</div>Запасы списываются в ОПУ (как себестоимость) только тогда, когда из них произвели и продали товар. Пока они лежат на складе, это актив на балансе, а не расход.</div>\n<div><div>Пояснение</div>Это принцип соответствия: расход признаётся в том же периоде, что и выручка, которую он помог получить. У Молчанова: моющие средства в задаче 7-1 при покупке — «Материалы» (актив), в расход — только когда израсходованы (Д-т Расходы К-т Материалы).</div>\n</div>"}, {"id": 1790385598301, "topic": "620f982081e3e73e", "sec": "IB Accounting (BIWS) EN-RU::2. Basic Concepts — Базовые понятия", "q": "Basic Concepts · Базовые понятия Debt repayment shows up in Cash Flow from Financing. Why don't interest payments also show up there? They're a financing activity! Погашение долга — в финансовом потоке. Почему проценты не там же?", "a": ["Answer (EN) Interest corresponds to the current period and is tax-deductible, so it already appeared on the IS and is already inside Net Income at the top of the CFS. Showing it again would double-count it. Debt principal repayment never appeared on the IS, so it must be shown separately in CFF. Ответ (RU) Проценты относятся к текущему периоду и уменьшают налог, поэтому они уже прошли через ОПУ и уже сидят внутри чистой прибыли в начале ОДДС. Показать их ещё раз — значит учесть дважды. Погашение тела долга через ОПУ не проходило, поэтому его нужно показать отдельно в финансовом потоке. Пояснение Общее правило: если статья — реальная денежная трата и уже прошла через ОПУ, в ОДДС её отдельно не показывают (кроме случаев переклассификации). В российском ОДДС уплаченные проценты тоже обычно относятся к текущей деятельности — как ты делал в задаче 7-4. По МСФО компания может выбрать и финансовую деятельность."], "frontHtml": "<div><div>Basic Concepts · Базовые понятия</div>\n<div>Debt repayment shows up in Cash Flow from Financing. Why don&#x27;t interest payments also show up there? They&#x27;re a financing activity!</div>\n<div>Погашение долга — в финансовом потоке. Почему проценты не там же?</div></div>", "backHtml": "<div>\n\n<div><div>Answer (EN)</div>Interest corresponds to the current period and is tax-deductible, so it already appeared on the IS and is already inside Net Income at the top of the CFS. Showing it again would double-count it. Debt principal repayment never appeared on the IS, so it must be shown separately in CFF.</div>\n<div><div>Ответ (RU)</div>Проценты относятся к текущему периоду и уменьшают налог, поэтому они уже прошли через ОПУ и уже сидят внутри чистой прибыли в начале ОДДС. Показать их ещё раз — значит учесть дважды. Погашение тела долга через ОПУ не проходило, поэтому его нужно показать отдельно в финансовом потоке.</div>\n<div><div>Пояснение</div>Общее правило: если статья — реальная денежная трата и уже прошла через ОПУ, в ОДДС её отдельно не показывают (кроме случаев переклассификации). В российском ОДДС уплаченные проценты тоже обычно относятся к текущей деятельности — как ты делал в задаче 7-4. По МСФО компания может выбрать и финансовую деятельность.</div>\n</div>"}, {"id": 1790385598303, "topic": "620f982081e3e73e", "sec": "IB Accounting (BIWS) EN-RU::2. Basic Concepts — Базовые понятия", "q": "Basic Concepts · Базовые понятия What's the difference between Accounts Payable and Accrued Expenses? Чем кредиторская задолженность (AP) отличается от начисленных обязательств (Accrued Expenses)?", "a": ["Answer (EN) Mechanically they are the same: Liabilities for expenses already recorded on the IS but not yet paid in cash, and they affect the statements identically. The difference: AP is mostly for one-time expenses with invoices (e.g. a law firm), while Accrued Expenses are for recurring expenses without invoices (wages, rent, utilities). Ответ (RU) Механически это одно и то же: обязательства по расходам, которые уже признаны в ОПУ, но ещё не оплачены. На отчёты они влияют одинаково. Разница: AP — в основном разовые расходы по счетам (например, юристы), Accrued Expenses — регулярные расходы без счетов (зарплата, аренда, коммунальные). Пояснение В российском учёте оба случая — это кредиторская задолженность (счета 60, 70, 76). У Молчанова в задаче 7-3: начисленная зарплата (оп. 7) — это Accrued Expense, неоплаченный счёт за рекламу (оп. 13) — Accounts Payable. Проводка одна и та же: Д-т Расходы К-т Кредиторы."], "frontHtml": "<div><div>Basic Concepts · Базовые понятия</div>\n<div>What&#x27;s the difference between Accounts Payable and Accrued Expenses?</div>\n<div>Чем кредиторская задолженность (AP) отличается от начисленных обязательств (Accrued Expenses)?</div></div>", "backHtml": "<div>\n\n<div><div>Answer (EN)</div>Mechanically they are the same: Liabilities for expenses already recorded on the IS but not yet paid in cash, and they affect the statements identically. The difference: AP is mostly for one-time expenses with invoices (e.g. a law firm), while Accrued Expenses are for recurring expenses without invoices (wages, rent, utilities).</div>\n<div><div>Ответ (RU)</div>Механически это одно и то же: обязательства по расходам, которые уже признаны в ОПУ, но ещё не оплачены. На отчёты они влияют одинаково. Разница: AP — в основном разовые расходы по счетам (например, юристы), Accrued Expenses — регулярные расходы без счетов (зарплата, аренда, коммунальные).</div>\n<div><div>Пояснение</div>В российском учёте оба случая — это кредиторская задолженность (счета 60, 70, 76). У Молчанова в задаче 7-3: начисленная зарплата (оп. 7) — это Accrued Expense, неоплаченный счёт за рекламу (оп. 13) — Accounts Payable. Проводка одна и та же: Д-т Расходы К-т Кредиторы.</div>\n</div>"}, {"id": 1790385598305, "topic": "620f982081e3e73e", "sec": "IB Accounting (BIWS) EN-RU::2. Basic Concepts — Базовые понятия", "q": "Basic Concepts · Базовые понятия When would a company collect cash from a customer and NOT record it as revenue? Когда компания получает деньги от клиента, но не признаёт выручку?", "a": ["Answer (EN) When the customer pays upfront for months or years of a product/service that hasn't been delivered yet — e.g. web-based subscription software, cell phone annual contracts, magazine subscriptions. Revenue is recorded only when the product/service is delivered. Ответ (RU) Когда клиент платит вперёд за месяцы или годы продукта/услуги, которые ещё не предоставлены: подписка на софт, годовые контракты мобильных операторов, подписка на журналы. Выручка признаётся только по мере оказания услуги. Пояснение Это ровно операция 1 из задачи 7-2: ЗАО «Осел Иа» заплатило аванс 10 за мёд, но выручки нет, пока мёд не отгружен. В проводках: Д-т Деньги К-т Авансы полученные."], "frontHtml": "<div><div>Basic Concepts · Базовые понятия</div>\n<div>When would a company collect cash from a customer and NOT record it as revenue?</div>\n<div>Когда компания получает деньги от клиента, но не признаёт выручку?</div></div>", "backHtml": "<div>\n\n<div><div>Answer (EN)</div>When the customer pays upfront for months or years of a product/service that hasn&#x27;t been delivered yet — e.g. web-based subscription software, cell phone annual contracts, magazine subscriptions. Revenue is recorded only when the product/service is delivered.</div>\n<div><div>Ответ (RU)</div>Когда клиент платит вперёд за месяцы или годы продукта/услуги, которые ещё не предоставлены: подписка на софт, годовые контракты мобильных операторов, подписка на журналы. Выручка признаётся только по мере оказания услуги.</div>\n<div><div>Пояснение</div>Это ровно операция 1 из задачи 7-2: ЗАО «Осел Иа» заплатило аванс 10 за мёд, но выручки нет, пока мёд не отгружен. В проводках: Д-т Деньги К-т Авансы полученные.</div>\n</div>"}, {"id": 1790385598307, "topic": "620f982081e3e73e", "sec": "IB Accounting (BIWS) EN-RU::2. Basic Concepts — Базовые понятия", "q": "Basic Concepts · Базовые понятия If cash collected is not recorded as revenue, what happens to it? Если полученные деньги не признаны выручкой, куда они попадают?", "a": ["Answer (EN) It goes into Deferred Revenue, a Liability on the Balance Sheet. As the product/service is delivered over time, Deferred Revenue decreases and turns into real revenue on the Income Statement. Ответ (RU) В Deferred Revenue (доходы будущих периодов / авансы полученные) — обязательство в балансе. По мере оказания услуги этот остаток уменьшается и превращается в выручку в ОПУ. Пояснение У Молчанова это задача 7-2, операция 12: мёд отгружен, аванс засчитан — Д-т Авансы полученные К-т Выручка. Обязательство уменьшилось, выручка появилась."], "frontHtml": "<div><div>Basic Concepts · Базовые понятия</div>\n<div>If cash collected is not recorded as revenue, what happens to it?</div>\n<div>Если полученные деньги не признаны выручкой, куда они попадают?</div></div>", "backHtml": "<div>\n\n<div><div>Answer (EN)</div>It goes into Deferred Revenue, a Liability on the Balance Sheet. As the product/service is delivered over time, Deferred Revenue decreases and turns into real revenue on the Income Statement.</div>\n<div><div>Ответ (RU)</div>В Deferred Revenue (доходы будущих периодов / авансы полученные) — обязательство в балансе. По мере оказания услуги этот остаток уменьшается и превращается в выручку в ОПУ.</div>\n<div><div>Пояснение</div>У Молчанова это задача 7-2, операция 12: мёд отгружен, аванс засчитан — Д-т Авансы полученные К-т Выручка. Обязательство уменьшилось, выручка появилась.</div>\n</div>"}, {"id": 1790385598309, "topic": "620f982081e3e73e", "sec": "IB Accounting (BIWS) EN-RU::2. Basic Concepts — Базовые понятия", "q": "Basic Concepts · Базовые понятия Deferred Revenue reflects cash we've already collected for a product we haven't delivered. Why is it a Liability? That's great for us! Почему Deferred Revenue — обязательство, если деньги уже у нас?", "a": ["Answer (EN) An Asset results in more future cash and a Liability in less future cash. With Deferred Revenue, we still must deliver the product/service, and when we recognize it as revenue we will pay additional taxes and incur additional expenses. So it implies future cash outflows — a Liability. Ответ (RU) Актив — это будущий приток денег, обязательство — будущий отток. По Deferred Revenue мы ещё должны оказать услугу, а при признании выручки заплатим налог и понесём затраты. Значит, она ведёт к будущему оттоку денег — это обязательство. Пояснение Проще всего думать так: мы должны клиенту — либо услугу, либо деньги назад, если не выполним. Долг перед клиентом ничем не отличается от долга перед банком с точки зрения баланса. Поэтому в российском учёте полученные авансы — кредиторская задолженность."], "frontHtml": "<div><div>Basic Concepts · Базовые понятия</div>\n<div>Deferred Revenue reflects cash we&#x27;ve already collected for a product we haven&#x27;t delivered. Why is it a Liability? That&#x27;s great for us!</div>\n<div>Почему Deferred Revenue — обязательство, если деньги уже у нас?</div></div>", "backHtml": "<div>\n\n<div><div>Answer (EN)</div>An Asset results in more future cash and a Liability in less future cash. With Deferred Revenue, we still must deliver the product/service, and when we recognize it as revenue we will pay additional taxes and incur additional expenses. So it implies future cash outflows — a Liability.</div>\n<div><div>Ответ (RU)</div>Актив — это будущий приток денег, обязательство — будущий отток. По Deferred Revenue мы ещё должны оказать услугу, а при признании выручки заплатим налог и понесём затраты. Значит, она ведёт к будущему оттоку денег — это обязательство.</div>\n<div><div>Пояснение</div>Проще всего думать так: мы должны клиенту — либо услугу, либо деньги назад, если не выполним. Долг перед клиентом ничем не отличается от долга перед банком с точки зрения баланса. Поэтому в российском учёте полученные авансы — кредиторская задолженность.</div>\n</div>"}, {"id": 1790385598311, "topic": "620f982081e3e73e", "sec": "IB Accounting (BIWS) EN-RU::2. Basic Concepts — Базовые понятия", "q": "Basic Concepts · Базовые понятия What's the difference between Accounts Receivable and Deferred Revenue? Чем дебиторская задолженность (AR) отличается от Deferred Revenue?", "a": ["Answer (EN) (1) AR has not been collected in cash yet; Deferred Revenue has. (2) AR is for a product/service already delivered; Deferred Revenue is for one not yet delivered. So AR is an Asset (more future cash) and Deferred Revenue is a Liability (less future cash). Ответ (RU) (1) Деньги по AR ещё не получены, по Deferred Revenue — уже получены. (2) AR — за уже оказанную услугу, Deferred Revenue — за ещё не оказанную. Поэтому AR — актив (будущий приток), Deferred Revenue — обязательство (будущий отток). Пояснение Это зеркальные ситуации. AR: сначала услуга, потом деньги. DR: сначала деньги, потом услуга. У Молчанова: AR — «Дебиторы» (задача 7-3, оп. 4), DR — «Авансы полученные» (задача 7-2, оп. 1)."], "frontHtml": "<div><div>Basic Concepts · Базовые понятия</div>\n<div>What&#x27;s the difference between Accounts Receivable and Deferred Revenue?</div>\n<div>Чем дебиторская задолженность (AR) отличается от Deferred Revenue?</div></div>", "backHtml": "<div>\n\n<div><div>Answer (EN)</div>(1) AR has not been collected in cash yet; Deferred Revenue has. (2) AR is for a product/service already delivered; Deferred Revenue is for one not yet delivered. So AR is an Asset (more future cash) and Deferred Revenue is a Liability (less future cash).</div>\n<div><div>Ответ (RU)</div>(1) Деньги по AR ещё не получены, по Deferred Revenue — уже получены. (2) AR — за уже оказанную услугу, Deferred Revenue — за ещё не оказанную. Поэтому AR — актив (будущий приток), Deferred Revenue — обязательство (будущий отток).</div>\n<div><div>Пояснение</div>Это зеркальные ситуации. AR: сначала услуга, потом деньги. DR: сначала деньги, потом услуга. У Молчанова: AR — «Дебиторы» (задача 7-3, оп. 4), DR — «Авансы полученные» (задача 7-2, оп. 1).</div>\n</div>"}, {"id": 1790385598313, "topic": "620f982081e3e73e", "sec": "IB Accounting (BIWS) EN-RU::2. Basic Concepts — Базовые понятия", "q": "Basic Concepts · Базовые понятия How long does it usually take for a company to collect its Accounts Receivable? За сколько дней компании обычно собирают дебиторку?", "a": ["Answer (EN) Generally Accounts Receivable Days are 30–60 days. It can be higher for companies selling expensive items and lower for companies selling cheap items mostly for cash. Ответ (RU) Обычно 30–60 дней. Больше — у компаний с дорогими товарами, меньше — у компаний с дешёвыми товарами и оплатой наличными. Пояснение AR Days = AR / Выручка × 365 — это период оборота дебиторской задолженности из курса финансового анализа. Рост этого показателя — тревожный сигнал: клиенты платят медленнее, в дебиторке «замораживаются» деньги."], "frontHtml": "<div><div>Basic Concepts · Базовые понятия</div>\n<div>How long does it usually take for a company to collect its Accounts Receivable?</div>\n<div>За сколько дней компании обычно собирают дебиторку?</div></div>", "backHtml": "<div>\n\n<div><div>Answer (EN)</div>Generally Accounts Receivable Days are 30–60 days. It can be higher for companies selling expensive items and lower for companies selling cheap items mostly for cash.</div>\n<div><div>Ответ (RU)</div>Обычно 30–60 дней. Больше — у компаний с дорогими товарами, меньше — у компаний с дешёвыми товарами и оплатой наличными.</div>\n<div><div>Пояснение</div>AR Days = AR / Выручка × 365 — это период оборота дебиторской задолженности из курса финансового анализа. Рост этого показателя — тревожный сигнал: клиенты платят медленнее, в дебиторке «замораживаются» деньги.</div>\n</div>"}, {"id": 1790385598315, "topic": "620f982081e3e73e", "sec": "IB Accounting (BIWS) EN-RU::2. Basic Concepts — Базовые понятия", "q": "Basic Concepts · Базовые понятия How are Prepaid Expenses and Accounts Payable different? Чем расходы будущих периодов (Prepaid Expenses) отличаются от кредиторки (AP)?", "a": ["Answer (EN) (1) Prepaid Expenses have been paid in cash but not yet recorded on the IS; AP has been recorded on the IS but not yet paid. (2) PE is for products/services not yet delivered to the company; AP is for ones already delivered. Ответ (RU) (1) Prepaid Expenses уже оплачены, но ещё не в ОПУ; AP уже в ОПУ, но ещё не оплачена. (2) PE — за товары/услуги, которые компания ещё не получила; AP — за уже полученные. Пояснение Та же зеркальность, что у AR и DR, только со стороны расходов. PE = «Расходы будущих периодов» у Молчанова: годовая аренда в задаче 7-1 (оп. 6), страховка в задаче 7-4 (оп. 8). AP = «Кредиторы» за полученные, но неоплаченные услуги."], "frontHtml": "<div><div>Basic Concepts · Базовые понятия</div>\n<div>How are Prepaid Expenses and Accounts Payable different?</div>\n<div>Чем расходы будущих периодов (Prepaid Expenses) отличаются от кредиторки (AP)?</div></div>", "backHtml": "<div>\n\n<div><div>Answer (EN)</div>(1) Prepaid Expenses have been paid in cash but not yet recorded on the IS; AP has been recorded on the IS but not yet paid. (2) PE is for products/services not yet delivered to the company; AP is for ones already delivered.</div>\n<div><div>Ответ (RU)</div>(1) Prepaid Expenses уже оплачены, но ещё не в ОПУ; AP уже в ОПУ, но ещё не оплачена. (2) PE — за товары/услуги, которые компания ещё не получила; AP — за уже полученные.</div>\n<div><div>Пояснение</div>Та же зеркальность, что у AR и DR, только со стороны расходов. PE = «Расходы будущих периодов» у Молчанова: годовая аренда в задаче 7-1 (оп. 6), страховка в задаче 7-4 (оп. 8). AP = «Кредиторы» за полученные, но неоплаченные услуги.</div>\n</div>"}, {"id": 1790385598317, "topic": "620f982081e3e73e", "sec": "IB Accounting (BIWS) EN-RU::2. Basic Concepts — Базовые понятия", "q": "Basic Concepts · Базовые понятия You see an 'Income Taxes Payable' line item on the Liabilities side. What is this? Что такое Income Taxes Payable в пассиве баланса?", "a": ["Answer (EN) Normal income taxes that accrue and are then paid in cash — like Accrued Expenses, but for taxes. E.g. a company pays taxes every 3 months but records them on monthly Income Statements; Income Taxes Payable grows until the cash payment, then falls. Ответ (RU) Обычный налог на прибыль, который начислен, но ещё не уплачен, — как Accrued Expenses, только для налога. Например, налог платят раз в квартал, а в ОПУ начисляют ежемесячно: обязательство растёт до даты платежа, потом уменьшается. Пояснение В российском учёте это кредитовое сальдо счёта 68 «Расчёты по налогам и сборам». У Молчанова: задача 7-2, начисление налога на прибыль (оп. 2) и его уплата (оп. 14)."], "frontHtml": "<div><div>Basic Concepts · Базовые понятия</div>\n<div>You see an &#x27;Income Taxes Payable&#x27; line item on the Liabilities side. What is this?</div>\n<div>Что такое Income Taxes Payable в пассиве баланса?</div></div>", "backHtml": "<div>\n\n<div><div>Answer (EN)</div>Normal income taxes that accrue and are then paid in cash — like Accrued Expenses, but for taxes. E.g. a company pays taxes every 3 months but records them on monthly Income Statements; Income Taxes Payable grows until the cash payment, then falls.</div>\n<div><div>Ответ (RU)</div>Обычный налог на прибыль, который начислен, но ещё не уплачен, — как Accrued Expenses, только для налога. Например, налог платят раз в квартал, а в ОПУ начисляют ежемесячно: обязательство растёт до даты платежа, потом уменьшается.</div>\n<div><div>Пояснение</div>В российском учёте это кредитовое сальдо счёта 68 «Расчёты по налогам и сборам». У Молчанова: задача 7-2, начисление налога на прибыль (оп. 2) и его уплата (оп. 14).</div>\n</div>"}, {"id": 1790385598319, "topic": "620f982081e3e73e", "sec": "IB Accounting (BIWS) EN-RU::2. Basic Concepts — Базовые понятия", "q": "Basic Concepts · Базовые понятия You see a 'Noncontrolling Interest' (Minority Interest) line item on a company's Balance Sheet. What does it mean? Что означает Noncontrolling Interest (доля меньшинства) в балансе?", "a": ["Answer (EN) If you own over 50% but less than 100% of another company, it is the portion you do NOT own. E.g. the other company is worth $100 and you own 70% — you show a Noncontrolling Interest of $30. Ответ (RU) Если вы владеете долей больше 50%, но меньше 100% в другой компании, это та часть, которой вы НЕ владеете. Например, компания стоит $100, у вас 70% — в балансе будет неконтролирующая доля $30. Пояснение Откуда она берётся: при контроле (>50%) вы консолидируете 100% активов и обязательств дочки, хотя владеете только 70%. Чтобы показать, что 30% принадлежат другим акционерам, создают Noncontrolling Interest. Гайд пишет, что это статья пассива; по современным МСФО и US GAAP она показывается внутри собственного капитала. Для M&A это важно: NCI прибавляют при переходе от Equity Value к Enterprise Value."], "frontHtml": "<div><div>Basic Concepts · Базовые понятия</div>\n<div>You see a &#x27;Noncontrolling Interest&#x27; (Minority Interest) line item on a company&#x27;s Balance Sheet. What does it mean?</div>\n<div>Что означает Noncontrolling Interest (доля меньшинства) в балансе?</div></div>", "backHtml": "<div>\n\n<div><div>Answer (EN)</div>If you own over 50% but less than 100% of another company, it is the portion you do NOT own. E.g. the other company is worth $100 and you own 70% — you show a Noncontrolling Interest of $30.</div>\n<div><div>Ответ (RU)</div>Если вы владеете долей больше 50%, но меньше 100% в другой компании, это та часть, которой вы НЕ владеете. Например, компания стоит $100, у вас 70% — в балансе будет неконтролирующая доля $30.</div>\n<div><div>Пояснение</div>Откуда она берётся: при контроле (&gt;50%) вы консолидируете 100% активов и обязательств дочки, хотя владеете только 70%. Чтобы показать, что 30% принадлежат другим акционерам, создают Noncontrolling Interest. Гайд пишет, что это статья пассива; по современным МСФО и US GAAP она показывается внутри собственного капитала. Для M&amp;A это важно: NCI прибавляют при переходе от Equity Value к Enterprise Value.</div>\n</div>"}, {"id": 1790385598321, "topic": "620f982081e3e73e", "sec": "IB Accounting (BIWS) EN-RU::2. Basic Concepts — Базовые понятия", "q": "Basic Concepts · Базовые понятия You see an 'Investments in Equity Interests' (Associate Companies) line item on the Assets side. What does it mean? Что означает Investments in Equity Interests в активе?", "a": ["Answer (EN) If you own over 20% but less than 50% of another company, it is the portion you DO own. E.g. the other company is worth $100 and you own 25% — you show $25 of Investments in Equity Interests. Ответ (RU) Если вы владеете от 20% до 50% другой компании, это та часть, которой вы владеете. Например, компания стоит $100, у вас 25% — в активе $25. Пояснение Такие компании называются ассоциированными, их учитывают по методу долевого участия (equity method): без консолидации, одной строкой в активе. Разница с NCI: при >50% консолидируем всё и вычитаем чужую долю; при 20–50% ничего не консолидируем и показываем только свою долю."], "frontHtml": "<div><div>Basic Concepts · Базовые понятия</div>\n<div>You see an &#x27;Investments in Equity Interests&#x27; (Associate Companies) line item on the Assets side. What does it mean?</div>\n<div>Что означает Investments in Equity Interests в активе?</div></div>", "backHtml": "<div>\n\n<div><div>Answer (EN)</div>If you own over 20% but less than 50% of another company, it is the portion you DO own. E.g. the other company is worth $100 and you own 25% — you show $25 of Investments in Equity Interests.</div>\n<div><div>Ответ (RU)</div>Если вы владеете от 20% до 50% другой компании, это та часть, которой вы владеете. Например, компания стоит $100, у вас 25% — в активе $25.</div>\n<div><div>Пояснение</div>Такие компании называются ассоциированными, их учитывают по методу долевого участия (equity method): без консолидации, одной строкой в активе. Разница с NCI: при &gt;50% консолидируем всё и вычитаем чужую долю; при 20–50% ничего не консолидируем и показываем только свою долю.</div>\n</div>"}, {"id": 1790385598323, "topic": "620f982081e3e73e", "sec": "IB Accounting (BIWS) EN-RU::2. Basic Concepts — Базовые понятия", "q": "Basic Concepts · Базовые понятия Could you ever have negative Shareholders' Equity? What does it mean? Может ли собственный капитал быть отрицательным?", "a": ["Answer (EN) Yes. Commonly (1) after a Leveraged Buyout with a dividend recapitalization, when the owner takes out a large part of the equity, or (2) when the company has lost money consistently, reducing Retained Earnings. It doesn't mean anything specific but may signal trouble in the second case. Note: Equity Value (market cap) can never be negative. Ответ (RU) Да. Типично (1) после LBO с дивидендной рекапитализацией, когда владелец забирает большую часть капитала, или (2) когда компания долго несёт убытки и нераспределённая прибыль уходит в минус. Само по себе это ничего конкретного не значит, но во втором случае может говорить о проблемах. Важно: рыночная капитализация (Equity Value) отрицательной быть не может. Пояснение LBO (Leveraged Buyout) — покупка компании в основном за заёмные деньги; dividend recap — компания берёт новый долг и выплачивает его владельцу как дивиденды. Не путай балансовый капитал (Shareholders' Equity, «бухгалтерский») и рыночный (Equity Value = цена акции × количество акций)."], "frontHtml": "<div><div>Basic Concepts · Базовые понятия</div>\n<div>Could you ever have negative Shareholders&#x27; Equity? What does it mean?</div>\n<div>Может ли собственный капитал быть отрицательным?</div></div>", "backHtml": "<div>\n\n<div><div>Answer (EN)</div>Yes. Commonly (1) after a Leveraged Buyout with a dividend recapitalization, when the owner takes out a large part of the equity, or (2) when the company has lost money consistently, reducing Retained Earnings. It doesn&#x27;t mean anything specific but may signal trouble in the second case. Note: Equity Value (market cap) can never be negative.</div>\n<div><div>Ответ (RU)</div>Да. Типично (1) после LBO с дивидендной рекапитализацией, когда владелец забирает большую часть капитала, или (2) когда компания долго несёт убытки и нераспределённая прибыль уходит в минус. Само по себе это ничего конкретного не значит, но во втором случае может говорить о проблемах. Важно: рыночная капитализация (Equity Value) отрицательной быть не может.</div>\n<div><div>Пояснение</div>LBO (Leveraged Buyout) — покупка компании в основном за заёмные деньги; dividend recap — компания берёт новый долг и выплачивает его владельцу как дивиденды. Не путай балансовый капитал (Shareholders&#x27; Equity, «бухгалтерский») и рыночный (Equity Value = цена акции × количество акций).</div>\n</div>"}, {"id": 1790385598325, "topic": "620f982081e3e73e", "sec": "IB Accounting (BIWS) EN-RU::2. Basic Concepts — Базовые понятия", "q": "Basic Concepts · Базовые понятия What is Working Capital? How is it used? Что такое оборотный капитал (Working Capital) и зачем он нужен?", "a": ["Answer (EN) Working Capital = Current Assets − Current Liabilities. If positive, the company can pay short-term liabilities with short-term assets. In finance, Operating Working Capital is more common: (Current Assets excluding Cash & Investments) − (Current Liabilities excluding Debt). 'Changes in Working Capital' appear in CFO on the Cash Flow Statement. Ответ (RU) Оборотный капитал = оборотные активы − краткосрочные обязательства. Если он положительный, компания может покрыть краткосрочные долги краткосрочными активами. В финансах чаще используют операционный оборотный капитал: (оборотные активы без денег и инвестиций) − (краткосрочные обязательства без долга). Изменения оборотного капитала отражаются в операционном потоке ОДДС. Пояснение Зачем исключать деньги, инвестиции и долг: они относятся к финансированию и инвестициям, а не к операционной деятельности. В модели DCF рост операционного оборотного капитала уменьшает свободный денежный поток. В задаче 7-3 ты видел это в косвенном методе: уменьшение дебиторки дало +3200 к денежному потоку."], "frontHtml": "<div><div>Basic Concepts · Базовые понятия</div>\n<div>What is Working Capital? How is it used?</div>\n<div>Что такое оборотный капитал (Working Capital) и зачем он нужен?</div></div>", "backHtml": "<div>\n\n<div><div>Answer (EN)</div>Working Capital = Current Assets − Current Liabilities. If positive, the company can pay short-term liabilities with short-term assets. In finance, Operating Working Capital is more common: (Current Assets excluding Cash &amp; Investments) − (Current Liabilities excluding Debt). &#x27;Changes in Working Capital&#x27; appear in CFO on the Cash Flow Statement.</div>\n<div><div>Ответ (RU)</div>Оборотный капитал = оборотные активы − краткосрочные обязательства. Если он положительный, компания может покрыть краткосрочные долги краткосрочными активами. В финансах чаще используют операционный оборотный капитал: (оборотные активы без денег и инвестиций) − (краткосрочные обязательства без долга). Изменения оборотного капитала отражаются в операционном потоке ОДДС.</div>\n<div><div>Пояснение</div>Зачем исключать деньги, инвестиции и долг: они относятся к финансированию и инвестициям, а не к операционной деятельности. В модели DCF рост операционного оборотного капитала уменьшает свободный денежный поток. В задаче 7-3 ты видел это в косвенном методе: уменьшение дебиторки дало +3200 к денежному потоку.</div>\n</div>"}, {"id": 1790385598327, "topic": "620f982081e3e73e", "sec": "IB Accounting (BIWS) EN-RU::2. Basic Concepts — Базовые понятия", "q": "Basic Concepts · Базовые понятия 'Short-Term Investments' is a Current Asset — should you count it in Working Capital? Включать ли краткосрочные инвестиции в оборотный капитал?", "a": ["Answer (EN) No. Technically it is part of 'Working Capital' as defined, but it is excluded from Operating Working Capital because buying and selling investments is an investing activity, not an operating one. Ответ (RU) Нет. Формально они входят в «оборотный капитал» по определению, но из операционного оборотного капитала их исключают: покупка и продажа инвестиций — это инвестиционная деятельность, а не операционная. Пояснение Гайд предлагает вместо размытого термина Working Capital говорить Operating Assets and Liabilities — операционные активы и обязательства. Туда могут входить и долгосрочные статьи, например долгосрочная часть Deferred Revenue."], "frontHtml": "<div><div>Basic Concepts · Базовые понятия</div>\n<div>&#x27;Short-Term Investments&#x27; is a Current Asset — should you count it in Working Capital?</div>\n<div>Включать ли краткосрочные инвестиции в оборотный капитал?</div></div>", "backHtml": "<div>\n\n<div><div>Answer (EN)</div>No. Technically it is part of &#x27;Working Capital&#x27; as defined, but it is excluded from Operating Working Capital because buying and selling investments is an investing activity, not an operating one.</div>\n<div><div>Ответ (RU)</div>Нет. Формально они входят в «оборотный капитал» по определению, но из операционного оборотного капитала их исключают: покупка и продажа инвестиций — это инвестиционная деятельность, а не операционная.</div>\n<div><div>Пояснение</div>Гайд предлагает вместо размытого термина Working Capital говорить Operating Assets and Liabilities — операционные активы и обязательства. Туда могут входить и долгосрочные статьи, например долгосрочная часть Deferred Revenue.</div>\n</div>"}, {"id": 1790385598329, "topic": "620f982081e3e73e", "sec": "IB Accounting (BIWS) EN-RU::2. Basic Concepts — Базовые понятия", "q": "Basic Concepts · Базовые понятия What does negative (Operating) Working Capital mean? Is that a bad sign? Что значит отрицательный оборотный капитал? Это плохо?", "a": ["Answer (EN) Not necessarily. (1) Subscription or long-term contract businesses have big Deferred Revenue balances. (2) Retailers and restaurants (Amazon, Walmart, McDonald's) get paid upfront by customers but pay suppliers weeks later — a sign of efficiency and healthy cash flow. (3) In other cases it can signal financial trouble, e.g. large unpaid supplier bills. Ответ (RU) Не обязательно. (1) У компаний с подписками много Deferred Revenue. (2) Ритейл и рестораны (Amazon, Walmart, McDonald's) получают деньги от покупателей сразу, а поставщикам платят через недели — это признак эффективности. (3) Но иногда это признак проблем: компания много должна поставщикам и не может заплатить. Пояснение Российский пример — X5 или «Магнит»: покупатель платит на кассе сразу, поставщику платят через 30–60 дней. Фактически поставщики бесплатно кредитуют ритейлера. На собеседовании важно показать, что ты не делаешь автоматический вывод «отрицательный = плохо», а смотришь на бизнес-модель."], "frontHtml": "<div><div>Basic Concepts · Базовые понятия</div>\n<div>What does negative (Operating) Working Capital mean? Is that a bad sign?</div>\n<div>Что значит отрицательный оборотный капитал? Это плохо?</div></div>", "backHtml": "<div>\n\n<div><div>Answer (EN)</div>Not necessarily. (1) Subscription or long-term contract businesses have big Deferred Revenue balances. (2) Retailers and restaurants (Amazon, Walmart, McDonald&#x27;s) get paid upfront by customers but pay suppliers weeks later — a sign of efficiency and healthy cash flow. (3) In other cases it can signal financial trouble, e.g. large unpaid supplier bills.</div>\n<div><div>Ответ (RU)</div>Не обязательно. (1) У компаний с подписками много Deferred Revenue. (2) Ритейл и рестораны (Amazon, Walmart, McDonald&#x27;s) получают деньги от покупателей сразу, а поставщикам платят через недели — это признак эффективности. (3) Но иногда это признак проблем: компания много должна поставщикам и не может заплатить.</div>\n<div><div>Пояснение</div>Российский пример — X5 или «Магнит»: покупатель платит на кассе сразу, поставщику платят через 30–60 дней. Фактически поставщики бесплатно кредитуют ритейлера. На собеседовании важно показать, что ты не делаешь автоматический вывод «отрицательный = плохо», а смотришь на бизнес-модель.</div>\n</div>"}, {"id": 1790385598331, "topic": "620f982081e3e73e", "sec": "IB Accounting (BIWS) EN-RU::2. Basic Concepts — Базовые понятия", "q": "Basic Concepts · Базовые понятия What's the difference between cash-based and accrual accounting? Чем кассовый метод отличается от метода начисления?", "a": ["Answer (EN) Cash-based accounting recognizes revenue and expenses when cash is actually received or paid. Accrual accounting recognizes revenue when collection is reasonably certain (e.g. after invoicing a customer with a good payment record) and expenses when they are incurred, not when paid. Large companies use accrual; small businesses may use cash-based. Ответ (RU) Кассовый метод признаёт доходы и расходы в момент получения или выплаты денег. Метод начисления признаёт выручку, когда её получение достаточно определено (например, после выставления счёта надёжному клиенту), а расходы — когда они понесены, а не оплачены. Крупные компании используют метод начисления, малый бизнес может использовать кассовый. Пояснение Это тема главы 7 Молчанова целиком. Его определение: метод начисления отражает доход в момент перехода права собственности к покупателю, а расход — в том периоде, когда он понесён. Пример автора: счёт в ресторане — доход по методу начисления, но не по кассовому до момента оплаты."], "frontHtml": "<div><div>Basic Concepts · Базовые понятия</div>\n<div>What&#x27;s the difference between cash-based and accrual accounting?</div>\n<div>Чем кассовый метод отличается от метода начисления?</div></div>", "backHtml": "<div>\n\n<div><div>Answer (EN)</div>Cash-based accounting recognizes revenue and expenses when cash is actually received or paid. Accrual accounting recognizes revenue when collection is reasonably certain (e.g. after invoicing a customer with a good payment record) and expenses when they are incurred, not when paid. Large companies use accrual; small businesses may use cash-based.</div>\n<div><div>Ответ (RU)</div>Кассовый метод признаёт доходы и расходы в момент получения или выплаты денег. Метод начисления признаёт выручку, когда её получение достаточно определено (например, после выставления счёта надёжному клиенту), а расходы — когда они понесены, а не оплачены. Крупные компании используют метод начисления, малый бизнес может использовать кассовый.</div>\n<div><div>Пояснение</div>Это тема главы 7 Молчанова целиком. Его определение: метод начисления отражает доход в момент перехода права собственности к покупателю, а расход — в том периоде, когда он понесён. Пример автора: счёт в ресторане — доход по методу начисления, но не по кассовому до момента оплаты.</div>\n</div>"}, {"id": 1790385598333, "topic": "620f982081e3e73e", "sec": "IB Accounting (BIWS) EN-RU::2. Basic Concepts — Базовые понятия", "q": "Basic Concepts · Базовые понятия A customer pays for a TV with a credit card. What does this look like under cash-based vs. accrual accounting? Покупатель платит за телевизор кредитной картой. Как это выглядит при кассовом методе и методе начисления?", "a": ["Answer (EN) Cash-based: revenue appears only when the card is charged, authorized and funds are deposited — then Revenue and Cash both increase. Accrual: Revenue appears right away, but it goes into Accounts Receivable first; when the cash is deposited, Cash goes up and AR goes down. Ответ (RU) Кассовый метод: выручка появится только когда деньги с карты придут на счёт компании — тогда растут и выручка, и деньги. Метод начисления: выручка признаётся сразу, но сначала в дебиторке; когда деньги поступят, растут деньги и уменьшается дебиторка. Пояснение Проводки по методу начисления: в момент продажи Д-т Дебиторы (банк-эквайер) К-т Выручка; при зачислении денег Д-т Деньги К-т Дебиторы. Вторая проводка на прибыль не влияет — это та же логика, что в задаче 7-3, оп. 4 и 9."], "frontHtml": "<div><div>Basic Concepts · Базовые понятия</div>\n<div>A customer pays for a TV with a credit card. What does this look like under cash-based vs. accrual accounting?</div>\n<div>Покупатель платит за телевизор кредитной картой. Как это выглядит при кассовом методе и методе начисления?</div></div>", "backHtml": "<div>\n\n<div><div>Answer (EN)</div>Cash-based: revenue appears only when the card is charged, authorized and funds are deposited — then Revenue and Cash both increase. Accrual: Revenue appears right away, but it goes into Accounts Receivable first; when the cash is deposited, Cash goes up and AR goes down.</div>\n<div><div>Ответ (RU)</div>Кассовый метод: выручка появится только когда деньги с карты придут на счёт компании — тогда растут и выручка, и деньги. Метод начисления: выручка признаётся сразу, но сначала в дебиторке; когда деньги поступят, растут деньги и уменьшается дебиторка.</div>\n<div><div>Пояснение</div>Проводки по методу начисления: в момент продажи Д-т Дебиторы (банк-эквайер) К-т Выручка; при зачислении денег Д-т Деньги К-т Дебиторы. Вторая проводка на прибыль не влияет — это та же логика, что в задаче 7-3, оп. 4 и 9.</div>\n</div>"}, {"id": 1790385598335, "topic": "620f982081e3e73e", "sec": "IB Accounting (BIWS) EN-RU::2. Basic Concepts — Базовые понятия", "q": "Basic Concepts · Базовые понятия Why do companies report GAAP/IFRS earnings AND non-GAAP (Pro Forma) earnings? Зачем компании публикуют и прибыль по GAAP/IFRS, и «скорректированную» прибыль?", "a": ["Answer (EN) Many companies have non-cash charges — Amortization of Intangibles, Stock-Based Compensation, Write-Downs — that reduce Net Income. They report Pro Forma metrics that exclude these charges to present a more favorable picture, arguing that it better reflects 'true cash earnings'. Ответ (RU) У многих компаний есть неденежные расходы — амортизация нематериальных активов, вознаграждение акциями, списания активов, — которые снижают чистую прибыль. Компании публикуют скорректированные показатели без них, чтобы показать более привлекательную картину, аргументируя это тем, что так лучше видна «реальная денежная прибыль». Пояснение Аналитику нужно относиться к таким показателям критически: компания сама решает, что исключить. Например, SBC — реальная стоимость для акционеров (размывание долей), хотя денег и не тратится. В России популярный пример — «скорректированная EBITDA» в отчётности многих эмитентов."], "frontHtml": "<div><div>Basic Concepts · Базовые понятия</div>\n<div>Why do companies report GAAP/IFRS earnings AND non-GAAP (Pro Forma) earnings?</div>\n<div>Зачем компании публикуют и прибыль по GAAP/IFRS, и «скорректированную» прибыль?</div></div>", "backHtml": "<div>\n\n<div><div>Answer (EN)</div>Many companies have non-cash charges — Amortization of Intangibles, Stock-Based Compensation, Write-Downs — that reduce Net Income. They report Pro Forma metrics that exclude these charges to present a more favorable picture, arguing that it better reflects &#x27;true cash earnings&#x27;.</div>\n<div><div>Ответ (RU)</div>У многих компаний есть неденежные расходы — амортизация нематериальных активов, вознаграждение акциями, списания активов, — которые снижают чистую прибыль. Компании публикуют скорректированные показатели без них, чтобы показать более привлекательную картину, аргументируя это тем, что так лучше видна «реальная денежная прибыль».</div>\n<div><div>Пояснение</div>Аналитику нужно относиться к таким показателям критически: компания сама решает, что исключить. Например, SBC — реальная стоимость для акционеров (размывание долей), хотя денег и не тратится. В России популярный пример — «скорректированная EBITDA» в отчётности многих эмитентов.</div>\n</div>"}, {"id": 1790385598337, "topic": "620f982081e3e73e", "sec": "IB Accounting (BIWS) EN-RU::2. Basic Concepts — Базовые понятия", "q": "Basic Concepts · Базовые понятия A company has had positive EBITDA for the past 10 years, but it recently went bankrupt. How could this happen? У компании 10 лет положительная EBITDA, но она обанкротилась. Как такое возможно?", "a": ["Answer (EN) (1) Too much CapEx — not in EBITDA but a real cash cost. (2) High Interest Expense it can no longer afford. (3) Debt maturing at once that it can't refinance in a credit crunch. (4) Large one-time charges (e.g. litigation) excluded from EBITDA. EBITDA ignores CapEx, interest and non-recurring charges — any of them can be huge cash expenses. Ответ (RU) (1) Слишком большие капвложения — их нет в EBITDA, но это реальные траты. (2) Высокие проценты, которые компания уже не тянет. (3) Весь долг гасится в одну дату, а рефинансироваться не получилось (кредитный кризис). (4) Крупные разовые расходы (например, судебные), которые исключены из EBITDA. EBITDA не учитывает капвложения, проценты и разовые расходы — любой из них может «съесть» все деньги. Пояснение EBITDA = прибыль до процентов, налогов и амортизации (Earnings Before Interest, Taxes, Depreciation & Amortization). Это приближение операционного денежного потока, но очень грубое. Урок: для оценки платёжеспособности смотрят на свободный денежный поток и долговую нагрузку (Debt/EBITDA, покрытие процентов)."], "frontHtml": "<div><div>Basic Concepts · Базовые понятия</div>\n<div>A company has had positive EBITDA for the past 10 years, but it recently went bankrupt. How could this happen?</div>\n<div>У компании 10 лет положительная EBITDA, но она обанкротилась. Как такое возможно?</div></div>", "backHtml": "<div>\n\n<div><div>Answer (EN)</div>(1) Too much CapEx — not in EBITDA but a real cash cost. (2) High Interest Expense it can no longer afford. (3) Debt maturing at once that it can&#x27;t refinance in a credit crunch. (4) Large one-time charges (e.g. litigation) excluded from EBITDA. EBITDA ignores CapEx, interest and non-recurring charges — any of them can be huge cash expenses.</div>\n<div><div>Ответ (RU)</div>(1) Слишком большие капвложения — их нет в EBITDA, но это реальные траты. (2) Высокие проценты, которые компания уже не тянет. (3) Весь долг гасится в одну дату, а рефинансироваться не получилось (кредитный кризис). (4) Крупные разовые расходы (например, судебные), которые исключены из EBITDA. EBITDA не учитывает капвложения, проценты и разовые расходы — любой из них может «съесть» все деньги.</div>\n<div><div>Пояснение</div>EBITDA = прибыль до процентов, налогов и амортизации (Earnings Before Interest, Taxes, Depreciation &amp; Amortization). Это приближение операционного денежного потока, но очень грубое. Урок: для оценки платёжеспособности смотрят на свободный денежный поток и долговую нагрузку (Debt/EBITDA, покрытие процентов).</div>\n</div>"}, {"id": 1790385598339, "topic": "620f982081e3e73e", "sec": "IB Accounting (BIWS) EN-RU::2. Basic Concepts — Базовые понятия", "q": "Basic Concepts · Базовые понятия Normally Goodwill remains constant on the Balance Sheet. Why would it be impaired and what does Goodwill Impairment mean? Почему гудвил обесценивается и что это значит?", "a": ["Answer (EN) Usually the acquirer re-assesses what it really got from an acquisition — customer relationships, brand, IP — and finds they are worth much less than thought, often because it overpaid. It can also happen when part of the business is discontinued. It can cause very negative Net Income. Ответ (RU) Обычно покупатель пересматривает, что он реально получил при сделке — клиентскую базу, бренд, интеллектуальную собственность, — и понимает, что это стоит намного меньше, чем думали, часто потому что переплатил. Также бывает при закрытии части бизнеса. Может привести к очень большому убытку. Пояснение Гудвил = цена покупки − балансовая стоимость чистых активов продавца (премия сверх капитала). Гудвил не амортизируется, а ежегодно тестируется на обесценение. Классический пример — крупные списания гудвила после неудачных сделок M&A."], "frontHtml": "<div><div>Basic Concepts · Базовые понятия</div>\n<div>Normally Goodwill remains constant on the Balance Sheet. Why would it be impaired and what does Goodwill Impairment mean?</div>\n<div>Почему гудвил обесценивается и что это значит?</div></div>", "backHtml": "<div>\n\n<div><div>Answer (EN)</div>Usually the acquirer re-assesses what it really got from an acquisition — customer relationships, brand, IP — and finds they are worth much less than thought, often because it overpaid. It can also happen when part of the business is discontinued. It can cause very negative Net Income.</div>\n<div><div>Ответ (RU)</div>Обычно покупатель пересматривает, что он реально получил при сделке — клиентскую базу, бренд, интеллектуальную собственность, — и понимает, что это стоит намного меньше, чем думали, часто потому что переплатил. Также бывает при закрытии части бизнеса. Может привести к очень большому убытку.</div>\n<div><div>Пояснение</div>Гудвил = цена покупки − балансовая стоимость чистых активов продавца (премия сверх капитала). Гудвил не амортизируется, а ежегодно тестируется на обесценение. Классический пример — крупные списания гудвила после неудачных сделок M&amp;A.</div>\n</div>"}, {"id": 1790385598341, "topic": "620f982081e3e73e", "sec": "IB Accounting (BIWS) EN-RU::3. Single-Step Scenarios — Одношаговые сценарии", "q": "Single-Step Scenarios · Одношаговые сценарии Walk me through how Depreciation going up by $10 affects the statements. Как рост амортизации на $10 влияет на три отчёта?", "a": ["3 statements · в трёх отчётах (tax 40%) IS / ОПУ Прибыль до налога −10; чистая прибыль −6 CFS / ОДДС ЧП −6; +10 амортизация → операционный поток +4; деньги +4 BS / Баланс Активы: деньги +4, ОС −10 = −6. Пассивы: нераспр. прибыль −6 Answer (EN) IS: Operating Income and Pre-Tax Income fall by $10; at 40% tax, Net Income falls by $6. CFS: Net Income −$6, add back $10 Depreciation → cash +$4. BS: PP&E −$10, Cash +$4 → Assets −$6; Shareholders' Equity (Retained Earnings) −$6. Balances. Ответ (RU) ОПУ: операционная прибыль и прибыль до налога −$10, чистая прибыль −$6 (налог 40%). ОДДС: чистая прибыль −$6, прибавляем амортизацию +$10 → деньги +$4. Баланс: ОС −$10, деньги +$4 → активы −$6; нераспределённая прибыль −$6. Сходится. Пояснение Интуиция: любой неденежный расход экономит налог, поэтому деньги растут. Это базовый шаблон для всех неденежных расходов (амортизация, списания, SBC): прибыль −6, деньги +4, какой-то актив −10."], "frontHtml": "<div><div>Single-Step Scenarios · Одношаговые сценарии</div>\n<div>Walk me through how Depreciation going up by $10 affects the statements.</div>\n<div>Как рост амортизации на $10 влияет на три отчёта?</div></div>", "backHtml": "<div>\n<div><div>3 statements · в трёх отчётах (tax 40%)</div>\n<table><tr><td>IS / ОПУ</td><td>Прибыль до налога −10; чистая прибыль −6</td></tr>\n<tr><td>CFS / ОДДС</td><td>ЧП −6; +10 амортизация → операционный поток +4; деньги +4</td></tr>\n<tr><td>BS / Баланс</td><td>Активы: деньги +4, ОС −10 = −6. Пассивы: нераспр. прибыль −6</td></tr></table></div>\n<div><div>Answer (EN)</div>IS: Operating Income and Pre-Tax Income fall by $10; at 40% tax, Net Income falls by $6. CFS: Net Income −$6, add back $10 Depreciation → cash +$4. BS: PP&amp;E −$10, Cash +$4 → Assets −$6; Shareholders&#x27; Equity (Retained Earnings) −$6. Balances.</div>\n<div><div>Ответ (RU)</div>ОПУ: операционная прибыль и прибыль до налога −$10, чистая прибыль −$6 (налог 40%). ОДДС: чистая прибыль −$6, прибавляем амортизацию +$10 → деньги +$4. Баланс: ОС −$10, деньги +$4 → активы −$6; нераспределённая прибыль −$6. Сходится.</div>\n<div><div>Пояснение</div>Интуиция: любой неденежный расход экономит налог, поэтому деньги растут. Это базовый шаблон для всех неденежных расходов (амортизация, списания, SBC): прибыль −6, деньги +4, какой-то актив −10.</div>\n</div>"}, {"id": 1790385598343, "topic": "620f982081e3e73e", "sec": "IB Accounting (BIWS) EN-RU::3. Single-Step Scenarios — Одношаговые сценарии", "q": "Single-Step Scenarios · Одношаговые сценарии What happens when Accrued Expenses increase by $10? Что происходит, когда начисленные обязательства растут на $10?", "a": ["3 statements · в трёх отчётах (tax 40%) IS / ОПУ Прибыль до налога −10; ЧП −6 CFS / ОДДС ЧП −6; рост начисленных обязательств +10 → деньги +4 BS / Баланс Активы: деньги +4. Пассивы: начисл. обязательства +10, нераспр. прибыль −6 = +4 Answer (EN) Accrued Expenses rising means an expense was recorded but not paid. IS: Pre-Tax Income −$10, Net Income −$6. CFS: Net Income −$6, +$10 from the Accrued Expenses increase → cash +$4. BS: Cash +$4; Accrued Expenses (Liability) +$10, Retained Earnings −$6 → both sides +$4. Ответ (RU) Рост начисленных обязательств означает: расход признали, но не оплатили. ОПУ: прибыль до налога −$10, чистая прибыль −$6. ОДДС: чистая прибыль −$6, рост обязательства +$10 → деньги +$4. Баланс: деньги +$4; начисленные обязательства +$10, нераспределённая прибыль −$6 → обе стороны +$4. Пояснение Интуиция: расход признали и сэкономили на налоге, а платить ещё не стали — поэтому денег даже больше. У Молчанова это начисление зарплаты: Д-т Расходы К-т Кредиторы (задача 7-3, оп. 7)."], "frontHtml": "<div><div>Single-Step Scenarios · Одношаговые сценарии</div>\n<div>What happens when Accrued Expenses increase by $10?</div>\n<div>Что происходит, когда начисленные обязательства растут на $10?</div></div>", "backHtml": "<div>\n<div><div>3 statements · в трёх отчётах (tax 40%)</div>\n<table><tr><td>IS / ОПУ</td><td>Прибыль до налога −10; ЧП −6</td></tr>\n<tr><td>CFS / ОДДС</td><td>ЧП −6; рост начисленных обязательств +10 → деньги +4</td></tr>\n<tr><td>BS / Баланс</td><td>Активы: деньги +4. Пассивы: начисл. обязательства +10, нераспр. прибыль −6 = +4</td></tr></table></div>\n<div><div>Answer (EN)</div>Accrued Expenses rising means an expense was recorded but not paid. IS: Pre-Tax Income −$10, Net Income −$6. CFS: Net Income −$6, +$10 from the Accrued Expenses increase → cash +$4. BS: Cash +$4; Accrued Expenses (Liability) +$10, Retained Earnings −$6 → both sides +$4.</div>\n<div><div>Ответ (RU)</div>Рост начисленных обязательств означает: расход признали, но не оплатили. ОПУ: прибыль до налога −$10, чистая прибыль −$6. ОДДС: чистая прибыль −$6, рост обязательства +$10 → деньги +$4. Баланс: деньги +$4; начисленные обязательства +$10, нераспределённая прибыль −$6 → обе стороны +$4.</div>\n<div><div>Пояснение</div>Интуиция: расход признали и сэкономили на налоге, а платить ещё не стали — поэтому денег даже больше. У Молчанова это начисление зарплаты: Д-т Расходы К-т Кредиторы (задача 7-3, оп. 7).</div>\n</div>"}, {"id": 1790385598345, "topic": "620f982081e3e73e", "sec": "IB Accounting (BIWS) EN-RU::3. Single-Step Scenarios — Одношаговые сценарии", "q": "Single-Step Scenarios · Одношаговые сценарии What happens when Accrued Expenses decrease by $10 (i.e. they're paid out in cash)? Ignore previous increases. Что происходит, когда начисленные обязательства уменьшаются на $10 (их оплатили)?", "a": ["3 statements · в трёх отчётах (tax 40%) IS / ОПУ Без изменений CFS / ОДДС Изменение начисл. обязательств −10 → деньги −10 BS / Баланс Активы: деньги −10. Пассивы: начисл. обязательства −10 Answer (EN) IS: no changes. CFS: the change in Accrued Expenses in CFO is −$10, so cash falls by $10. BS: Cash −$10, Accrued Expenses −$10. Balances. Ответ (RU) ОПУ: без изменений. ОДДС: изменение начисленных обязательств −$10, деньги −$10. Баланс: деньги −$10, начисленные обязательства −$10. Сходится. Пояснение Это просто выплата ранее признанного расхода — расход второй раз не признаётся. У Молчанова: выплата зарплаты, Д-т Кредиторы К-т Деньги (задача 7-3, оп. 15). На собеседовании уточни у интервьюера, не нужно ли учитывать предыдущее начисление."], "frontHtml": "<div><div>Single-Step Scenarios · Одношаговые сценарии</div>\n<div>What happens when Accrued Expenses decrease by $10 (i.e. they&#x27;re paid out in cash)? Ignore previous increases.</div>\n<div>Что происходит, когда начисленные обязательства уменьшаются на $10 (их оплатили)?</div></div>", "backHtml": "<div>\n<div><div>3 statements · в трёх отчётах (tax 40%)</div>\n<table><tr><td>IS / ОПУ</td><td>Без изменений</td></tr>\n<tr><td>CFS / ОДДС</td><td>Изменение начисл. обязательств −10 → деньги −10</td></tr>\n<tr><td>BS / Баланс</td><td>Активы: деньги −10. Пассивы: начисл. обязательства −10</td></tr></table></div>\n<div><div>Answer (EN)</div>IS: no changes. CFS: the change in Accrued Expenses in CFO is −$10, so cash falls by $10. BS: Cash −$10, Accrued Expenses −$10. Balances.</div>\n<div><div>Ответ (RU)</div>ОПУ: без изменений. ОДДС: изменение начисленных обязательств −$10, деньги −$10. Баланс: деньги −$10, начисленные обязательства −$10. Сходится.</div>\n<div><div>Пояснение</div>Это просто выплата ранее признанного расхода — расход второй раз не признаётся. У Молчанова: выплата зарплаты, Д-т Кредиторы К-т Деньги (задача 7-3, оп. 15). На собеседовании уточни у интервьюера, не нужно ли учитывать предыдущее начисление.</div>\n</div>"}, {"id": 1790385598347, "topic": "620f982081e3e73e", "sec": "IB Accounting (BIWS) EN-RU::3. Single-Step Scenarios — Одношаговые сценарии", "q": "Single-Step Scenarios · Одношаговые сценарии Accounts Receivable increases by $10. Walk me through the 3 statements. Дебиторская задолженность выросла на $10. Что происходит в трёх отчётах?", "a": ["3 statements · в трёх отчётах (tax 40%) IS / ОПУ Выручка +10; прибыль до налога +10; ЧП +6 CFS / ОДДС ЧП +6; рост дебиторки −10 → деньги −4 BS / Баланс Активы: деньги −4, дебиторка +10 = +6. Пассивы: нераспр. прибыль +6 Answer (EN) AR up means we recorded $10 revenue but haven't collected cash. IS: Revenue +$10, Pre-Tax Income +$10, Net Income +$6. CFS: Net Income +$6, subtract $10 AR increase → cash −$4. BS: Cash −$4, AR +$10 → Assets +$6; Retained Earnings +$6. Ответ (RU) Рост AR: выручку $10 признали, а деньги не получили. ОПУ: выручка +$10, прибыль до налога +$10, чистая прибыль +$6. ОДДС: чистая прибыль +$6, вычитаем рост дебиторки −$10 → деньги −$4. Баланс: деньги −$4, дебиторка +$10 → активы +$6; нераспределённая прибыль +$6. Пояснение Интуиция: налог на новую выручку мы заплатили, а саму выручку деньгами ещё не получили — поэтому денег стало меньше на сумму налога ($4). Правило: рост актива уменьшает денежный поток."], "frontHtml": "<div><div>Single-Step Scenarios · Одношаговые сценарии</div>\n<div>Accounts Receivable increases by $10. Walk me through the 3 statements.</div>\n<div>Дебиторская задолженность выросла на $10. Что происходит в трёх отчётах?</div></div>", "backHtml": "<div>\n<div><div>3 statements · в трёх отчётах (tax 40%)</div>\n<table><tr><td>IS / ОПУ</td><td>Выручка +10; прибыль до налога +10; ЧП +6</td></tr>\n<tr><td>CFS / ОДДС</td><td>ЧП +6; рост дебиторки −10 → деньги −4</td></tr>\n<tr><td>BS / Баланс</td><td>Активы: деньги −4, дебиторка +10 = +6. Пассивы: нераспр. прибыль +6</td></tr></table></div>\n<div><div>Answer (EN)</div>AR up means we recorded $10 revenue but haven&#x27;t collected cash. IS: Revenue +$10, Pre-Tax Income +$10, Net Income +$6. CFS: Net Income +$6, subtract $10 AR increase → cash −$4. BS: Cash −$4, AR +$10 → Assets +$6; Retained Earnings +$6.</div>\n<div><div>Ответ (RU)</div>Рост AR: выручку $10 признали, а деньги не получили. ОПУ: выручка +$10, прибыль до налога +$10, чистая прибыль +$6. ОДДС: чистая прибыль +$6, вычитаем рост дебиторки −$10 → деньги −$4. Баланс: деньги −$4, дебиторка +$10 → активы +$6; нераспределённая прибыль +$6.</div>\n<div><div>Пояснение</div>Интуиция: налог на новую выручку мы заплатили, а саму выручку деньгами ещё не получили — поэтому денег стало меньше на сумму налога ($4). Правило: рост актива уменьшает денежный поток.</div>\n</div>"}, {"id": 1790385598349, "topic": "620f982081e3e73e", "sec": "IB Accounting (BIWS) EN-RU::3. Single-Step Scenarios — Одношаговые сценарии", "q": "Single-Step Scenarios · Одношаговые сценарии Prepaid Expenses decrease by $10. Walk me through the statements. Ignore previous increases. Расходы будущих периодов уменьшились на $10. Что происходит?", "a": ["3 statements · в трёх отчётах (tax 40%) IS / ОПУ Прибыль до налога −10; ЧП −6 CFS / ОДДС ЧП −6; уменьшение РБП +10 → деньги +4 BS / Баланс Активы: деньги +4, РБП −10 = −6. Пассивы: нераспр. прибыль −6 Answer (EN) PE decreasing means a previously paid expense is now recognized (e.g. insurance). IS: Pre-Tax Income −$10, Net Income −$6. CFS: Net Income −$6; PE is an Asset, so a $10 decrease adds $10 → cash +$4. BS: Cash +$4, PE −$10 → Assets −$6; Retained Earnings −$6. Ответ (RU) Уменьшение PE: ранее оплаченный расход теперь признаётся (например, страховка). ОПУ: прибыль до налога −$10, чистая прибыль −$6. ОДДС: чистая прибыль −$6; PE — актив, его уменьшение даёт +$10 → деньги +$4. Баланс: деньги +$4, PE −$10 → активы −$6; нераспределённая прибыль −$6. Пояснение Интуиция: расход в ОПУ появился и налог уменьшился, но деньги за этот расход ушли раньше — поэтому сейчас деньги растут на сэкономленный налог. У Молчанова это списание РБП: Д-т Расходы К-т РБП (задача 7-1, оп. 6а; задача 7-4, оп. 8а)."], "frontHtml": "<div><div>Single-Step Scenarios · Одношаговые сценарии</div>\n<div>Prepaid Expenses decrease by $10. Walk me through the statements. Ignore previous increases.</div>\n<div>Расходы будущих периодов уменьшились на $10. Что происходит?</div></div>", "backHtml": "<div>\n<div><div>3 statements · в трёх отчётах (tax 40%)</div>\n<table><tr><td>IS / ОПУ</td><td>Прибыль до налога −10; ЧП −6</td></tr>\n<tr><td>CFS / ОДДС</td><td>ЧП −6; уменьшение РБП +10 → деньги +4</td></tr>\n<tr><td>BS / Баланс</td><td>Активы: деньги +4, РБП −10 = −6. Пассивы: нераспр. прибыль −6</td></tr></table></div>\n<div><div>Answer (EN)</div>PE decreasing means a previously paid expense is now recognized (e.g. insurance). IS: Pre-Tax Income −$10, Net Income −$6. CFS: Net Income −$6; PE is an Asset, so a $10 decrease adds $10 → cash +$4. BS: Cash +$4, PE −$10 → Assets −$6; Retained Earnings −$6.</div>\n<div><div>Ответ (RU)</div>Уменьшение PE: ранее оплаченный расход теперь признаётся (например, страховка). ОПУ: прибыль до налога −$10, чистая прибыль −$6. ОДДС: чистая прибыль −$6; PE — актив, его уменьшение даёт +$10 → деньги +$4. Баланс: деньги +$4, PE −$10 → активы −$6; нераспределённая прибыль −$6.</div>\n<div><div>Пояснение</div>Интуиция: расход в ОПУ появился и налог уменьшился, но деньги за этот расход ушли раньше — поэтому сейчас деньги растут на сэкономленный налог. У Молчанова это списание РБП: Д-т Расходы К-т РБП (задача 7-1, оп. 6а; задача 7-4, оп. 8а).</div>\n</div>"}, {"id": 1790385598351, "topic": "620f982081e3e73e", "sec": "IB Accounting (BIWS) EN-RU::3. Single-Step Scenarios — Одношаговые сценарии", "q": "Single-Step Scenarios · Одношаговые сценарии What happens when Inventory goes up by $10, assuming you pay for it with cash? Что происходит, когда запасы растут на $10 за счёт денег?", "a": ["3 statements · в трёх отчётах (tax 40%) IS / ОПУ Без изменений CFS / ОДДС Рост запасов −10 → деньги −10 BS / Баланс Активы: запасы +10, деньги −10 = 0. Пассивы: без изменений Answer (EN) IS: no changes. CFS: Inventory is an Asset, so its increase reduces CFO by $10; cash −$10. BS: Inventory +$10, Cash −$10 — they cancel out. Ответ (RU) ОПУ: без изменений. ОДДС: запасы — актив, их рост уменьшает операционный поток на $10; деньги −$10. Баланс: запасы +$10, деньги −$10 — изменения взаимно гасятся. Пояснение Деньги превратились в запасы, но ничего ещё не произведено и не продано. У Молчанова: Д-т Материалы К-т Деньги (задача 7-1, оп. 2). Обрати внимание: покупка запасов идёт в операционный поток, а не в инвестиционный."], "frontHtml": "<div><div>Single-Step Scenarios · Одношаговые сценарии</div>\n<div>What happens when Inventory goes up by $10, assuming you pay for it with cash?</div>\n<div>Что происходит, когда запасы растут на $10 за счёт денег?</div></div>", "backHtml": "<div>\n<div><div>3 statements · в трёх отчётах (tax 40%)</div>\n<table><tr><td>IS / ОПУ</td><td>Без изменений</td></tr>\n<tr><td>CFS / ОДДС</td><td>Рост запасов −10 → деньги −10</td></tr>\n<tr><td>BS / Баланс</td><td>Активы: запасы +10, деньги −10 = 0. Пассивы: без изменений</td></tr></table></div>\n<div><div>Answer (EN)</div>IS: no changes. CFS: Inventory is an Asset, so its increase reduces CFO by $10; cash −$10. BS: Inventory +$10, Cash −$10 — they cancel out.</div>\n<div><div>Ответ (RU)</div>ОПУ: без изменений. ОДДС: запасы — актив, их рост уменьшает операционный поток на $10; деньги −$10. Баланс: запасы +$10, деньги −$10 — изменения взаимно гасятся.</div>\n<div><div>Пояснение</div>Деньги превратились в запасы, но ничего ещё не произведено и не продано. У Молчанова: Д-т Материалы К-т Деньги (задача 7-1, оп. 2). Обрати внимание: покупка запасов идёт в операционный поток, а не в инвестиционный.</div>\n</div>"}, {"id": 1790385598353, "topic": "620f982081e3e73e", "sec": "IB Accounting (BIWS) EN-RU::3. Single-Step Scenarios — Одношаговые сценарии", "q": "Single-Step Scenarios · Одношаговые сценарии A company sells PP&E for $120. On the Balance Sheet the PP&E is worth $100. Walk me through the 3 statements. Компания продаёт ОС за $120, балансовая стоимость $100. Что происходит?", "a": ["3 statements · в трёх отчётах (tax 40%) IS / ОПУ Прибыль от продажи +20; прибыль до налога +20; ЧП +12 CFS / ОДДС ЧП +12; −20 прибыль от продажи → CFO −8; CFI +120 → деньги +112 BS / Баланс Активы: деньги +112, ОС −100 = +12. Пассивы: нераспр. прибыль +12 Answer (EN) IS: Gain of $20, Pre-Tax Income +$20, Net Income +$12. CFS: Net Income +$12, subtract the $20 Gain → CFO −$8; in CFI record full proceeds +$120 → cash +$112. BS: Cash +$112, PP&E −$100 → Assets +$12; Retained Earnings +$12. Ответ (RU) ОПУ: прибыль от продажи $20, прибыль до налога +$20, чистая прибыль +$12. ОДДС: чистая прибыль +$12, вычитаем прибыль от продажи −$20 → операционный поток −$8; в инвестиционном потоке вся выручка от продажи +$120 → деньги +$112. Баланс: деньги +$112, ОС −$100 → активы +$12; нераспределённая прибыль +$12. Пояснение Почему вычитаем прибыль от продажи, если она денежная? Это переклассификация: все $120 показываются в инвестиционном потоке, и чтобы не учесть $20 дважды, их убирают из операционного. Итог +$112 = $120 − налог $8."], "frontHtml": "<div><div>Single-Step Scenarios · Одношаговые сценарии</div>\n<div>A company sells PP&amp;E for $120. On the Balance Sheet the PP&amp;E is worth $100. Walk me through the 3 statements.</div>\n<div>Компания продаёт ОС за $120, балансовая стоимость $100. Что происходит?</div></div>", "backHtml": "<div>\n<div><div>3 statements · в трёх отчётах (tax 40%)</div>\n<table><tr><td>IS / ОПУ</td><td>Прибыль от продажи +20; прибыль до налога +20; ЧП +12</td></tr>\n<tr><td>CFS / ОДДС</td><td>ЧП +12; −20 прибыль от продажи → CFO −8; CFI +120 → деньги +112</td></tr>\n<tr><td>BS / Баланс</td><td>Активы: деньги +112, ОС −100 = +12. Пассивы: нераспр. прибыль +12</td></tr></table></div>\n<div><div>Answer (EN)</div>IS: Gain of $20, Pre-Tax Income +$20, Net Income +$12. CFS: Net Income +$12, subtract the $20 Gain → CFO −$8; in CFI record full proceeds +$120 → cash +$112. BS: Cash +$112, PP&amp;E −$100 → Assets +$12; Retained Earnings +$12.</div>\n<div><div>Ответ (RU)</div>ОПУ: прибыль от продажи $20, прибыль до налога +$20, чистая прибыль +$12. ОДДС: чистая прибыль +$12, вычитаем прибыль от продажи −$20 → операционный поток −$8; в инвестиционном потоке вся выручка от продажи +$120 → деньги +$112. Баланс: деньги +$112, ОС −$100 → активы +$12; нераспределённая прибыль +$12.</div>\n<div><div>Пояснение</div>Почему вычитаем прибыль от продажи, если она денежная? Это переклассификация: все $120 показываются в инвестиционном потоке, и чтобы не учесть $20 дважды, их убирают из операционного. Итог +$112 = $120 − налог $8.</div>\n</div>"}, {"id": 1790385598355, "topic": "620f982081e3e73e", "sec": "IB Accounting (BIWS) EN-RU::3. Single-Step Scenarios — Одношаговые сценарии", "q": "Single-Step Scenarios · Одношаговые сценарии Walk me through the 3 statements when there's an Asset Write-Down of $100. Что происходит при списании (обесценении) актива на $100?", "a": ["3 statements · в трёх отчётах (tax 40%) IS / ОПУ Прибыль до налога −100; ЧП −60 CFS / ОДДС ЧП −60; +100 списание → деньги +40 BS / Баланс Активы: деньги +40, актив −100 = −60. Пассивы: нераспр. прибыль −60 Answer (EN) IS: Pre-Tax Income −$100, Net Income −$60. CFS: Net Income −$60, add back the non-cash $100 → cash +$40. BS: Cash +$40, the Asset −$100 → Assets −$60; Retained Earnings −$60. Ответ (RU) ОПУ: прибыль до налога −$100, чистая прибыль −$60. ОДДС: чистая прибыль −$60, прибавляем неденежное списание +$100 → деньги +$40. Баланс: деньги +$40, актив −$100 → активы −$60; нераспределённая прибыль −$60. Пояснение Тот же шаблон, что с амортизацией, только в 10 раз больше. Оговорка из гайда: в реальности списания не всегда уменьшают налог (см. продвинутый раздел про обесценение гудвила)."], "frontHtml": "<div><div>Single-Step Scenarios · Одношаговые сценарии</div>\n<div>Walk me through the 3 statements when there&#x27;s an Asset Write-Down of $100.</div>\n<div>Что происходит при списании (обесценении) актива на $100?</div></div>", "backHtml": "<div>\n<div><div>3 statements · в трёх отчётах (tax 40%)</div>\n<table><tr><td>IS / ОПУ</td><td>Прибыль до налога −100; ЧП −60</td></tr>\n<tr><td>CFS / ОДДС</td><td>ЧП −60; +100 списание → деньги +40</td></tr>\n<tr><td>BS / Баланс</td><td>Активы: деньги +40, актив −100 = −60. Пассивы: нераспр. прибыль −60</td></tr></table></div>\n<div><div>Answer (EN)</div>IS: Pre-Tax Income −$100, Net Income −$60. CFS: Net Income −$60, add back the non-cash $100 → cash +$40. BS: Cash +$40, the Asset −$100 → Assets −$60; Retained Earnings −$60.</div>\n<div><div>Ответ (RU)</div>ОПУ: прибыль до налога −$100, чистая прибыль −$60. ОДДС: чистая прибыль −$60, прибавляем неденежное списание +$100 → деньги +$40. Баланс: деньги +$40, актив −$100 → активы −$60; нераспределённая прибыль −$60.</div>\n<div><div>Пояснение</div>Тот же шаблон, что с амортизацией, только в 10 раз больше. Оговорка из гайда: в реальности списания не всегда уменьшают налог (см. продвинутый раздел про обесценение гудвила).</div>\n</div>"}, {"id": 1790385598357, "topic": "620f982081e3e73e", "sec": "IB Accounting (BIWS) EN-RU::3. Single-Step Scenarios — Одношаговые сценарии", "q": "Single-Step Scenarios · Одношаговые сценарии Explain what happens on the 3 statements when a company issues $100 worth of shares to investors. Что происходит, когда компания выпускает акции на $100?", "a": ["3 statements · в трёх отчётах (tax 40%) IS / ОПУ Без изменений CFS / ОДДС Финансовый поток +100 → деньги +100 BS / Баланс Активы: деньги +100. Пассивы: акц. капитал и APIC +100 Answer (EN) IS: no changes (doesn't affect taxes, not tied to the current period). CFS: CFF +$100, cash +$100. BS: Cash +$100; Common Stock & APIC +$100. Ответ (RU) ОПУ: без изменений (не влияет на налог и не относится к текущему периоду). ОДДС: финансовый поток +$100, деньги +$100. Баланс: деньги +$100; акционерный капитал и эмиссионный доход +$100. Пояснение APIC (Additional Paid-In Capital) — добавочный капитал / эмиссионный доход. У Молчанова: Д-т Деньги К-т Уставный капитал (задача 7-1, оп. 1) — тип «А+ П+»."], "frontHtml": "<div><div>Single-Step Scenarios · Одношаговые сценарии</div>\n<div>Explain what happens on the 3 statements when a company issues $100 worth of shares to investors.</div>\n<div>Что происходит, когда компания выпускает акции на $100?</div></div>", "backHtml": "<div>\n<div><div>3 statements · в трёх отчётах (tax 40%)</div>\n<table><tr><td>IS / ОПУ</td><td>Без изменений</td></tr>\n<tr><td>CFS / ОДДС</td><td>Финансовый поток +100 → деньги +100</td></tr>\n<tr><td>BS / Баланс</td><td>Активы: деньги +100. Пассивы: акц. капитал и APIC +100</td></tr></table></div>\n<div><div>Answer (EN)</div>IS: no changes (doesn&#x27;t affect taxes, not tied to the current period). CFS: CFF +$100, cash +$100. BS: Cash +$100; Common Stock &amp; APIC +$100.</div>\n<div><div>Ответ (RU)</div>ОПУ: без изменений (не влияет на налог и не относится к текущему периоду). ОДДС: финансовый поток +$100, деньги +$100. Баланс: деньги +$100; акционерный капитал и эмиссионный доход +$100.</div>\n<div><div>Пояснение</div>APIC (Additional Paid-In Capital) — добавочный капитал / эмиссионный доход. У Молчанова: Д-т Деньги К-т Уставный капитал (задача 7-1, оп. 1) — тип «А+ П+».</div>\n</div>"}, {"id": 1790385598359, "topic": "620f982081e3e73e", "sec": "IB Accounting (BIWS) EN-RU::3. Single-Step Scenarios — Одношаговые сценарии", "q": "Single-Step Scenarios · Одношаговые сценарии Instead of issuing $100 of stock to investors, the company issues $100 of stock to employees as Stock-Based Compensation. What happens? Компания выдаёт сотрудникам акции на $100 как вознаграждение (SBC). Что происходит?", "a": ["3 statements · в трёх отчётах (tax 40%) IS / ОПУ Прибыль до налога −100; ЧП −60 CFS / ОДДС ЧП −60; +100 SBC → деньги +40 BS / Баланс Активы: деньги +40. Пассивы: APIC +100, нераспр. прибыль −60 = +40 Answer (EN) IS: it's a current, tax-deductible expense — Pre-Tax Income −$100, Net Income −$60. CFS: Net Income −$60, add back non-cash SBC $100 → cash +$40. BS: Cash +$40; Common Stock & APIC +$100, Retained Earnings −$60 → Equity +$40. Ответ (RU) ОПУ: это расход текущего периода, уменьшающий налог — прибыль до налога −$100, чистая прибыль −$60. ОДДС: чистая прибыль −$60, прибавляем неденежный SBC +$100 → деньги +$40. Баланс: деньги +$40; акционерный капитал и APIC +$100, нераспределённая прибыль −$60 → капитал +$40. Пояснение Как любой неденежный расход, SBC уменьшает прибыль, экономит налог и меняет ещё одну статью баланса — здесь это APIC, потому что сотрудники получили акции. Сравни с предыдущим вопросом: акции инвесторам — не расход, акции сотрудникам — расход (оплата труда)."], "frontHtml": "<div><div>Single-Step Scenarios · Одношаговые сценарии</div>\n<div>Instead of issuing $100 of stock to investors, the company issues $100 of stock to employees as Stock-Based Compensation. What happens?</div>\n<div>Компания выдаёт сотрудникам акции на $100 как вознаграждение (SBC). Что происходит?</div></div>", "backHtml": "<div>\n<div><div>3 statements · в трёх отчётах (tax 40%)</div>\n<table><tr><td>IS / ОПУ</td><td>Прибыль до налога −100; ЧП −60</td></tr>\n<tr><td>CFS / ОДДС</td><td>ЧП −60; +100 SBC → деньги +40</td></tr>\n<tr><td>BS / Баланс</td><td>Активы: деньги +40. Пассивы: APIC +100, нераспр. прибыль −60 = +40</td></tr></table></div>\n<div><div>Answer (EN)</div>IS: it&#x27;s a current, tax-deductible expense — Pre-Tax Income −$100, Net Income −$60. CFS: Net Income −$60, add back non-cash SBC $100 → cash +$40. BS: Cash +$40; Common Stock &amp; APIC +$100, Retained Earnings −$60 → Equity +$40.</div>\n<div><div>Ответ (RU)</div>ОПУ: это расход текущего периода, уменьшающий налог — прибыль до налога −$100, чистая прибыль −$60. ОДДС: чистая прибыль −$60, прибавляем неденежный SBC +$100 → деньги +$40. Баланс: деньги +$40; акционерный капитал и APIC +$100, нераспределённая прибыль −$60 → капитал +$40.</div>\n<div><div>Пояснение</div>Как любой неденежный расход, SBC уменьшает прибыль, экономит налог и меняет ещё одну статью баланса — здесь это APIC, потому что сотрудники получили акции. Сравни с предыдущим вопросом: акции инвесторам — не расход, акции сотрудникам — расход (оплата труда).</div>\n</div>"}, {"id": 1790385598361, "topic": "620f982081e3e73e", "sec": "IB Accounting (BIWS) EN-RU::3. Single-Step Scenarios — Одношаговые сценарии", "q": "Single-Step Scenarios · Одношаговые сценарии A company issues $100 in Dividends. How do the 3 statements change? Компания выплачивает дивиденды $100. Что происходит?", "a": ["3 statements · в трёх отчётах (tax 40%) IS / ОПУ Без изменений CFS / ОДДС Финансовый поток −100 → деньги −100 BS / Баланс Активы: деньги −100. Пассивы: нераспр. прибыль −100 Answer (EN) IS: no changes — dividends are a financing activity and not tax-deductible. CFS: CFF −$100, cash −$100. BS: Cash −$100; Retained Earnings −$100. Ответ (RU) ОПУ: без изменений — дивиденды относятся к финансовой деятельности и не уменьшают налог. ОДДС: финансовый поток −$100, деньги −$100. Баланс: деньги −$100; нераспределённая прибыль −$100. Пояснение Точно как у Молчанова в задаче 7-2: дивиденды — не расход, это распределение прибыли собственникам (оп. 3 — начисление из нераспределённой прибыли, оп. 15 — выплата)."], "frontHtml": "<div><div>Single-Step Scenarios · Одношаговые сценарии</div>\n<div>A company issues $100 in Dividends. How do the 3 statements change?</div>\n<div>Компания выплачивает дивиденды $100. Что происходит?</div></div>", "backHtml": "<div>\n<div><div>3 statements · в трёх отчётах (tax 40%)</div>\n<table><tr><td>IS / ОПУ</td><td>Без изменений</td></tr>\n<tr><td>CFS / ОДДС</td><td>Финансовый поток −100 → деньги −100</td></tr>\n<tr><td>BS / Баланс</td><td>Активы: деньги −100. Пассивы: нераспр. прибыль −100</td></tr></table></div>\n<div><div>Answer (EN)</div>IS: no changes — dividends are a financing activity and not tax-deductible. CFS: CFF −$100, cash −$100. BS: Cash −$100; Retained Earnings −$100.</div>\n<div><div>Ответ (RU)</div>ОПУ: без изменений — дивиденды относятся к финансовой деятельности и не уменьшают налог. ОДДС: финансовый поток −$100, деньги −$100. Баланс: деньги −$100; нераспределённая прибыль −$100.</div>\n<div><div>Пояснение</div>Точно как у Молчанова в задаче 7-2: дивиденды — не расход, это распределение прибыли собственникам (оп. 3 — начисление из нераспределённой прибыли, оп. 15 — выплата).</div>\n</div>"}, {"id": 1790385598363, "topic": "620f982081e3e73e", "sec": "IB Accounting (BIWS) EN-RU::3. Single-Step Scenarios — Одношаговые сценарии", "q": "Single-Step Scenarios · Одношаговые сценарии A company recorded $100 income tax expense, all paid in cash. Now only $90 is paid in cash and $10 is deferred to future periods. How do the statements change? Налог $100: раньше весь платили сразу, теперь $90 сейчас и $10 отсрочено. Что меняется?", "a": ["3 statements · в трёх отчётах (tax 40%) IS / ОПУ Без изменений CFS / ОДДС Отложенный налог +10 → деньги +10 BS / Баланс Активы: деньги +10. Пассивы: ОНО (DTL) +10 Answer (EN) IS: nothing — current and deferred taxes are both just 'Taxes'; Net Income changes only if total taxes change. CFS: add back $10 of Deferred Taxes in CFO → cash +$10. BS: Cash +$10; Deferred Tax Liability +$10. Ответ (RU) ОПУ: ничего — текущий и отложенный налог в сумме дают тот же налог; чистая прибыль меняется только при изменении общей суммы налога. ОДДС: прибавляем $10 отложенного налога в операционном потоке → деньги +$10. Баланс: деньги +$10; отложенное налоговое обязательство +$10. Пояснение Отложенный налог экономит деньги сейчас за счёт дополнительных налоговых платежей в будущем. В российском учёте это ОНО — отложенное налоговое обязательство (ПБУ 18/02)."], "frontHtml": "<div><div>Single-Step Scenarios · Одношаговые сценарии</div>\n<div>A company recorded $100 income tax expense, all paid in cash. Now only $90 is paid in cash and $10 is deferred to future periods. How do the statements change?</div>\n<div>Налог $100: раньше весь платили сразу, теперь $90 сейчас и $10 отсрочено. Что меняется?</div></div>", "backHtml": "<div>\n<div><div>3 statements · в трёх отчётах (tax 40%)</div>\n<table><tr><td>IS / ОПУ</td><td>Без изменений</td></tr>\n<tr><td>CFS / ОДДС</td><td>Отложенный налог +10 → деньги +10</td></tr>\n<tr><td>BS / Баланс</td><td>Активы: деньги +10. Пассивы: ОНО (DTL) +10</td></tr></table></div>\n<div><div>Answer (EN)</div>IS: nothing — current and deferred taxes are both just &#x27;Taxes&#x27;; Net Income changes only if total taxes change. CFS: add back $10 of Deferred Taxes in CFO → cash +$10. BS: Cash +$10; Deferred Tax Liability +$10.</div>\n<div><div>Ответ (RU)</div>ОПУ: ничего — текущий и отложенный налог в сумме дают тот же налог; чистая прибыль меняется только при изменении общей суммы налога. ОДДС: прибавляем $10 отложенного налога в операционном потоке → деньги +$10. Баланс: деньги +$10; отложенное налоговое обязательство +$10.</div>\n<div><div>Пояснение</div>Отложенный налог экономит деньги сейчас за счёт дополнительных налоговых платежей в будущем. В российском учёте это ОНО — отложенное налоговое обязательство (ПБУ 18/02).</div>\n</div>"}, {"id": 1790385598365, "topic": "620f982081e3e73e", "sec": "IB Accounting (BIWS) EN-RU::3. Single-Step Scenarios — Одношаговые сценарии", "q": "Single-Step Scenarios · Одношаговые сценарии Walk me through a $100 'bailout' of a company and how it affects the 3 statements. Как «спасение» компании государством на $100 отражается в отчётах?", "a": ["3 statements · в трёх отчётах (tax 40%) IS / ОПУ Без изменений CFS / ОДДС Финансовый поток +100 → деньги +100 BS / Баланс Активы: деньги +100. Пассивы: капитал (акции/преф.) +100 Answer (EN) First confirm the type (debt, equity, combination). Most common is an equity or Preferred Stock investment. IS: no changes. CFS: CFF +$100, cash +$100. BS: Cash +$100; Shareholders' Equity +$100 (Common Stock & APIC, or Preferred Stock). Ответ (RU) Сначала уточни тип: долг, капитал или комбинация. Чаще всего это вложение в капитал или привилегированные акции. ОПУ: без изменений. ОДДС: финансовый поток +$100, деньги +$100. Баланс: деньги +$100; капитал +$100 (обыкновенные или привилегированные акции). Пояснение Это обычный выпуск акций. Главный навык здесь — задать уточняющий вопрос. Если бы это был кредит, в пассиве вырос бы долг, а не капитал."], "frontHtml": "<div><div>Single-Step Scenarios · Одношаговые сценарии</div>\n<div>Walk me through a $100 &#x27;bailout&#x27; of a company and how it affects the 3 statements.</div>\n<div>Как «спасение» компании государством на $100 отражается в отчётах?</div></div>", "backHtml": "<div>\n<div><div>3 statements · в трёх отчётах (tax 40%)</div>\n<table><tr><td>IS / ОПУ</td><td>Без изменений</td></tr>\n<tr><td>CFS / ОДДС</td><td>Финансовый поток +100 → деньги +100</td></tr>\n<tr><td>BS / Баланс</td><td>Активы: деньги +100. Пассивы: капитал (акции/преф.) +100</td></tr></table></div>\n<div><div>Answer (EN)</div>First confirm the type (debt, equity, combination). Most common is an equity or Preferred Stock investment. IS: no changes. CFS: CFF +$100, cash +$100. BS: Cash +$100; Shareholders&#x27; Equity +$100 (Common Stock &amp; APIC, or Preferred Stock).</div>\n<div><div>Ответ (RU)</div>Сначала уточни тип: долг, капитал или комбинация. Чаще всего это вложение в капитал или привилегированные акции. ОПУ: без изменений. ОДДС: финансовый поток +$100, деньги +$100. Баланс: деньги +$100; капитал +$100 (обыкновенные или привилегированные акции).</div>\n<div><div>Пояснение</div>Это обычный выпуск акций. Главный навык здесь — задать уточняющий вопрос. Если бы это был кредит, в пассиве вырос бы долг, а не капитал.</div>\n</div>"}, {"id": 1790385598367, "topic": "620f982081e3e73e", "sec": "IB Accounting (BIWS) EN-RU::3. Single-Step Scenarios — Одношаговые сценарии", "q": "Single-Step Scenarios · Одношаговые сценарии Walk me through a $100 Write-Down of Debt (a Liability) and how it affects the 3 statements. Как списание долга (обязательства) на $100 влияет на отчёты?", "a": ["3 statements · в трёх отчётах (tax 40%) IS / ОПУ Прибыль до налога +100; ЧП +60 CFS / ОДДС ЧП +60; −100 неденежный доход → деньги −40 BS / Баланс Активы: деньги −40. Пассивы: долг −100, нераспр. прибыль +60 = −40 Answer (EN) Counter-intuitive: writing down a Liability is a gain on the IS. IS: Pre-Tax Income +$100, Net Income +$60. CFS: Net Income +$60, subtract the non-cash $100 gain → cash −$40. BS: Cash −$40; Debt −$100, Retained Earnings +$60 → both sides −$40. Ответ (RU) Контринтуитивно: списание обязательства — это доход в ОПУ. ОПУ: прибыль до налога +$100, чистая прибыль +$60. ОДДС: чистая прибыль +$60, вычитаем неденежный доход −$100 → деньги −$40. Баланс: деньги −$40; долг −$100, нераспределённая прибыль +$60 → обе стороны −$40. Пояснение Почему деньги уменьшились? Появился налогооблагаемый доход, налог $40 платим реальными деньгами, а сам доход неденежный. Списание актива «плохо» (меньше будущих денег), списание обязательства «хорошо» (меньше будущих выплат)."], "frontHtml": "<div><div>Single-Step Scenarios · Одношаговые сценарии</div>\n<div>Walk me through a $100 Write-Down of Debt (a Liability) and how it affects the 3 statements.</div>\n<div>Как списание долга (обязательства) на $100 влияет на отчёты?</div></div>", "backHtml": "<div>\n<div><div>3 statements · в трёх отчётах (tax 40%)</div>\n<table><tr><td>IS / ОПУ</td><td>Прибыль до налога +100; ЧП +60</td></tr>\n<tr><td>CFS / ОДДС</td><td>ЧП +60; −100 неденежный доход → деньги −40</td></tr>\n<tr><td>BS / Баланс</td><td>Активы: деньги −40. Пассивы: долг −100, нераспр. прибыль +60 = −40</td></tr></table></div>\n<div><div>Answer (EN)</div>Counter-intuitive: writing down a Liability is a gain on the IS. IS: Pre-Tax Income +$100, Net Income +$60. CFS: Net Income +$60, subtract the non-cash $100 gain → cash −$40. BS: Cash −$40; Debt −$100, Retained Earnings +$60 → both sides −$40.</div>\n<div><div>Ответ (RU)</div>Контринтуитивно: списание обязательства — это доход в ОПУ. ОПУ: прибыль до налога +$100, чистая прибыль +$60. ОДДС: чистая прибыль +$60, вычитаем неденежный доход −$100 → деньги −$40. Баланс: деньги −$40; долг −$100, нераспределённая прибыль +$60 → обе стороны −$40.</div>\n<div><div>Пояснение</div>Почему деньги уменьшились? Появился налогооблагаемый доход, налог $40 платим реальными деньгами, а сам доход неденежный. Списание актива «плохо» (меньше будущих денег), списание обязательства «хорошо» (меньше будущих выплат).</div>\n</div>"}, {"id": 1790385598369, "topic": "620f982081e3e73e", "sec": "IB Accounting (BIWS) EN-RU::3. Single-Step Scenarios — Одношаговые сценарии", "q": "Single-Step Scenarios · Одношаговые сценарии If writing down Liabilities boosts Net Income, why don't companies do it all the time? Если списание долга увеличивает прибыль, почему компании не делают это постоянно?", "a": ["Answer (EN) Like asking why not declare bankruptcy whenever you have debt: it helps short-term but destroys credibility and the ability to borrow in the future. Investors would stop trusting the company, which hurts far more than a lower Net Income. Ответ (RU) Это как спросить, почему бы не объявлять банкротство каждый раз, когда есть долги: в краткосрочной перспективе помогает, но уничтожает репутацию и возможность занимать в будущем. Инвесторы перестанут доверять компании — это вредит намного сильнее, чем низкая прибыль. Пояснение Списание долга возможно только по соглашению с кредиторами (реструктуризация) или через банкротство. Кредиторы теряют деньги и в следующий раз либо не дадут в долг, либо потребуют гораздо более высокую ставку."], "frontHtml": "<div><div>Single-Step Scenarios · Одношаговые сценарии</div>\n<div>If writing down Liabilities boosts Net Income, why don&#x27;t companies do it all the time?</div>\n<div>Если списание долга увеличивает прибыль, почему компании не делают это постоянно?</div></div>", "backHtml": "<div>\n\n<div><div>Answer (EN)</div>Like asking why not declare bankruptcy whenever you have debt: it helps short-term but destroys credibility and the ability to borrow in the future. Investors would stop trusting the company, which hurts far more than a lower Net Income.</div>\n<div><div>Ответ (RU)</div>Это как спросить, почему бы не объявлять банкротство каждый раз, когда есть долги: в краткосрочной перспективе помогает, но уничтожает репутацию и возможность занимать в будущем. Инвесторы перестанут доверять компании — это вредит намного сильнее, чем низкая прибыль.</div>\n<div><div>Пояснение</div>Списание долга возможно только по соглашению с кредиторами (реструктуризация) или через банкротство. Кредиторы теряют деньги и в следующий раз либо не дадут в долг, либо потребуют гораздо более высокую ставку.</div>\n</div>"}, {"id": 1790385598371, "topic": "620f982081e3e73e", "sec": "IB Accounting (BIWS) EN-RU::3. Single-Step Scenarios — Одношаговые сценарии", "q": "Single-Step Scenarios · Одношаговые сценарии What's the difference between LIFO and FIFO? Walk me through an example. Чем LIFO отличается от FIFO? Приведите пример.", "a": ["Answer (EN) Two ways to value Inventory and COGS. LIFO (Last-In, First-Out) uses the most recent purchase costs for COGS; FIFO (First-In, First-Out) uses the oldest. Example: start with 10 units at $10; buy 10 units each quarter at $12, $15, $17, $20; sell 40 units at $30 (revenue $1,200). LIFO COGS = 120+150+170+200 = $640; FIFO COGS = 100+120+150+170 = $540. When prices rise, LIFO gives higher COGS, lower profit and lower ending Inventory. IFRS does not allow LIFO. Ответ (RU) Два способа оценки запасов и себестоимости. LIFO («последним пришёл — первым ушёл») берёт в себестоимость цены последних закупок, FIFO («первым пришёл — первым ушёл») — самых ранних. Пример: 10 единиц по $10 на начало; закупки по 10 единиц за $12, $15, $17, $20; продано 40 единиц по $30 (выручка $1200). Себестоимость LIFO = 640, FIFO = 540. При росте цен LIFO даёт большую себестоимость, меньшую прибыль и меньший остаток запасов. МСФО запрещает LIFO. Пояснение В России LIFO тоже запрещён (ФСБУ 5/2019 допускает FIFO, среднюю себестоимость и оценку по стоимости единицы). Зачем американским компаниям LIFO при росте цен: меньше прибыль — меньше налог. Разница в остатке запасов: FIFO на $100 больше, чем LIFO."], "frontHtml": "<div><div>Single-Step Scenarios · Одношаговые сценарии</div>\n<div>What&#x27;s the difference between LIFO and FIFO? Walk me through an example.</div>\n<div>Чем LIFO отличается от FIFO? Приведите пример.</div></div>", "backHtml": "<div>\n\n<div><div>Answer (EN)</div>Two ways to value Inventory and COGS. LIFO (Last-In, First-Out) uses the most recent purchase costs for COGS; FIFO (First-In, First-Out) uses the oldest. Example: start with 10 units at $10; buy 10 units each quarter at $12, $15, $17, $20; sell 40 units at $30 (revenue $1,200). LIFO COGS = 120+150+170+200 = $640; FIFO COGS = 100+120+150+170 = $540. When prices rise, LIFO gives higher COGS, lower profit and lower ending Inventory. IFRS does not allow LIFO.</div>\n<div><div>Ответ (RU)</div>Два способа оценки запасов и себестоимости. LIFO («последним пришёл — первым ушёл») берёт в себестоимость цены последних закупок, FIFO («первым пришёл — первым ушёл») — самых ранних. Пример: 10 единиц по $10 на начало; закупки по 10 единиц за $12, $15, $17, $20; продано 40 единиц по $30 (выручка $1200). Себестоимость LIFO = 640, FIFO = 540. При росте цен LIFO даёт большую себестоимость, меньшую прибыль и меньший остаток запасов. МСФО запрещает LIFO.</div>\n<div><div>Пояснение</div>В России LIFO тоже запрещён (ФСБУ 5/2019 допускает FIFO, среднюю себестоимость и оценку по стоимости единицы). Зачем американским компаниям LIFO при росте цен: меньше прибыль — меньше налог. Разница в остатке запасов: FIFO на $100 больше, чем LIFO.</div>\n</div>"}, {"id": 1790385598373, "topic": "620f982081e3e73e", "sec": "IB Accounting (BIWS) EN-RU::4. Multi-Step Scenarios — Многошаговые сценарии", "q": "Multi-Step Scenarios · Многошаговые сценарии Apple buys $100 of new iPad factories with debt. How are the 3 statements affected at the start of Year 1, before anything else happens? Apple покупает заводы на $100 в долг. Что происходит в начале первого года?", "a": ["3 statements · в трёх отчётах (tax 40%) IS / ОПУ Без изменений CFS / ОДДС CFI −100 (капвложения); CFF +100 (долг) → деньги 0 BS / Баланс Активы: ОС +100. Пассивы: долг +100 Answer (EN) IS: no changes yet. CFS: CapEx of $100 in CFI (−$100) and $100 Debt raised in CFF (+$100) — cash unchanged. BS: PP&E +$100; Debt +$100. Ответ (RU) ОПУ: пока без изменений. ОДДС: капвложения −$100 в инвестиционном потоке, привлечение долга +$100 в финансовом — деньги не изменились. Баланс: ОС +$100; долг +$100. Пояснение Тип операции «А+ П+». Проводки по Молчанову: Д-т Деньги К-т Кредиты 100, затем Д-т ОС К-т Деньги 100. В ОПУ ничего нет: ни амортизации, ни процентов ещё не начислено."], "frontHtml": "<div><div>Multi-Step Scenarios · Многошаговые сценарии</div>\n<div>Apple buys $100 of new iPad factories with debt. How are the 3 statements affected at the start of Year 1, before anything else happens?</div>\n<div>Apple покупает заводы на $100 в долг. Что происходит в начале первого года?</div></div>", "backHtml": "<div>\n<div><div>3 statements · в трёх отчётах (tax 40%)</div>\n<table><tr><td>IS / ОПУ</td><td>Без изменений</td></tr>\n<tr><td>CFS / ОДДС</td><td>CFI −100 (капвложения); CFF +100 (долг) → деньги 0</td></tr>\n<tr><td>BS / Баланс</td><td>Активы: ОС +100. Пассивы: долг +100</td></tr></table></div>\n<div><div>Answer (EN)</div>IS: no changes yet. CFS: CapEx of $100 in CFI (−$100) and $100 Debt raised in CFF (+$100) — cash unchanged. BS: PP&amp;E +$100; Debt +$100.</div>\n<div><div>Ответ (RU)</div>ОПУ: пока без изменений. ОДДС: капвложения −$100 в инвестиционном потоке, привлечение долга +$100 в финансовом — деньги не изменились. Баланс: ОС +$100; долг +$100.</div>\n<div><div>Пояснение</div>Тип операции «А+ П+». Проводки по Молчанову: Д-т Деньги К-т Кредиты 100, затем Д-т ОС К-т Деньги 100. В ОПУ ничего нет: ни амортизации, ни процентов ещё не начислено.</div>\n</div>"}, {"id": 1790385598375, "topic": "620f982081e3e73e", "sec": "IB Accounting (BIWS) EN-RU::4. Multi-Step Scenarios — Многошаговые сценарии", "q": "Multi-Step Scenarios · Многошаговые сценарии Go to the start of Year 2. The debt is high-yield (no principal paid), interest rate 10%, factories depreciate 10% per year. What happens? Начало второго года: проценты 10%, амортизация 10% в год, тело долга не гасится. Что происходит?", "a": ["3 statements · в трёх отчётах (tax 40%) IS / ОПУ Амортизация −10, проценты −10 → прибыль до налога −20; ЧП −12 CFS / ОДДС ЧП −12; +10 амортизация → деньги −2 BS / Баланс Активы: деньги −2, ОС −10 = −12. Пассивы: нераспр. прибыль −12 Answer (EN) IS: Depreciation $10 and Interest Expense $10 → Pre-Tax Income −$20, Net Income −$12. CFS: Net Income −$12, add back $10 Depreciation → cash −$2. BS: Cash −$2, PP&E −$10 → Assets −$12; Retained Earnings −$12. Debt unchanged. Ответ (RU) ОПУ: амортизация $10 и проценты $10 → прибыль до налога −$20, чистая прибыль −$12. ОДДС: чистая прибыль −$12, прибавляем амортизацию +$10 → деньги −$2. Баланс: деньги −$2, ОС −$10 → активы −$12; нераспределённая прибыль −$12. Долг не меняется. Пояснение Почему деньги −$2: проценты $10 — реальная трата, но налог уменьшился на $8 (40% от $20 расходов). −10 + 8 = −2. Проценты не показываем отдельно в ОДДС: они уже внутри чистой прибыли."], "frontHtml": "<div><div>Multi-Step Scenarios · Многошаговые сценарии</div>\n<div>Go to the start of Year 2. The debt is high-yield (no principal paid), interest rate 10%, factories depreciate 10% per year. What happens?</div>\n<div>Начало второго года: проценты 10%, амортизация 10% в год, тело долга не гасится. Что происходит?</div></div>", "backHtml": "<div>\n<div><div>3 statements · в трёх отчётах (tax 40%)</div>\n<table><tr><td>IS / ОПУ</td><td>Амортизация −10, проценты −10 → прибыль до налога −20; ЧП −12</td></tr>\n<tr><td>CFS / ОДДС</td><td>ЧП −12; +10 амортизация → деньги −2</td></tr>\n<tr><td>BS / Баланс</td><td>Активы: деньги −2, ОС −10 = −12. Пассивы: нераспр. прибыль −12</td></tr></table></div>\n<div><div>Answer (EN)</div>IS: Depreciation $10 and Interest Expense $10 → Pre-Tax Income −$20, Net Income −$12. CFS: Net Income −$12, add back $10 Depreciation → cash −$2. BS: Cash −$2, PP&amp;E −$10 → Assets −$12; Retained Earnings −$12. Debt unchanged.</div>\n<div><div>Ответ (RU)</div>ОПУ: амортизация $10 и проценты $10 → прибыль до налога −$20, чистая прибыль −$12. ОДДС: чистая прибыль −$12, прибавляем амортизацию +$10 → деньги −$2. Баланс: деньги −$2, ОС −$10 → активы −$12; нераспределённая прибыль −$12. Долг не меняется.</div>\n<div><div>Пояснение</div>Почему деньги −$2: проценты $10 — реальная трата, но налог уменьшился на $8 (40% от $20 расходов). −10 + 8 = −2. Проценты не показываем отдельно в ОДДС: они уже внутри чистой прибыли.</div>\n</div>"}, {"id": 1790385598377, "topic": "620f982081e3e73e", "sec": "IB Accounting (BIWS) EN-RU::4. Multi-Step Scenarios — Многошаговые сценарии", "q": "Multi-Step Scenarios · Многошаговые сценарии At the end of Year 2 the factories break down and are written down to $0. The loan must be paid back. Walk me through the statements from start of Year 2 to end of Year 2 only. В конце второго года заводы сломались и списаны до нуля, кредит нужно вернуть. Что происходит за второй год?", "a": ["3 statements · в трёх отчётах (tax 40%) IS / ОПУ Амортизация −10, списание −80, проценты −10 → прибыль до налога −100; ЧП −60 CFS / ОДДС ЧП −60; +90 неденежные → CFO +30; CFF −100 → деньги −70 BS / Баланс Активы: деньги −70, ОС −90 = −160. Пассивы: долг −100, нераспр. прибыль −60 = −160 Answer (EN) Factory value after 2 years = $80; that's written down. IS: Depreciation $10 + Write-Down $80 + Interest $10 → Pre-Tax Income −$100, Net Income −$60. CFS: Net Income −$60, add back $10 + $80 non-cash → +$30; CFF −$100 loan repayment → cash −$70. BS: Cash −$70, PP&E −$90 → Assets −$160; Debt −$100, Retained Earnings −$60 → −$160. Ответ (RU) Стоимость заводов через 2 года = $80, её и списываем. ОПУ: амортизация $10 + списание $80 + проценты $10 → прибыль до налога −$100, чистая прибыль −$60. ОДДС: чистая прибыль −$60, прибавляем неденежные $10 + $80 → +$30; финансовый поток −$100 (возврат кредита) → деньги −$70. Баланс: деньги −$70, ОС −$90 → активы −$160; долг −$100, нераспределённая прибыль −$60 → −$160. Пояснение Ловушки: (1) не забыть амортизацию и проценты второго года; (2) списывается остаточная стоимость $80, а не первоначальная $100; (3) возврат тела кредита — только в ОДДС и балансе, не в ОПУ."], "frontHtml": "<div><div>Multi-Step Scenarios · Многошаговые сценарии</div>\n<div>At the end of Year 2 the factories break down and are written down to $0. The loan must be paid back. Walk me through the statements from start of Year 2 to end of Year 2 only.</div>\n<div>В конце второго года заводы сломались и списаны до нуля, кредит нужно вернуть. Что происходит за второй год?</div></div>", "backHtml": "<div>\n<div><div>3 statements · в трёх отчётах (tax 40%)</div>\n<table><tr><td>IS / ОПУ</td><td>Амортизация −10, списание −80, проценты −10 → прибыль до налога −100; ЧП −60</td></tr>\n<tr><td>CFS / ОДДС</td><td>ЧП −60; +90 неденежные → CFO +30; CFF −100 → деньги −70</td></tr>\n<tr><td>BS / Баланс</td><td>Активы: деньги −70, ОС −90 = −160. Пассивы: долг −100, нераспр. прибыль −60 = −160</td></tr></table></div>\n<div><div>Answer (EN)</div>Factory value after 2 years = $80; that&#x27;s written down. IS: Depreciation $10 + Write-Down $80 + Interest $10 → Pre-Tax Income −$100, Net Income −$60. CFS: Net Income −$60, add back $10 + $80 non-cash → +$30; CFF −$100 loan repayment → cash −$70. BS: Cash −$70, PP&amp;E −$90 → Assets −$160; Debt −$100, Retained Earnings −$60 → −$160.</div>\n<div><div>Ответ (RU)</div>Стоимость заводов через 2 года = $80, её и списываем. ОПУ: амортизация $10 + списание $80 + проценты $10 → прибыль до налога −$100, чистая прибыль −$60. ОДДС: чистая прибыль −$60, прибавляем неденежные $10 + $80 → +$30; финансовый поток −$100 (возврат кредита) → деньги −$70. Баланс: деньги −$70, ОС −$90 → активы −$160; долг −$100, нераспределённая прибыль −$60 → −$160.</div>\n<div><div>Пояснение</div>Ловушки: (1) не забыть амортизацию и проценты второго года; (2) списывается остаточная стоимость $80, а не первоначальная $100; (3) возврат тела кредита — только в ОДДС и балансе, не в ОПУ.</div>\n</div>"}, {"id": 1790385598379, "topic": "620f982081e3e73e", "sec": "IB Accounting (BIWS) EN-RU::4. Multi-Step Scenarios — Многошаговые сценарии", "q": "Multi-Step Scenarios · Многошаговые сценарии Apple orders $10 of iPad Inventory using cash. They order it but haven't manufactured or sold anything. What happens? Apple покупает запасы на $10 за деньги, ничего не произведено и не продано. Что происходит?", "a": ["3 statements · в трёх отчётах (tax 40%) IS / ОПУ Без изменений CFS / ОДДС Рост запасов −10 → деньги −10 BS / Баланс Активы: запасы +10, деньги −10. Пассивы: без изменений Answer (EN) IS: no changes. CFS: Inventory +$10 → CFO −$10, cash −$10. BS: Inventory +$10, Cash −$10 — Assets unchanged. Ответ (RU) ОПУ: без изменений. ОДДС: рост запасов → операционный поток −$10, деньги −$10. Баланс: запасы +$10, деньги −$10 — активы не изменились. Пояснение Здесь гайд пишет «order», но подразумевает, что запасы получены и оплачены. У Молчанова простой заказ — вообще не операция (задача 7-3, оп. 3): проводка появляется только при получении."], "frontHtml": "<div><div>Multi-Step Scenarios · Многошаговые сценарии</div>\n<div>Apple orders $10 of iPad Inventory using cash. They order it but haven&#x27;t manufactured or sold anything. What happens?</div>\n<div>Apple покупает запасы на $10 за деньги, ничего не произведено и не продано. Что происходит?</div></div>", "backHtml": "<div>\n<div><div>3 statements · в трёх отчётах (tax 40%)</div>\n<table><tr><td>IS / ОПУ</td><td>Без изменений</td></tr>\n<tr><td>CFS / ОДДС</td><td>Рост запасов −10 → деньги −10</td></tr>\n<tr><td>BS / Баланс</td><td>Активы: запасы +10, деньги −10. Пассивы: без изменений</td></tr></table></div>\n<div><div>Answer (EN)</div>IS: no changes. CFS: Inventory +$10 → CFO −$10, cash −$10. BS: Inventory +$10, Cash −$10 — Assets unchanged.</div>\n<div><div>Ответ (RU)</div>ОПУ: без изменений. ОДДС: рост запасов → операционный поток −$10, деньги −$10. Баланс: запасы +$10, деньги −$10 — активы не изменились.</div>\n<div><div>Пояснение</div>Здесь гайд пишет «order», но подразумевает, что запасы получены и оплачены. У Молчанова простой заказ — вообще не операция (задача 7-3, оп. 3): проводка появляется только при получении.</div>\n</div>"}, {"id": 1790385598381, "topic": "620f982081e3e73e", "sec": "IB Accounting (BIWS) EN-RU::4. Multi-Step Scenarios — Многошаговые сценарии", "q": "Multi-Step Scenarios · Многошаговые сценарии Now they sell the iPads for revenue of $20, at a cost of $10. Walk me through the 3 statements. Теперь iPad продают за $20 при себестоимости $10. Что происходит?", "a": ["3 statements · в трёх отчётах (tax 40%) IS / ОПУ Выручка +20, себестоимость −10 → прибыль до налога +10; ЧП +6 CFS / ОДДС ЧП +6; уменьшение запасов +10 → деньги +16 BS / Баланс Активы: деньги +16, запасы −10 = +6. Пассивы: нераспр. прибыль +6 Answer (EN) IS: Revenue +$20, COGS +$10 → Pre-Tax Income +$10, Net Income +$6. CFS: Net Income +$6, Inventory decreases by $10 (adds to cash) → cash +$16. BS: Cash +$16, Inventory −$10 → Assets +$6; Retained Earnings +$6. Ответ (RU) ОПУ: выручка +$20, себестоимость +$10 → прибыль до налога +$10, чистая прибыль +$6. ОДДС: чистая прибыль +$6, уменьшение запасов +$10 → деньги +$16. Баланс: деньги +$16, запасы −$10 → активы +$6; нераспределённая прибыль +$6. Пояснение Почему деньги +$16, а не +$6: покупатель заплатил $20, налог $4, а деньги за запасы ушли раньше (в прошлом шаге). 20 − 4 = 16. Сложив оба шага: деньги −10 + 16 = +6 = чистая прибыль."], "frontHtml": "<div><div>Multi-Step Scenarios · Многошаговые сценарии</div>\n<div>Now they sell the iPads for revenue of $20, at a cost of $10. Walk me through the 3 statements.</div>\n<div>Теперь iPad продают за $20 при себестоимости $10. Что происходит?</div></div>", "backHtml": "<div>\n<div><div>3 statements · в трёх отчётах (tax 40%)</div>\n<table><tr><td>IS / ОПУ</td><td>Выручка +20, себестоимость −10 → прибыль до налога +10; ЧП +6</td></tr>\n<tr><td>CFS / ОДДС</td><td>ЧП +6; уменьшение запасов +10 → деньги +16</td></tr>\n<tr><td>BS / Баланс</td><td>Активы: деньги +16, запасы −10 = +6. Пассивы: нераспр. прибыль +6</td></tr></table></div>\n<div><div>Answer (EN)</div>IS: Revenue +$20, COGS +$10 → Pre-Tax Income +$10, Net Income +$6. CFS: Net Income +$6, Inventory decreases by $10 (adds to cash) → cash +$16. BS: Cash +$16, Inventory −$10 → Assets +$6; Retained Earnings +$6.</div>\n<div><div>Ответ (RU)</div>ОПУ: выручка +$20, себестоимость +$10 → прибыль до налога +$10, чистая прибыль +$6. ОДДС: чистая прибыль +$6, уменьшение запасов +$10 → деньги +$16. Баланс: деньги +$16, запасы −$10 → активы +$6; нераспределённая прибыль +$6.</div>\n<div><div>Пояснение</div>Почему деньги +$16, а не +$6: покупатель заплатил $20, налог $4, а деньги за запасы ушли раньше (в прошлом шаге). 20 − 4 = 16. Сложив оба шага: деньги −10 + 16 = +6 = чистая прибыль.</div>\n</div>"}, {"id": 1790385598383, "topic": "620f982081e3e73e", "sec": "IB Accounting (BIWS) EN-RU::4. Multi-Step Scenarios — Многошаговые сценарии", "q": "Multi-Step Scenarios · Многошаговые сценарии A company raises $100 of Debt (5% interest, 10% yearly principal repayment) to buy $100 of Short-Term Securities paying 10% interest. What happens IMMEDIATELY after the purchase? Компания берёт долг $100 (5% годовых, гашение 10% в год) и покупает краткосрочные ценные бумаги на $100 (доходность 10%). Что происходит сразу после покупки?", "a": ["3 statements · в трёх отчётах (tax 40%) IS / ОПУ Без изменений CFS / ОДДС CFI −100 (покупка бумаг); CFF +100 (долг) → деньги 0 BS / Баланс Активы: ценные бумаги +100. Пассивы: долг +100 Answer (EN) IS: no changes yet. CFS: Purchase of Securities −$100 in CFI, Debt raised +$100 in CFF — cash unchanged. BS: Short-Term Securities +$100; Debt +$100. Ответ (RU) ОПУ: пока без изменений. ОДДС: покупка ценных бумаг −$100 в инвестиционном потоке, долг +$100 в финансовом — деньги не изменились. Баланс: краткосрочные ценные бумаги +$100; долг +$100. Пояснение Та же структура, что с покупкой заводов в долг. Краткосрочные инвестиции — оборотный актив, но их покупка идёт в инвестиционный поток, а не в операционный."], "frontHtml": "<div><div>Multi-Step Scenarios · Многошаговые сценарии</div>\n<div>A company raises $100 of Debt (5% interest, 10% yearly principal repayment) to buy $100 of Short-Term Securities paying 10% interest. What happens IMMEDIATELY after the purchase?</div>\n<div>Компания берёт долг $100 (5% годовых, гашение 10% в год) и покупает краткосрочные ценные бумаги на $100 (доходность 10%). Что происходит сразу после покупки?</div></div>", "backHtml": "<div>\n<div><div>3 statements · в трёх отчётах (tax 40%)</div>\n<table><tr><td>IS / ОПУ</td><td>Без изменений</td></tr>\n<tr><td>CFS / ОДДС</td><td>CFI −100 (покупка бумаг); CFF +100 (долг) → деньги 0</td></tr>\n<tr><td>BS / Баланс</td><td>Активы: ценные бумаги +100. Пассивы: долг +100</td></tr></table></div>\n<div><div>Answer (EN)</div>IS: no changes yet. CFS: Purchase of Securities −$100 in CFI, Debt raised +$100 in CFF — cash unchanged. BS: Short-Term Securities +$100; Debt +$100.</div>\n<div><div>Ответ (RU)</div>ОПУ: пока без изменений. ОДДС: покупка ценных бумаг −$100 в инвестиционном потоке, долг +$100 в финансовом — деньги не изменились. Баланс: краткосрочные ценные бумаги +$100; долг +$100.</div>\n<div><div>Пояснение</div>Та же структура, что с покупкой заводов в долг. Краткосрочные инвестиции — оборотный актив, но их покупка идёт в инвестиционный поток, а не в операционный.</div>\n</div>"}, {"id": 1790385598385, "topic": "620f982081e3e73e", "sec": "IB Accounting (BIWS) EN-RU::4. Multi-Step Scenarios — Многошаговые сценарии", "q": "Multi-Step Scenarios · Многошаговые сценарии What happens at the end of Year 1, after the company has earned interest, paid interest, and repaid some principal? Что происходит в конце первого года: получены и уплачены проценты, частично погашен долг?", "a": ["3 statements · в трёх отчётах (tax 40%) IS / ОПУ Процентный доход +10, процентный расход −5 → прибыль до налога +5; ЧП +3 CFS / ОДДС ЧП +3; CFF −10 (погашение долга) → деньги −7 BS / Баланс Активы: деньги −7. Пассивы: долг −10, нераспр. прибыль +3 = −7 Answer (EN) IS: Interest Income $10 (10% × $100), Interest Expense $5 (5% × $100) → Pre-Tax Income +$5, Net Income +$3. CFS: Net Income +$3; CFF −$10 principal repayment → cash −$7. BS: Cash −$7; Debt −$10, Retained Earnings +$3 → −$7. Ответ (RU) ОПУ: процентный доход $10, процентный расход $5 → прибыль до налога +$5, чистая прибыль +$3. ОДДС: чистая прибыль +$3; финансовый поток −$10 (погашение тела долга) → деньги −$7. Баланс: деньги −$7; долг −$10, нераспределённая прибыль +$3 → −$7. Пояснение Проценты (и полученные, и уплаченные) уже внутри чистой прибыли, поэтому в ОДДС отдельно не показываются. А вот погашение 10% тела долга ($10) — только в финансовом потоке."], "frontHtml": "<div><div>Multi-Step Scenarios · Многошаговые сценарии</div>\n<div>What happens at the end of Year 1, after the company has earned interest, paid interest, and repaid some principal?</div>\n<div>Что происходит в конце первого года: получены и уплачены проценты, частично погашен долг?</div></div>", "backHtml": "<div>\n<div><div>3 statements · в трёх отчётах (tax 40%)</div>\n<table><tr><td>IS / ОПУ</td><td>Процентный доход +10, процентный расход −5 → прибыль до налога +5; ЧП +3</td></tr>\n<tr><td>CFS / ОДДС</td><td>ЧП +3; CFF −10 (погашение долга) → деньги −7</td></tr>\n<tr><td>BS / Баланс</td><td>Активы: деньги −7. Пассивы: долг −10, нераспр. прибыль +3 = −7</td></tr></table></div>\n<div><div>Answer (EN)</div>IS: Interest Income $10 (10% × $100), Interest Expense $5 (5% × $100) → Pre-Tax Income +$5, Net Income +$3. CFS: Net Income +$3; CFF −$10 principal repayment → cash −$7. BS: Cash −$7; Debt −$10, Retained Earnings +$3 → −$7.</div>\n<div><div>Ответ (RU)</div>ОПУ: процентный доход $10, процентный расход $5 → прибыль до налога +$5, чистая прибыль +$3. ОДДС: чистая прибыль +$3; финансовый поток −$10 (погашение тела долга) → деньги −$7. Баланс: деньги −$7; долг −$10, нераспределённая прибыль +$3 → −$7.</div>\n<div><div>Пояснение</div>Проценты (и полученные, и уплаченные) уже внутри чистой прибыли, поэтому в ОДДС отдельно не показываются. А вот погашение 10% тела долга ($10) — только в финансовом потоке.</div>\n</div>"}, {"id": 1790385598387, "topic": "620f982081e3e73e", "sec": "IB Accounting (BIWS) EN-RU::4. Multi-Step Scenarios — Многошаговые сценарии", "q": "Multi-Step Scenarios · Многошаговые сценарии At end of Year 1, the company sells the $100 of Securities for $110 and uses the proceeds to repay the remaining $90 of Debt. Walk me through ONLY these changes. Бумаги на $100 продают за $110 и гасят оставшийся долг $90. Что происходит (только эти изменения)?", "a": ["3 statements · в трёх отчётах (tax 40%) IS / ОПУ Прибыль от продажи +10; ЧП +6 CFS / ОДДС ЧП +6; −10 прибыль от продажи → CFO −4; CFI +110; CFF −90 → деньги +16 BS / Баланс Активы: деньги +16, бумаги −100 = −84. Пассивы: долг −90, нераспр. прибыль +6 = −84 Answer (EN) IS: Gain $10 → Pre-Tax Income +$10, Net Income +$6. CFS: Net Income +$6, subtract $10 Gain → CFO −$4; CFI +$110 sale; CFF −$90 debt repayment → cash +$16. BS: Cash +$16, Securities −$100 → Assets −$84; Debt −$90, Retained Earnings +$6 → −$84. Ответ (RU) ОПУ: прибыль от продажи $10 → прибыль до налога +$10, чистая прибыль +$6. ОДДС: чистая прибыль +$6, вычитаем прибыль от продажи −$10 → операционный поток −$4; инвестиционный +$110; финансовый −$90 → деньги +$16. Баланс: деньги +$16, ценные бумаги −$100 → активы −$84; долг −$90, нераспределённая прибыль +$6 → −$84. Пояснение Та же переклассификация, что с продажей ОС: вся выручка от продажи ($110) показывается в инвестиционном потоке, а прибыль ($10) вычитается из операционного. Проверка: 110 − 90 − налог 4 = +16."], "frontHtml": "<div><div>Multi-Step Scenarios · Многошаговые сценарии</div>\n<div>At end of Year 1, the company sells the $100 of Securities for $110 and uses the proceeds to repay the remaining $90 of Debt. Walk me through ONLY these changes.</div>\n<div>Бумаги на $100 продают за $110 и гасят оставшийся долг $90. Что происходит (только эти изменения)?</div></div>", "backHtml": "<div>\n<div><div>3 statements · в трёх отчётах (tax 40%)</div>\n<table><tr><td>IS / ОПУ</td><td>Прибыль от продажи +10; ЧП +6</td></tr>\n<tr><td>CFS / ОДДС</td><td>ЧП +6; −10 прибыль от продажи → CFO −4; CFI +110; CFF −90 → деньги +16</td></tr>\n<tr><td>BS / Баланс</td><td>Активы: деньги +16, бумаги −100 = −84. Пассивы: долг −90, нераспр. прибыль +6 = −84</td></tr></table></div>\n<div><div>Answer (EN)</div>IS: Gain $10 → Pre-Tax Income +$10, Net Income +$6. CFS: Net Income +$6, subtract $10 Gain → CFO −$4; CFI +$110 sale; CFF −$90 debt repayment → cash +$16. BS: Cash +$16, Securities −$100 → Assets −$84; Debt −$90, Retained Earnings +$6 → −$84.</div>\n<div><div>Ответ (RU)</div>ОПУ: прибыль от продажи $10 → прибыль до налога +$10, чистая прибыль +$6. ОДДС: чистая прибыль +$6, вычитаем прибыль от продажи −$10 → операционный поток −$4; инвестиционный +$110; финансовый −$90 → деньги +$16. Баланс: деньги +$16, ценные бумаги −$100 → активы −$84; долг −$90, нераспределённая прибыль +$6 → −$84.</div>\n<div><div>Пояснение</div>Та же переклассификация, что с продажей ОС: вся выручка от продажи ($110) показывается в инвестиционном потоке, а прибыль ($10) вычитается из операционного. Проверка: 110 − 90 − налог 4 = +16.</div>\n</div>"}, {"id": 1790385598389, "topic": "620f982081e3e73e", "sec": "IB Accounting (BIWS) EN-RU::5. Advanced Concepts — Продвинутые понятия", "q": "Advanced Concepts · Продвинутые понятия Explain what a Deferred Tax Asset or Deferred Tax Liability is. How do they usually get created? Что такое отложенный налоговый актив и обязательство? Как они возникают?", "a": ["Answer (EN) A DTL means you must pay additional cash taxes in the future (you've underpaid now). A DTA means you can pay less cash tax in the future (you've overpaid before). Both arise from temporary differences between what can be deducted for cash (tax) purposes and for book purposes. Most common: (1) different Depreciation for book vs tax (faster for tax), (2) Asset write-ups in M&A for book but not tax, (3) pension contributions recognized differently. Ответ (RU) Отложенное налоговое обязательство (DTL) — в будущем придётся заплатить больше налога (сейчас недоплатили). Отложенный налоговый актив (DTA) — в будущем можно заплатить меньше (раньше переплатили). Оба возникают из-за временных разниц между налоговым и бухгалтерским учётом. Чаще всего: (1) разная амортизация (в налоговом учёте быстрее), (2) переоценка активов при M&A в бухучёте, но не в налоговом, (3) разный учёт пенсионных взносов. Пояснение В России это ОНА и ОНО по ПБУ 18/02 (счета 09 и 77). «Book» — отчётность для инвесторов, «tax» — налоговые декларации. Разница временная: со временем она выравнивается."], "frontHtml": "<div><div>Advanced Concepts · Продвинутые понятия</div>\n<div>Explain what a Deferred Tax Asset or Deferred Tax Liability is. How do they usually get created?</div>\n<div>Что такое отложенный налоговый актив и обязательство? Как они возникают?</div></div>", "backHtml": "<div>\n\n<div><div>Answer (EN)</div>A DTL means you must pay additional cash taxes in the future (you&#x27;ve underpaid now). A DTA means you can pay less cash tax in the future (you&#x27;ve overpaid before). Both arise from temporary differences between what can be deducted for cash (tax) purposes and for book purposes. Most common: (1) different Depreciation for book vs tax (faster for tax), (2) Asset write-ups in M&amp;A for book but not tax, (3) pension contributions recognized differently.</div>\n<div><div>Ответ (RU)</div>Отложенное налоговое обязательство (DTL) — в будущем придётся заплатить больше налога (сейчас недоплатили). Отложенный налоговый актив (DTA) — в будущем можно заплатить меньше (раньше переплатили). Оба возникают из-за временных разниц между налоговым и бухгалтерским учётом. Чаще всего: (1) разная амортизация (в налоговом учёте быстрее), (2) переоценка активов при M&amp;A в бухучёте, но не в налоговом, (3) разный учёт пенсионных взносов.</div>\n<div><div>Пояснение</div>В России это ОНА и ОНО по ПБУ 18/02 (счета 09 и 77). «Book» — отчётность для инвесторов, «tax» — налоговые декларации. Разница временная: со временем она выравнивается.</div>\n</div>"}, {"id": 1790385598391, "topic": "620f982081e3e73e", "sec": "IB Accounting (BIWS) EN-RU::5. Advanced Concepts — Продвинутые понятия", "q": "Advanced Concepts · Продвинутые понятия How can both DTAs and DTLs exist on a company's Balance Sheet at the same time? Как у компании одновременно могут быть и ОНА, и ОНО?", "a": ["Answer (EN) Because a company can owe and save on future taxes for different reasons. E.g. it may have Net Operating Losses from unprofitable early years (a DTA), while also using accelerated Depreciation for tax and straight-line for book (creating a DTL). Ответ (RU) Потому что компания может и должна, и экономить на будущих налогах — по разным причинам. Например, у неё есть налоговые убытки прошлых лет (ОНА), и одновременно она использует ускоренную амортизацию в налоговом учёте и линейную в бухгалтерском (ОНО). Пояснение NOL (Net Operating Losses) — налоговые убытки, которые можно перенести на будущее и уменьшить будущий налог. В России убытки прошлых лет тоже переносятся на будущее (с ограничением 50% налоговой базы в год)."], "frontHtml": "<div><div>Advanced Concepts · Продвинутые понятия</div>\n<div>How can both DTAs and DTLs exist on a company&#x27;s Balance Sheet at the same time?</div>\n<div>Как у компании одновременно могут быть и ОНА, и ОНО?</div></div>", "backHtml": "<div>\n\n<div><div>Answer (EN)</div>Because a company can owe and save on future taxes for different reasons. E.g. it may have Net Operating Losses from unprofitable early years (a DTA), while also using accelerated Depreciation for tax and straight-line for book (creating a DTL).</div>\n<div><div>Ответ (RU)</div>Потому что компания может и должна, и экономить на будущих налогах — по разным причинам. Например, у неё есть налоговые убытки прошлых лет (ОНА), и одновременно она использует ускоренную амортизацию в налоговом учёте и линейную в бухгалтерском (ОНО).</div>\n<div><div>Пояснение</div>NOL (Net Operating Losses) — налоговые убытки, которые можно перенести на будущее и уменьшить будущий налог. В России убытки прошлых лет тоже переносятся на будущее (с ограничением 50% налоговой базы в год).</div>\n</div>"}, {"id": 1790385598393, "topic": "620f982081e3e73e", "sec": "IB Accounting (BIWS) EN-RU::5. Advanced Concepts — Продвинутые понятия", "q": "Advanced Concepts · Продвинутые понятия How do Income Taxes Payable/Receivable differ from DTLs and DTAs? Чем текущие налоговые обязательства отличаются от отложенных?", "a": ["Answer (EN) Income Taxes Payable/Receivable are accrual accounts for taxes owed for the current year (e.g. accrued monthly, paid quarterly). DTAs and DTLs are longer-term and arise from events outside the normal course of business (temporary book-tax differences). Ответ (RU) Текущие налоги к уплате/получению — начисления по налогу текущего года (например, начисляют ежемесячно, платят поквартально). ОНА и ОНО — долгосрочные, возникают из временных разниц между бухгалтерским и налоговым учётом. Пояснение Taxes Payable — это «налог, который мы точно должны прямо сейчас» (как начисленная зарплата). DTL — это «налог, который мы будем должны в будущем из-за разницы методов учёта»."], "frontHtml": "<div><div>Advanced Concepts · Продвинутые понятия</div>\n<div>How do Income Taxes Payable/Receivable differ from DTLs and DTAs?</div>\n<div>Чем текущие налоговые обязательства отличаются от отложенных?</div></div>", "backHtml": "<div>\n\n<div><div>Answer (EN)</div>Income Taxes Payable/Receivable are accrual accounts for taxes owed for the current year (e.g. accrued monthly, paid quarterly). DTAs and DTLs are longer-term and arise from events outside the normal course of business (temporary book-tax differences).</div>\n<div><div>Ответ (RU)</div>Текущие налоги к уплате/получению — начисления по налогу текущего года (например, начисляют ежемесячно, платят поквартально). ОНА и ОНО — долгосрочные, возникают из временных разниц между бухгалтерским и налоговым учётом.</div>\n<div><div>Пояснение</div>Taxes Payable — это «налог, который мы точно должны прямо сейчас» (как начисленная зарплата). DTL — это «налог, который мы будем должны в будущем из-за разницы методов учёта».</div>\n</div>"}, {"id": 1790385598395, "topic": "620f982081e3e73e", "sec": "IB Accounting (BIWS) EN-RU::5. Advanced Concepts — Продвинутые понятия", "q": "Advanced Concepts · Продвинутые понятия Walk me through how you project revenue for a company. Как спрогнозировать выручку компании?", "a": ["Answer (EN) Simplest: assume a percentage growth rate that usually declines over time (e.g. 15%, 12%, 10%). More precise: a bottoms-up build (individual products/customers, average sale value, growth in customers and values) or a tops-down build (market size × market share). Bottoms-up is more common and credible because big-picture numbers are hard to estimate. Ответ (RU) Проще всего — задать темп роста, который обычно снижается со временем (15%, 12%, 10%). Точнее — построить модель снизу вверх (продукты/клиенты, средний чек, рост числа клиентов и чека) или сверху вниз (размер рынка × доля компании). Модель снизу вверх популярнее и убедительнее, потому что оценить весь рынок почти невозможно. Пояснение Для кейса по МД Медикал это выглядит так: снизу вверх — количество госпитализаций/приёмов × средний чек по клиникам; сверху вниз — рынок частной медицины × доля компании. Лучше всего показать оба подхода и сверить результаты."], "frontHtml": "<div><div>Advanced Concepts · Продвинутые понятия</div>\n<div>Walk me through how you project revenue for a company.</div>\n<div>Как спрогнозировать выручку компании?</div></div>", "backHtml": "<div>\n\n<div><div>Answer (EN)</div>Simplest: assume a percentage growth rate that usually declines over time (e.g. 15%, 12%, 10%). More precise: a bottoms-up build (individual products/customers, average sale value, growth in customers and values) or a tops-down build (market size × market share). Bottoms-up is more common and credible because big-picture numbers are hard to estimate.</div>\n<div><div>Ответ (RU)</div>Проще всего — задать темп роста, который обычно снижается со временем (15%, 12%, 10%). Точнее — построить модель снизу вверх (продукты/клиенты, средний чек, рост числа клиентов и чека) или сверху вниз (размер рынка × доля компании). Модель снизу вверх популярнее и убедительнее, потому что оценить весь рынок почти невозможно.</div>\n<div><div>Пояснение</div>Для кейса по МД Медикал это выглядит так: снизу вверх — количество госпитализаций/приёмов × средний чек по клиникам; сверху вниз — рынок частной медицины × доля компании. Лучше всего показать оба подхода и сверить результаты.</div>\n</div>"}, {"id": 1790385598397, "topic": "620f982081e3e73e", "sec": "IB Accounting (BIWS) EN-RU::5. Advanced Concepts — Продвинутые понятия", "q": "Advanced Concepts · Продвинутые понятия Walk me through how you project expenses for a company. Как спрогнозировать расходы компании?", "a": ["Answer (EN) Simplest: make each IS expense a % of revenue and hold it roughly constant, maybe decreasing slightly (economies of scale). More complex: build by department — headcount, average salary, bonuses, benefits — with headcount tied to revenue. COGS should be tied directly to revenue (per unit sold). Rent and CapEx link to internal expansion plans or to revenue in a simpler model. Ответ (RU) Проще всего — каждый расход как % от выручки, примерно постоянный или слегка снижающийся (эффект масштаба). Сложнее — по подразделениям: численность, средняя зарплата, бонусы, соцпакет, при этом численность привязана к выручке. Себестоимость привязывают напрямую к выручке (на единицу продаж). Аренду и капвложения — к планам расширения или к выручке в простой модели. Пояснение Главная идея: у каждой статьи должен быть понятный «драйвер» — показатель, от которого она зависит. Себестоимость зависит от объёма продаж, зарплата — от численности, аренда — от площадей."], "frontHtml": "<div><div>Advanced Concepts · Продвинутые понятия</div>\n<div>Walk me through how you project expenses for a company.</div>\n<div>Как спрогнозировать расходы компании?</div></div>", "backHtml": "<div>\n\n<div><div>Answer (EN)</div>Simplest: make each IS expense a % of revenue and hold it roughly constant, maybe decreasing slightly (economies of scale). More complex: build by department — headcount, average salary, bonuses, benefits — with headcount tied to revenue. COGS should be tied directly to revenue (per unit sold). Rent and CapEx link to internal expansion plans or to revenue in a simpler model.</div>\n<div><div>Ответ (RU)</div>Проще всего — каждый расход как % от выручки, примерно постоянный или слегка снижающийся (эффект масштаба). Сложнее — по подразделениям: численность, средняя зарплата, бонусы, соцпакет, при этом численность привязана к выручке. Себестоимость привязывают напрямую к выручке (на единицу продаж). Аренду и капвложения — к планам расширения или к выручке в простой модели.</div>\n<div><div>Пояснение</div>Главная идея: у каждой статьи должен быть понятный «драйвер» — показатель, от которого она зависит. Себестоимость зависит от объёма продаж, зарплата — от численности, аренда — от площадей.</div>\n</div>"}, {"id": 1790385598399, "topic": "620f982081e3e73e", "sec": "IB Accounting (BIWS) EN-RU::5. Advanced Concepts — Продвинутые понятия", "q": "Advanced Concepts · Продвинутые понятия How do you project Balance Sheet items like Accounts Receivable and Accrued Expenses in a 3-statement model? Как прогнозировать статьи баланса (дебиторку, начисленные обязательства) в модели?", "a": ["Answer (EN) As percentages of IS items they're linked to: AR — % of Revenue; Prepaid Expenses — % of OpEx; Inventory — % of COGS; Deferred Revenue — % of Revenue; AP — % of OpEx; Accrued Expenses — % of OpEx. Or use 'days', e.g. AR Days = AR / Revenue × 365, hold days roughly constant and back into AR. Ответ (RU) Как процент от связанной статьи ОПУ: дебиторка — % от выручки; РБП — % от операционных расходов; запасы — % от себестоимости; Deferred Revenue — % от выручки; кредиторка и начисленные обязательства — % от операционных расходов. Или через «дни»: AR Days = дебиторка / выручка × 365; держим дни примерно постоянными и вычисляем дебиторку. Пояснение Логика: дебиторка возникает из выручки, запасы — из себестоимости, поэтому они растут вместе с ними. Показатели оборачиваемости в днях — те же, что в финансовом анализе (DSO, DIO, DPO)."], "frontHtml": "<div><div>Advanced Concepts · Продвинутые понятия</div>\n<div>How do you project Balance Sheet items like Accounts Receivable and Accrued Expenses in a 3-statement model?</div>\n<div>Как прогнозировать статьи баланса (дебиторку, начисленные обязательства) в модели?</div></div>", "backHtml": "<div>\n\n<div><div>Answer (EN)</div>As percentages of IS items they&#x27;re linked to: AR — % of Revenue; Prepaid Expenses — % of OpEx; Inventory — % of COGS; Deferred Revenue — % of Revenue; AP — % of OpEx; Accrued Expenses — % of OpEx. Or use &#x27;days&#x27;, e.g. AR Days = AR / Revenue × 365, hold days roughly constant and back into AR.</div>\n<div><div>Ответ (RU)</div>Как процент от связанной статьи ОПУ: дебиторка — % от выручки; РБП — % от операционных расходов; запасы — % от себестоимости; Deferred Revenue — % от выручки; кредиторка и начисленные обязательства — % от операционных расходов. Или через «дни»: AR Days = дебиторка / выручка × 365; держим дни примерно постоянными и вычисляем дебиторку.</div>\n<div><div>Пояснение</div>Логика: дебиторка возникает из выручки, запасы — из себестоимости, поэтому они растут вместе с ними. Показатели оборачиваемости в днях — те же, что в финансовом анализе (DSO, DIO, DPO).</div>\n</div>"}, {"id": 1790385598401, "topic": "620f982081e3e73e", "sec": "IB Accounting (BIWS) EN-RU::5. Advanced Concepts — Продвинутые понятия", "q": "Advanced Concepts · Продвинутые понятия How should you project Depreciation and Capital Expenditures? Как прогнозировать амортизацию и капвложения?", "a": ["Answer (EN) Simplest: each as a % of revenue. Alternative: Depreciation as % of revenue, CapEx as an average of past years or a fixed dollar/percentage change. Complex: a PP&E schedule — CapEx from management plans, depreciate existing PP&E by useful life (straight-line), and depreciate new CapEx right after it's added. Ответ (RU) Проще всего — оба как % от выручки. Вариант: амортизация как % от выручки, а капвложения — среднее за прошлые годы или фиксированный рост. Сложно: график ОС — капвложения по планам менеджмента, существующие ОС амортизируются линейно по сроку службы, новые — сразу после ввода. Пояснение PP&E schedule в модели выглядит так: ОС на начало + капвложения − амортизация − выбытие = ОС на конец. Это та же логика, что «уравнение запасов» у Молчанова: было + пришло − ушло = осталось."], "frontHtml": "<div><div>Advanced Concepts · Продвинутые понятия</div>\n<div>How should you project Depreciation and Capital Expenditures?</div>\n<div>Как прогнозировать амортизацию и капвложения?</div></div>", "backHtml": "<div>\n\n<div><div>Answer (EN)</div>Simplest: each as a % of revenue. Alternative: Depreciation as % of revenue, CapEx as an average of past years or a fixed dollar/percentage change. Complex: a PP&amp;E schedule — CapEx from management plans, depreciate existing PP&amp;E by useful life (straight-line), and depreciate new CapEx right after it&#x27;s added.</div>\n<div><div>Ответ (RU)</div>Проще всего — оба как % от выручки. Вариант: амортизация как % от выручки, а капвложения — среднее за прошлые годы или фиксированный рост. Сложно: график ОС — капвложения по планам менеджмента, существующие ОС амортизируются линейно по сроку службы, новые — сразу после ввода.</div>\n<div><div>Пояснение</div>PP&amp;E schedule в модели выглядит так: ОС на начало + капвложения − амортизация − выбытие = ОС на конец. Это та же логика, что «уравнение запасов» у Молчанова: было + пришло − ушло = осталось.</div>\n</div>"}, {"id": 1790385598403, "topic": "620f982081e3e73e", "sec": "IB Accounting (BIWS) EN-RU::5. Advanced Concepts — Продвинутые понятия", "q": "Advanced Concepts · Продвинутые понятия There's usually a 'simple' and 'complex' way of projecting financials. Does the complex method give better numbers? Даёт ли сложный метод прогнозирования более точные цифры?", "a": ["Answer (EN) In short, no. Complex methods usually give similar numbers; you use them to get better SUPPORT for the numbers. 'Revenue grows 10%' has little evidence; a segment build lets you say the 10% comes from a 5% price increase here, 10% more units there, 15% growth in a geography. Ответ (RU) Если коротко — нет. Сложные методы обычно дают похожие цифры; их используют, чтобы лучше ОБОСНОВАТЬ цифры. «Выручка растёт на 10%» — ничем не подкреплено; модель по сегментам позволяет сказать, что 10% складываются из роста цен на 5% в одном сегменте, объёмов на 10% в другом и т. д. Пояснение Хороший зрелый ответ: модель — это инструмент аргументации, а не предсказания. Инвестор или клиент доверяет цифрам, когда понимает драйверы, стоящие за ними."], "frontHtml": "<div><div>Advanced Concepts · Продвинутые понятия</div>\n<div>There&#x27;s usually a &#x27;simple&#x27; and &#x27;complex&#x27; way of projecting financials. Does the complex method give better numbers?</div>\n<div>Даёт ли сложный метод прогнозирования более точные цифры?</div></div>", "backHtml": "<div>\n\n<div><div>Answer (EN)</div>In short, no. Complex methods usually give similar numbers; you use them to get better SUPPORT for the numbers. &#x27;Revenue grows 10%&#x27; has little evidence; a segment build lets you say the 10% comes from a 5% price increase here, 10% more units there, 15% growth in a geography.</div>\n<div><div>Ответ (RU)</div>Если коротко — нет. Сложные методы обычно дают похожие цифры; их используют, чтобы лучше ОБОСНОВАТЬ цифры. «Выручка растёт на 10%» — ничем не подкреплено; модель по сегментам позволяет сказать, что 10% складываются из роста цен на 5% в одном сегменте, объёмов на 10% в другом и т. д.</div>\n<div><div>Пояснение</div>Хороший зрелый ответ: модель — это инструмент аргументации, а не предсказания. Инвестор или клиент доверяет цифрам, когда понимает драйверы, стоящие за ними.</div>\n</div>"}, {"id": 1790385598405, "topic": "620f982081e3e73e", "sec": "IB Accounting (BIWS) EN-RU::5. Advanced Concepts — Продвинутые понятия", "q": "Advanced Concepts · Продвинутые понятия What are examples of non-recurring charges you add back to EBIT / EBITDA? Какие разовые расходы прибавляют при расчёте EBIT / EBITDA?", "a": ["Answer (EN) Restructuring charges, Goodwill Impairment, Asset Write-Downs, Bad Debt Expenses, one-time legal expenses, disaster expenses, changes in accounting policies. They must affect Operating Income to be added back — if 'below the line', you don't add them back. D&A (and sometimes SBC) are added back for EBITDA, but they are non-cash, not non-recurring. Ответ (RU) Расходы на реструктуризацию, обесценение гудвила, списания активов, резервы по безнадёжным долгам, разовые судебные расходы, ущерб от стихийных бедствий, изменения учётной политики. Прибавлять можно, только если они вошли в операционную прибыль — если они ниже операционной прибыли, их не прибавляют. Амортизацию (и иногда SBC) прибавляют для EBITDA, но они неденежные, а не разовые. Пояснение Цель — получить «нормализованную» прибыль, отражающую регулярный бизнес, чтобы корректно считать мультипликаторы (EV/EBITDA) и сравнивать компании."], "frontHtml": "<div><div>Advanced Concepts · Продвинутые понятия</div>\n<div>What are examples of non-recurring charges you add back to EBIT / EBITDA?</div>\n<div>Какие разовые расходы прибавляют при расчёте EBIT / EBITDA?</div></div>", "backHtml": "<div>\n\n<div><div>Answer (EN)</div>Restructuring charges, Goodwill Impairment, Asset Write-Downs, Bad Debt Expenses, one-time legal expenses, disaster expenses, changes in accounting policies. They must affect Operating Income to be added back — if &#x27;below the line&#x27;, you don&#x27;t add them back. D&amp;A (and sometimes SBC) are added back for EBITDA, but they are non-cash, not non-recurring.</div>\n<div><div>Ответ (RU)</div>Расходы на реструктуризацию, обесценение гудвила, списания активов, резервы по безнадёжным долгам, разовые судебные расходы, ущерб от стихийных бедствий, изменения учётной политики. Прибавлять можно, только если они вошли в операционную прибыль — если они ниже операционной прибыли, их не прибавляют. Амортизацию (и иногда SBC) прибавляют для EBITDA, но они неденежные, а не разовые.</div>\n<div><div>Пояснение</div>Цель — получить «нормализованную» прибыль, отражающую регулярный бизнес, чтобы корректно считать мультипликаторы (EV/EBITDA) и сравнивать компании.</div>\n</div>"}, {"id": 1790385598407, "topic": "620f982081e3e73e", "sec": "IB Accounting (BIWS) EN-RU::5. Advanced Concepts — Продвинутые понятия", "q": "Advanced Concepts · Продвинутые понятия What's the difference between capital leases and operating leases? How do they affect the statements? Чем финансовая аренда отличается от операционной?", "a": ["Answer (EN) Operating leases: short-term leasing, no ownership; lease expense is an Operating Expense on the IS. Capital leases: longer-term with ownership rights; they Depreciate, incur Interest Expense and count as Debt. A lease is capital if any of 4 tests is met: ownership transfers at end; bargain purchase option; term > 75% of useful life; PV of payments > 90% of fair value. Ответ (RU) Операционная аренда — краткосрочная, без права собственности; арендный платёж — операционный расход в ОПУ. Финансовая (капитальная) аренда — долгосрочная, с правами собственника: актив амортизируется, начисляются проценты, обязательство считается долгом. Аренда финансовая, если выполнено хотя бы одно из 4 условий: право собственности переходит в конце; опцион выкупа по льготной цене; срок > 75% срока службы; приведённая стоимость платежей > 90% справедливой стоимости. Пояснение Важно: это правила до 2019 года. Сейчас по МСФО 16 (и по ФСБУ 25 в России) почти вся аренда у арендатора отражается на балансе: актив «право пользования» амортизируется, а обязательство по аренде начисляет проценты. Это увеличило EBITDA многих компаний (арендные платежи ушли из операционных расходов)."], "frontHtml": "<div><div>Advanced Concepts · Продвинутые понятия</div>\n<div>What&#x27;s the difference between capital leases and operating leases? How do they affect the statements?</div>\n<div>Чем финансовая аренда отличается от операционной?</div></div>", "backHtml": "<div>\n\n<div><div>Answer (EN)</div>Operating leases: short-term leasing, no ownership; lease expense is an Operating Expense on the IS. Capital leases: longer-term with ownership rights; they Depreciate, incur Interest Expense and count as Debt. A lease is capital if any of 4 tests is met: ownership transfers at end; bargain purchase option; term &gt; 75% of useful life; PV of payments &gt; 90% of fair value.</div>\n<div><div>Ответ (RU)</div>Операционная аренда — краткосрочная, без права собственности; арендный платёж — операционный расход в ОПУ. Финансовая (капитальная) аренда — долгосрочная, с правами собственника: актив амортизируется, начисляются проценты, обязательство считается долгом. Аренда финансовая, если выполнено хотя бы одно из 4 условий: право собственности переходит в конце; опцион выкупа по льготной цене; срок &gt; 75% срока службы; приведённая стоимость платежей &gt; 90% справедливой стоимости.</div>\n<div><div>Пояснение</div>Важно: это правила до 2019 года. Сейчас по МСФО 16 (и по ФСБУ 25 в России) почти вся аренда у арендатора отражается на балансе: актив «право пользования» амортизируется, а обязательство по аренде начисляет проценты. Это увеличило EBITDA многих компаний (арендные платежи ушли из операционных расходов).</div>\n</div>"}, {"id": 1790385598409, "topic": "620f982081e3e73e", "sec": "IB Accounting (BIWS) EN-RU::5. Advanced Concepts — Продвинутые понятия", "q": "Advanced Concepts · Продвинутые понятия How do Net Operating Losses (NOLs) affect a company's 3 statements? Как налоговые убытки прошлых лет (NOL) влияют на отчёты?", "a": ["Answer (EN) Quick way: reduce Taxable Income by the NOLs usable each year, apply the tax rate, use the lower tax against the unchanged Pre-Tax Income, and reduce the NOL balance (part of the DTA). Complex way: a book vs cash tax schedule — compute taxes with and without NOLs, and record the difference as an increase in the Deferred Tax Liability, reflecting cash savings. Ответ (RU) Быстрый способ: уменьшить налогооблагаемую прибыль на доступную часть убытков, применить ставку, вычесть меньший налог из прежней прибыли до налога и уменьшить остаток NOL (часть ОНА). Сложный способ: отдельный график бухгалтерского и денежного налога — посчитать налог с учётом NOL и без, разницу отразить как рост ОНО, что показывает экономию денег. Пояснение Суть: NOL — это «налоговый щит» из прошлых убытков. В M&A NOL покупаемой компании могут иметь реальную ценность для покупателя, но их использование часто ограничивается законом после смены собственника."], "frontHtml": "<div><div>Advanced Concepts · Продвинутые понятия</div>\n<div>How do Net Operating Losses (NOLs) affect a company&#x27;s 3 statements?</div>\n<div>Как налоговые убытки прошлых лет (NOL) влияют на отчёты?</div></div>", "backHtml": "<div>\n\n<div><div>Answer (EN)</div>Quick way: reduce Taxable Income by the NOLs usable each year, apply the tax rate, use the lower tax against the unchanged Pre-Tax Income, and reduce the NOL balance (part of the DTA). Complex way: a book vs cash tax schedule — compute taxes with and without NOLs, and record the difference as an increase in the Deferred Tax Liability, reflecting cash savings.</div>\n<div><div>Ответ (RU)</div>Быстрый способ: уменьшить налогооблагаемую прибыль на доступную часть убытков, применить ставку, вычесть меньший налог из прежней прибыли до налога и уменьшить остаток NOL (часть ОНА). Сложный способ: отдельный график бухгалтерского и денежного налога — посчитать налог с учётом NOL и без, разницу отразить как рост ОНО, что показывает экономию денег.</div>\n<div><div>Пояснение</div>Суть: NOL — это «налоговый щит» из прошлых убытков. В M&amp;A NOL покупаемой компании могут иметь реальную ценность для покупателя, но их использование часто ограничивается законом после смены собственника.</div>\n</div>"}, {"id": 1790385598411, "topic": "620f982081e3e73e", "sec": "IB Accounting (BIWS) EN-RU::5. Advanced Concepts — Продвинутые понятия", "q": "Advanced Concepts · Продвинутые понятия What's the difference between Tax Benefits from SBC and Excess Tax Benefits from SBC? How do they impact the statements? Чем Tax Benefits от SBC отличаются от Excess Tax Benefits?", "a": ["Answer (EN) Tax Benefits = total taxes saved from issuing SBC (e.g. $100 SBC × 40% = $40). Excess Tax Benefits = the part of those savings due to share price increases after the SBC was announced. Neither is a separate IS item. On the CFS, Tax Benefits are added back in CFO (so they accrue to APIC); Excess Tax Benefits are subtracted from CFO and added to CFF (re-classified as financing). Ответ (RU) Tax Benefits — вся налоговая экономия от SBC (например, $100 SBC × 40% = $40). Excess Tax Benefits — часть этой экономии из-за роста цены акций после объявления SBC. Отдельной строкой в ОПУ ни то ни другое не идёт. В ОДДС Tax Benefits прибавляются в операционном потоке (и попадают в APIC); Excess Tax Benefits вычитаются из операционного и прибавляются в финансовом потоке. Пояснение Очень американская тема, на собеседованиях начального уровня почти не встречается. К тому же правила изменились в 2016 году (ASU 2016-09): теперь excess tax benefits проходят через ОПУ и относятся к операционному потоку. Достаточно понимать общую идею."], "frontHtml": "<div><div>Advanced Concepts · Продвинутые понятия</div>\n<div>What&#x27;s the difference between Tax Benefits from SBC and Excess Tax Benefits from SBC? How do they impact the statements?</div>\n<div>Чем Tax Benefits от SBC отличаются от Excess Tax Benefits?</div></div>", "backHtml": "<div>\n\n<div><div>Answer (EN)</div>Tax Benefits = total taxes saved from issuing SBC (e.g. $100 SBC × 40% = $40). Excess Tax Benefits = the part of those savings due to share price increases after the SBC was announced. Neither is a separate IS item. On the CFS, Tax Benefits are added back in CFO (so they accrue to APIC); Excess Tax Benefits are subtracted from CFO and added to CFF (re-classified as financing).</div>\n<div><div>Ответ (RU)</div>Tax Benefits — вся налоговая экономия от SBC (например, $100 SBC × 40% = $40). Excess Tax Benefits — часть этой экономии из-за роста цены акций после объявления SBC. Отдельной строкой в ОПУ ни то ни другое не идёт. В ОДДС Tax Benefits прибавляются в операционном потоке (и попадают в APIC); Excess Tax Benefits вычитаются из операционного и прибавляются в финансовом потоке.</div>\n<div><div>Пояснение</div>Очень американская тема, на собеседованиях начального уровня почти не встречается. К тому же правила изменились в 2016 году (ASU 2016-09): теперь excess tax benefits проходят через ОПУ и относятся к операционному потоку. Достаточно понимать общую идею.</div>\n</div>"}, {"id": 1790385598413, "topic": "620f982081e3e73e", "sec": "IB Accounting (BIWS) EN-RU::5. Advanced Concepts — Продвинутые понятия", "q": "Advanced Concepts · Продвинутые понятия You're creating quarterly projections. What's the best way to project revenue growth each quarter? Как прогнозировать рост выручки поквартально?", "a": ["Answer (EN) Split historical data by quarter and use Year-over-Year growth for each quarter (Q1 vs prior Q1s), not Quarter-over-Quarter, because many businesses are seasonal. Same for expenses. Ответ (RU) Разбить историю по кварталам и использовать рост год к году для каждого квартала (Q1 к прошлым Q1), а не квартал к кварталу, потому что многие бизнесы сезонны. То же для расходов. Пояснение Пример: у ритейла 4-й квартал (новогодние продажи) всегда сильнее 1-го. Сравнение Q1 с Q4 покажет «падение», которого на самом деле нет."], "frontHtml": "<div><div>Advanced Concepts · Продвинутые понятия</div>\n<div>You&#x27;re creating quarterly projections. What&#x27;s the best way to project revenue growth each quarter?</div>\n<div>Как прогнозировать рост выручки поквартально?</div></div>", "backHtml": "<div>\n\n<div><div>Answer (EN)</div>Split historical data by quarter and use Year-over-Year growth for each quarter (Q1 vs prior Q1s), not Quarter-over-Quarter, because many businesses are seasonal. Same for expenses.</div>\n<div><div>Ответ (RU)</div>Разбить историю по кварталам и использовать рост год к году для каждого квартала (Q1 к прошлым Q1), а не квартал к кварталу, потому что многие бизнесы сезонны. То же для расходов.</div>\n<div><div>Пояснение</div>Пример: у ритейла 4-й квартал (новогодние продажи) всегда сильнее 1-го. Сравнение Q1 с Q4 покажет «падение», которого на самом деле нет.</div>\n</div>"}, {"id": 1790385598415, "topic": "620f982081e3e73e", "sec": "IB Accounting (BIWS) EN-RU::5. Advanced Concepts — Продвинутые понятия", "q": "Advanced Concepts · Продвинутые понятия What's the purpose of calendarizing financial figures? Зачем «календаризировать» финансовые показатели?", "a": ["Answer (EN) To use the same 12-month period for all companies instead of their different fiscal years. It's used mostly with public comps: if one company's year ends Dec 31, another's Jun 30 and another's Sep 30, you must align them to compare apples to apples. Ответ (RU) Чтобы привести все компании к одному 12-месячному периоду вместо их разных финансовых лет. Чаще всего это нужно в анализе компаний-аналогов: если у одной год заканчивается 31 декабря, у другой 30 июня, у третьей 30 сентября, их нужно выровнять, иначе сравнение некорректно. Пояснение Comps (comparable companies) — оценка через мультипликаторы компаний-аналогов. Если EBITDA одних компаний за год до декабря, а других — до июня, мультипликаторы несопоставимы. Типичный инструмент — LTM/TTM (последние 12 месяцев)."], "frontHtml": "<div><div>Advanced Concepts · Продвинутые понятия</div>\n<div>What&#x27;s the purpose of calendarizing financial figures?</div>\n<div>Зачем «календаризировать» финансовые показатели?</div></div>", "backHtml": "<div>\n\n<div><div>Answer (EN)</div>To use the same 12-month period for all companies instead of their different fiscal years. It&#x27;s used mostly with public comps: if one company&#x27;s year ends Dec 31, another&#x27;s Jun 30 and another&#x27;s Sep 30, you must align them to compare apples to apples.</div>\n<div><div>Ответ (RU)</div>Чтобы привести все компании к одному 12-месячному периоду вместо их разных финансовых лет. Чаще всего это нужно в анализе компаний-аналогов: если у одной год заканчивается 31 декабря, у другой 30 июня, у третьей 30 сентября, их нужно выровнять, иначе сравнение некорректно.</div>\n<div><div>Пояснение</div>Comps (comparable companies) — оценка через мультипликаторы компаний-аналогов. Если EBITDA одних компаний за год до декабря, а других — до июня, мультипликаторы несопоставимы. Типичный инструмент — LTM/TTM (последние 12 месяцев).</div>\n</div>"}, {"id": 1790385598417, "topic": "620f982081e3e73e", "sec": "IB Accounting (BIWS) EN-RU::5. Advanced Concepts — Продвинутые понятия", "q": "Advanced Concepts · Продвинутые понятия What happens to the DTA/DTL if we record accelerated Depreciation for tax purposes but straight-line for book purposes? Что происходит с ОНО, если в налоговом учёте амортизация ускоренная, а в бухгалтерском — линейная?", "a": ["Answer (EN) In early years tax Depreciation is higher, so cash taxes are lower and the DTL increases (you'll need to make up for it). In later years tax Depreciation is lower, you pay more cash taxes and the DTL decreases. Ответ (RU) В первые годы налоговая амортизация больше, денежный налог меньше, и ОНО растёт (потом придётся доплатить). В последующие годы налоговая амортизация меньше, налог платится больше, и ОНО уменьшается. Пояснение Итог за весь срок одинаковый: общая амортизация и общий налог совпадают. Меняется только распределение по времени. Компания выигрывает за счёт временной стоимости денег: заплатить налог позже выгоднее."], "frontHtml": "<div><div>Advanced Concepts · Продвинутые понятия</div>\n<div>What happens to the DTA/DTL if we record accelerated Depreciation for tax purposes but straight-line for book purposes?</div>\n<div>Что происходит с ОНО, если в налоговом учёте амортизация ускоренная, а в бухгалтерском — линейная?</div></div>", "backHtml": "<div>\n\n<div><div>Answer (EN)</div>In early years tax Depreciation is higher, so cash taxes are lower and the DTL increases (you&#x27;ll need to make up for it). In later years tax Depreciation is lower, you pay more cash taxes and the DTL decreases.</div>\n<div><div>Ответ (RU)</div>В первые годы налоговая амортизация больше, денежный налог меньше, и ОНО растёт (потом придётся доплатить). В последующие годы налоговая амортизация меньше, налог платится больше, и ОНО уменьшается.</div>\n<div><div>Пояснение</div>Итог за весь срок одинаковый: общая амортизация и общий налог совпадают. Меняется только распределение по времени. Компания выигрывает за счёт временной стоимости денег: заплатить налог позже выгоднее.</div>\n</div>"}, {"id": 1790385598419, "topic": "620f982081e3e73e", "sec": "IB Accounting (BIWS) EN-RU::5. Advanced Concepts — Продвинутые понятия", "q": "Advanced Concepts · Продвинутые понятия If you own over 50% but less than 100% of another company, what happens on the statements when you record the acquisition? Вы купили 50–100% другой компании. Как это отражается в отчётах?", "a": ["Answer (EN) You consolidate 100% of the other company's statements, like a full acquisition, but also create a Noncontrolling Interest on the L&E side for the part you don't own (e.g. $30 if worth $100 and you own 70%). You wipe out its Shareholders' Equity and allocate the purchase price. On the IS you subtract Net Income Attributable to NCI, then add it back on the CFS; NCI on the BS grows by that amount each year while Retained Earnings falls by it. Ответ (RU) Вы консолидируете 100% отчётности дочки, как при полной покупке, но создаёте в пассиве неконтролирующую долю на часть, которой не владеете (например, $30 при стоимости $100 и доле 70%). Капитал дочки исключается, цена покупки распределяется. В ОПУ вычитается прибыль, приходящаяся на NCI, в ОДДС она прибавляется обратно; NCI в балансе ежегодно растёт на эту сумму, а нераспределённая прибыль на неё уменьшается. Пояснение Логика: деньги дочки при контроле фактически доступны группе, поэтому в ОДДС прибыль NCI прибавляется обратно — на деньги она не влияет. Это просто разделение прибыли между «нами» и миноритариями."], "frontHtml": "<div><div>Advanced Concepts · Продвинутые понятия</div>\n<div>If you own over 50% but less than 100% of another company, what happens on the statements when you record the acquisition?</div>\n<div>Вы купили 50–100% другой компании. Как это отражается в отчётах?</div></div>", "backHtml": "<div>\n\n<div><div>Answer (EN)</div>You consolidate 100% of the other company&#x27;s statements, like a full acquisition, but also create a Noncontrolling Interest on the L&amp;E side for the part you don&#x27;t own (e.g. $30 if worth $100 and you own 70%). You wipe out its Shareholders&#x27; Equity and allocate the purchase price. On the IS you subtract Net Income Attributable to NCI, then add it back on the CFS; NCI on the BS grows by that amount each year while Retained Earnings falls by it.</div>\n<div><div>Ответ (RU)</div>Вы консолидируете 100% отчётности дочки, как при полной покупке, но создаёте в пассиве неконтролирующую долю на часть, которой не владеете (например, $30 при стоимости $100 и доле 70%). Капитал дочки исключается, цена покупки распределяется. В ОПУ вычитается прибыль, приходящаяся на NCI, в ОДДС она прибавляется обратно; NCI в балансе ежегодно растёт на эту сумму, а нераспределённая прибыль на неё уменьшается.</div>\n<div><div>Пояснение</div>Логика: деньги дочки при контроле фактически доступны группе, поэтому в ОДДС прибыль NCI прибавляется обратно — на деньги она не влияет. Это просто разделение прибыли между «нами» и миноритариями.</div>\n</div>"}, {"id": 1790385598421, "topic": "620f982081e3e73e", "sec": "IB Accounting (BIWS) EN-RU::5. Advanced Concepts — Продвинутые понятия", "q": "Advanced Concepts · Продвинутые понятия What if you own between 20% and 50% of another company? How do you record it and how are the statements affected? Вы владеете 20–50% другой компании. Как это учитывается?", "a": ["Answer (EN) Equity Interest (Associate): no consolidation. Record % owned × value as an Asset (Investments in Equity Interests), e.g. 30% of $200 = $60. Add % × the other company's Net Income to your Net Income, then subtract it on the CFS since it's non-cash. The investment grows by that amount each year and falls by dividends received; Retained Earnings changes with Net Income. Ответ (RU) Ассоциированная компания: без консолидации. В активе отражается доля × стоимость (Investments in Equity Interests), например 30% от $200 = $60. К своей чистой прибыли прибавляют долю от прибыли той компании, а в ОДДС её вычитают, потому что денег нет. Инвестиция растёт на эту сумму каждый год и уменьшается на полученные дивиденды; нераспределённая прибыль меняется вместе с чистой прибылью. Пояснение Это метод долевого участия (equity method). Инвестиция работает как «мини-капитал»: + наша доля прибыли − наша доля дивидендов. Контроля нет, поэтому прибыль ассоциированной компании — не наши деньги, пока не пришли дивиденды."], "frontHtml": "<div><div>Advanced Concepts · Продвинутые понятия</div>\n<div>What if you own between 20% and 50% of another company? How do you record it and how are the statements affected?</div>\n<div>Вы владеете 20–50% другой компании. Как это учитывается?</div></div>", "backHtml": "<div>\n\n<div><div>Answer (EN)</div>Equity Interest (Associate): no consolidation. Record % owned × value as an Asset (Investments in Equity Interests), e.g. 30% of $200 = $60. Add % × the other company&#x27;s Net Income to your Net Income, then subtract it on the CFS since it&#x27;s non-cash. The investment grows by that amount each year and falls by dividends received; Retained Earnings changes with Net Income.</div>\n<div><div>Ответ (RU)</div>Ассоциированная компания: без консолидации. В активе отражается доля × стоимость (Investments in Equity Interests), например 30% от $200 = $60. К своей чистой прибыли прибавляют долю от прибыли той компании, а в ОДДС её вычитают, потому что денег нет. Инвестиция растёт на эту сумму каждый год и уменьшается на полученные дивиденды; нераспределённая прибыль меняется вместе с чистой прибылью.</div>\n<div><div>Пояснение</div>Это метод долевого участия (equity method). Инвестиция работает как «мини-капитал»: + наша доля прибыли − наша доля дивидендов. Контроля нет, поэтому прибыль ассоциированной компании — не наши деньги, пока не пришли дивиденды.</div>\n</div>"}, {"id": 1790385598423, "topic": "620f982081e3e73e", "sec": "IB Accounting (BIWS) EN-RU::5. Advanced Concepts — Продвинутые понятия", "q": "Advanced Concepts · Продвинутые понятия What if you own less than 20% of another company? Что если доля меньше 20%?", "a": ["Answer (EN) Treatment is inconsistent. Some companies still use the Equity Interest method, especially if they exert 'significant influence'. Others classify it as a simple Investment/Security, as if they bought a stock or bond, and ignore the other company's financials. Ответ (RU) Учёт неоднороден. Некоторые компании всё равно применяют метод долевого участия, особенно если имеют «существенное влияние». Другие отражают долю как обычную финансовую инвестицию — будто купили акцию или облигацию — и не учитывают отчётность той компании. Пояснение Пороги 20% и 50% — ориентиры, а не жёсткие правила. Решает наличие контроля (консолидация) или существенного влияния (метод долевого участия): например, место в совете директоров при доле 15%."], "frontHtml": "<div><div>Advanced Concepts · Продвинутые понятия</div>\n<div>What if you own less than 20% of another company?</div>\n<div>Что если доля меньше 20%?</div></div>", "backHtml": "<div>\n\n<div><div>Answer (EN)</div>Treatment is inconsistent. Some companies still use the Equity Interest method, especially if they exert &#x27;significant influence&#x27;. Others classify it as a simple Investment/Security, as if they bought a stock or bond, and ignore the other company&#x27;s financials.</div>\n<div><div>Ответ (RU)</div>Учёт неоднороден. Некоторые компании всё равно применяют метод долевого участия, особенно если имеют «существенное влияние». Другие отражают долю как обычную финансовую инвестицию — будто купили акцию или облигацию — и не учитывают отчётность той компании.</div>\n<div><div>Пояснение</div>Пороги 20% и 50% — ориентиры, а не жёсткие правила. Решает наличие контроля (консолидация) или существенного влияния (метод долевого участия): например, место в совете директоров при доле 15%.</div>\n</div>"}, {"id": 1790385598425, "topic": "620f982081e3e73e", "sec": "IB Accounting (BIWS) EN-RU::5. Advanced Concepts — Продвинутые понятия", "q": "Advanced Concepts · Продвинутые понятия What are the different classifications for Securities on the Balance Sheet? How do they differ? Как классифицируются ценные бумаги на балансе?", "a": ["Answer (EN) Trading: very short-term; all Gains/Losses go on the IS, even unrealized. Available-for-Sale (AFS): longer-term; unrealized Gains/Losses go to AOCI, not the IS; BS value is marked to market. Held-to-Maturity (HTM): even longer-term; unrealized Gains/Losses aren't reported anywhere, only realized ones on sale. Ответ (RU) Trading (торговые): очень краткосрочные; все прибыли/убытки — в ОПУ, даже нереализованные. Available-for-Sale (для продажи): более долгосрочные; нереализованные прибыли/убытки — в прочий совокупный доход (AOCI), не в ОПУ; стоимость на балансе переоценивается по рынку. Held-to-Maturity (до погашения): ещё более долгосрочные; нереализованные прибыли/убытки нигде не отражаются, только реализованные при продаже. Пояснение Это старая классификация US GAAP. По МСФО 9 сейчас другие категории: по справедливой стоимости через прибыль или убыток (FVTPL ≈ Trading), через прочий совокупный доход (FVOCI ≈ AFS) и по амортизированной стоимости (≈ HTM). Логика та же."], "frontHtml": "<div><div>Advanced Concepts · Продвинутые понятия</div>\n<div>What are the different classifications for Securities on the Balance Sheet? How do they differ?</div>\n<div>Как классифицируются ценные бумаги на балансе?</div></div>", "backHtml": "<div>\n\n<div><div>Answer (EN)</div>Trading: very short-term; all Gains/Losses go on the IS, even unrealized. Available-for-Sale (AFS): longer-term; unrealized Gains/Losses go to AOCI, not the IS; BS value is marked to market. Held-to-Maturity (HTM): even longer-term; unrealized Gains/Losses aren&#x27;t reported anywhere, only realized ones on sale.</div>\n<div><div>Ответ (RU)</div>Trading (торговые): очень краткосрочные; все прибыли/убытки — в ОПУ, даже нереализованные. Available-for-Sale (для продажи): более долгосрочные; нереализованные прибыли/убытки — в прочий совокупный доход (AOCI), не в ОПУ; стоимость на балансе переоценивается по рынку. Held-to-Maturity (до погашения): ещё более долгосрочные; нереализованные прибыли/убытки нигде не отражаются, только реализованные при продаже.</div>\n<div><div>Пояснение</div>Это старая классификация US GAAP. По МСФО 9 сейчас другие категории: по справедливой стоимости через прибыль или убыток (FVTPL ≈ Trading), через прочий совокупный доход (FVOCI ≈ AFS) и по амортизированной стоимости (≈ HTM). Логика та же.</div>\n</div>"}, {"id": 1790385598427, "topic": "620f982081e3e73e", "sec": "IB Accounting (BIWS) EN-RU::6. Advanced Scenarios — Продвинутые сценарии", "q": "Advanced Scenarios · Продвинутые сценарии You own 70% of a company that earns Net Income of $10; everything above Net Income is consolidated. How do you record Net Income Attributable to NCI? Вам принадлежит 70% компании с чистой прибылью $10. Как отразить прибыль, приходящуюся на неконтролирующую долю?", "a": ["3 statements · в трёх отчётах (tax 40%) IS / ОПУ Прибыль NCI −3 → ЧП материнской −3 CFS / ОДДС ЧП −3; +3 прибыль NCI → деньги 0 BS / Баланс Активы: без изменений. Пассивы: NCI +3, нераспр. прибыль −3 Answer (EN) IS: subtract $3 (30% × $10) as Net Income Attributable to NCI; Net Income Attributable to Parent −$3. CFS: Net Income −$3, but add back $3 because you do receive this cash when you own >50% → cash unchanged. BS: Assets unchanged; NCI +$3, Retained Earnings −$3. Ответ (RU) ОПУ: вычитаем $3 (30% × $10) как прибыль NCI; прибыль, приходящаяся на материнскую компанию, −$3. ОДДС: чистая прибыль −$3, но прибавляем $3 обратно, потому что при контроле эти деньги фактически в группе → деньги без изменений. Баланс: активы не меняются; NCI +$3, нераспределённая прибыль −$3. Пояснение Это не расход и не отток денег — просто перераспределение прибыли внутри капитала между нами и миноритариями."], "frontHtml": "<div><div>Advanced Scenarios · Продвинутые сценарии</div>\n<div>You own 70% of a company that earns Net Income of $10; everything above Net Income is consolidated. How do you record Net Income Attributable to NCI?</div>\n<div>Вам принадлежит 70% компании с чистой прибылью $10. Как отразить прибыль, приходящуюся на неконтролирующую долю?</div></div>", "backHtml": "<div>\n<div><div>3 statements · в трёх отчётах (tax 40%)</div>\n<table><tr><td>IS / ОПУ</td><td>Прибыль NCI −3 → ЧП материнской −3</td></tr>\n<tr><td>CFS / ОДДС</td><td>ЧП −3; +3 прибыль NCI → деньги 0</td></tr>\n<tr><td>BS / Баланс</td><td>Активы: без изменений. Пассивы: NCI +3, нераспр. прибыль −3</td></tr></table></div>\n<div><div>Answer (EN)</div>IS: subtract $3 (30% × $10) as Net Income Attributable to NCI; Net Income Attributable to Parent −$3. CFS: Net Income −$3, but add back $3 because you do receive this cash when you own &gt;50% → cash unchanged. BS: Assets unchanged; NCI +$3, Retained Earnings −$3.</div>\n<div><div>Ответ (RU)</div>ОПУ: вычитаем $3 (30% × $10) как прибыль NCI; прибыль, приходящаяся на материнскую компанию, −$3. ОДДС: чистая прибыль −$3, но прибавляем $3 обратно, потому что при контроле эти деньги фактически в группе → деньги без изменений. Баланс: активы не меняются; NCI +$3, нераспределённая прибыль −$3.</div>\n<div><div>Пояснение</div>Это не расход и не отток денег — просто перераспределение прибыли внутри капитала между нами и миноритариями.</div>\n</div>"}, {"id": 1790385598429, "topic": "620f982081e3e73e", "sec": "IB Accounting (BIWS) EN-RU::6. Advanced Scenarios — Продвинутые сценарии", "q": "Advanced Scenarios · Продвинутые сценарии Same example: the 70%-owned company issues Dividends of $5. How is that recorded? Та же дочка (70%) выплачивает дивиденды $5. Как это отражается?", "a": ["3 statements · в трёх отчётах (tax 40%) IS / ОПУ Без изменений CFS / ОДДС Дивиденды −5 в CFF → деньги −5 BS / Баланс Активы: деньги −5. Пассивы: нераспр. прибыль −5 (по версии гайда) Answer (EN) IS: no changes. CFS: additional Dividend of $5 in CFF → cash −$5. BS: Cash −$5; Retained Earnings −$5. Since statements are consolidated when you own >50%, you don't multiply by ownership — only Net Income is split out. Ответ (RU) ОПУ: без изменений. ОДДС: дивиденд −$5 в финансовом потоке → деньги −$5. Баланс: деньги −$5; нераспределённая прибыль −$5. Так как отчётность консолидирована, на долю владения не умножаем — разделяется только чистая прибыль. Пояснение Оговорка: это упрощённый ответ гайда. В реальной консолидации 70% дивидендов ($3,5) — внутригрупповой платёж, который исключается, а из группы уходят только $1,5 миноритариям, и они уменьшают NCI, а не нераспределённую прибыль. На собеседовании можно дать ответ гайда, но упомянуть это уточнение — это покажет глубину понимания."], "frontHtml": "<div><div>Advanced Scenarios · Продвинутые сценарии</div>\n<div>Same example: the 70%-owned company issues Dividends of $5. How is that recorded?</div>\n<div>Та же дочка (70%) выплачивает дивиденды $5. Как это отражается?</div></div>", "backHtml": "<div>\n<div><div>3 statements · в трёх отчётах (tax 40%)</div>\n<table><tr><td>IS / ОПУ</td><td>Без изменений</td></tr>\n<tr><td>CFS / ОДДС</td><td>Дивиденды −5 в CFF → деньги −5</td></tr>\n<tr><td>BS / Баланс</td><td>Активы: деньги −5. Пассивы: нераспр. прибыль −5 (по версии гайда)</td></tr></table></div>\n<div><div>Answer (EN)</div>IS: no changes. CFS: additional Dividend of $5 in CFF → cash −$5. BS: Cash −$5; Retained Earnings −$5. Since statements are consolidated when you own &gt;50%, you don&#x27;t multiply by ownership — only Net Income is split out.</div>\n<div><div>Ответ (RU)</div>ОПУ: без изменений. ОДДС: дивиденд −$5 в финансовом потоке → деньги −$5. Баланс: деньги −$5; нераспределённая прибыль −$5. Так как отчётность консолидирована, на долю владения не умножаем — разделяется только чистая прибыль.</div>\n<div><div>Пояснение</div>Оговорка: это упрощённый ответ гайда. В реальной консолидации 70% дивидендов ($3,5) — внутригрупповой платёж, который исключается, а из группы уходят только $1,5 миноритариям, и они уменьшают NCI, а не нераспределённую прибыль. На собеседовании можно дать ответ гайда, но упомянуть это уточнение — это покажет глубину понимания.</div>\n</div>"}, {"id": 1790385598431, "topic": "620f982081e3e73e", "sec": "IB Accounting (BIWS) EN-RU::6. Advanced Scenarios — Продвинутые сценарии", "q": "Advanced Scenarios · Продвинутые сценарии You own 30% of another company, which earns Net Income of $20. Walk me through recording your share of Net Income. Вам принадлежит 30% компании с прибылью $20. Как отразить вашу долю прибыли?", "a": ["3 statements · в трёх отчётах (tax 40%) IS / ОПУ Доля в прибыли +6 → ЧП +6 CFS / ОДДС ЧП +6; −6 неденежная доля → деньги 0 BS / Баланс Активы: инвестиции в ассоц. компании +6. Пассивы: нераспр. прибыль +6 Answer (EN) Nothing is consolidated. IS: add 'Net Income from Equity Interests' of $6 (30% × $20) → Net Income +$6. CFS: Net Income +$6, subtract $6 because you haven't received it in cash (no control) → cash unchanged. BS: Investments in Equity Interests +$6; Retained Earnings +$6. Ответ (RU) Ничего не консолидируется. ОПУ: добавляем «прибыль от долевого участия» $6 (30% × $20) → чистая прибыль +$6. ОДДС: чистая прибыль +$6, вычитаем $6, так как деньги не получены (контроля нет) → деньги без изменений. Баланс: инвестиции в ассоциированные компании +$6; нераспределённая прибыль +$6. Пояснение Сравни с NCI: там прибыль вычитается из ОПУ и прибавляется в ОДДС, здесь — наоборот. Причина одна: деньги считаются «нашими» только при контроле."], "frontHtml": "<div><div>Advanced Scenarios · Продвинутые сценарии</div>\n<div>You own 30% of another company, which earns Net Income of $20. Walk me through recording your share of Net Income.</div>\n<div>Вам принадлежит 30% компании с прибылью $20. Как отразить вашу долю прибыли?</div></div>", "backHtml": "<div>\n<div><div>3 statements · в трёх отчётах (tax 40%)</div>\n<table><tr><td>IS / ОПУ</td><td>Доля в прибыли +6 → ЧП +6</td></tr>\n<tr><td>CFS / ОДДС</td><td>ЧП +6; −6 неденежная доля → деньги 0</td></tr>\n<tr><td>BS / Баланс</td><td>Активы: инвестиции в ассоц. компании +6. Пассивы: нераспр. прибыль +6</td></tr></table></div>\n<div><div>Answer (EN)</div>Nothing is consolidated. IS: add &#x27;Net Income from Equity Interests&#x27; of $6 (30% × $20) → Net Income +$6. CFS: Net Income +$6, subtract $6 because you haven&#x27;t received it in cash (no control) → cash unchanged. BS: Investments in Equity Interests +$6; Retained Earnings +$6.</div>\n<div><div>Ответ (RU)</div>Ничего не консолидируется. ОПУ: добавляем «прибыль от долевого участия» $6 (30% × $20) → чистая прибыль +$6. ОДДС: чистая прибыль +$6, вычитаем $6, так как деньги не получены (контроля нет) → деньги без изменений. Баланс: инвестиции в ассоциированные компании +$6; нераспределённая прибыль +$6.</div>\n<div><div>Пояснение</div>Сравни с NCI: там прибыль вычитается из ОПУ и прибавляется в ОДДС, здесь — наоборот. Причина одна: деньги считаются «нашими» только при контроле.</div>\n</div>"}, {"id": 1790385598433, "topic": "620f982081e3e73e", "sec": "IB Accounting (BIWS) EN-RU::6. Advanced Scenarios — Продвинутые сценарии", "q": "Advanced Scenarios · Продвинутые сценарии The 30%-owned company now issues Dividends of $10. Including the previous changes, walk me through the statements. Та же компания (30%) выплачивает дивиденды $10. Что происходит с учётом прошлого шага?", "a": ["3 statements · в трёх отчётах (tax 40%) IS / ОПУ Доля в прибыли +6 → ЧП +6 CFS / ОДДС ЧП +6; −6 доля прибыли; +3 полученные дивиденды → деньги +3 BS / Баланс Активы: деньги +3, инвестиции +3 = +6. Пассивы: нераспр. прибыль +6 Answer (EN) IS: same — Net Income +$6. CFS: Net Income +$6, subtract $6, then ADD $3 (30% × $10) dividends received in CFO → cash +$3. BS: Cash +$3; Investments in Equity Interests +$6 − $3 = +$3 → Assets +$6; Retained Earnings +$6. Ответ (RU) ОПУ: то же — чистая прибыль +$6. ОДДС: чистая прибыль +$6, вычитаем $6, затем ПРИБАВЛЯЕМ $3 (30% × $10) полученных дивидендов в операционном потоке → деньги +$3. Баланс: деньги +$3; инвестиции +$6 − $3 = +$3 → активы +$6; нераспределённая прибыль +$6. Пояснение Полученные дивиденды — в операционном потоке, а не в финансовом: в финансовом только дивиденды, которые платит сама компания. Инвестиция — как «мини-капитал»: + доля прибыли − доля дивидендов."], "frontHtml": "<div><div>Advanced Scenarios · Продвинутые сценарии</div>\n<div>The 30%-owned company now issues Dividends of $10. Including the previous changes, walk me through the statements.</div>\n<div>Та же компания (30%) выплачивает дивиденды $10. Что происходит с учётом прошлого шага?</div></div>", "backHtml": "<div>\n<div><div>3 statements · в трёх отчётах (tax 40%)</div>\n<table><tr><td>IS / ОПУ</td><td>Доля в прибыли +6 → ЧП +6</td></tr>\n<tr><td>CFS / ОДДС</td><td>ЧП +6; −6 доля прибыли; +3 полученные дивиденды → деньги +3</td></tr>\n<tr><td>BS / Баланс</td><td>Активы: деньги +3, инвестиции +3 = +6. Пассивы: нераспр. прибыль +6</td></tr></table></div>\n<div><div>Answer (EN)</div>IS: same — Net Income +$6. CFS: Net Income +$6, subtract $6, then ADD $3 (30% × $10) dividends received in CFO → cash +$3. BS: Cash +$3; Investments in Equity Interests +$6 − $3 = +$3 → Assets +$6; Retained Earnings +$6.</div>\n<div><div>Ответ (RU)</div>ОПУ: то же — чистая прибыль +$6. ОДДС: чистая прибыль +$6, вычитаем $6, затем ПРИБАВЛЯЕМ $3 (30% × $10) полученных дивидендов в операционном потоке → деньги +$3. Баланс: деньги +$3; инвестиции +$6 − $3 = +$3 → активы +$6; нераспределённая прибыль +$6.</div>\n<div><div>Пояснение</div>Полученные дивиденды — в операционном потоке, а не в финансовом: в финансовом только дивиденды, которые платит сама компания. Инвестиция — как «мини-капитал»: + доля прибыли − доля дивидендов.</div>\n</div>"}, {"id": 1790385598435, "topic": "620f982081e3e73e", "sec": "IB Accounting (BIWS) EN-RU::6. Advanced Scenarios — Продвинутые сценарии", "q": "Advanced Scenarios · Продвинутые сценарии What if you now own only 10% of this company? Would anything change? А если доля всего 10%? Что-то изменится?", "a": ["Answer (EN) In theory yes: under 20% it should be recorded as a Security or Short-Term Investment, and you'd only include dividends received, not its Net Income. In practice treatment varies; some companies still use the equity method if they have 'significant influence'. Ответ (RU) Теоретически да: при доле меньше 20% компания учитывается как финансовая инвестиция, и в учёт попадают только полученные дивиденды, а не её прибыль. На практике по-разному: при существенном влиянии некоторые продолжают применять метод долевого участия. Пояснение Если это просто финансовое вложение, то дивиденды $1 (10% × $10) — доход в ОПУ и реальный приток денег, а стоимость доли может переоцениваться по рынку."], "frontHtml": "<div><div>Advanced Scenarios · Продвинутые сценарии</div>\n<div>What if you now own only 10% of this company? Would anything change?</div>\n<div>А если доля всего 10%? Что-то изменится?</div></div>", "backHtml": "<div>\n\n<div><div>Answer (EN)</div>In theory yes: under 20% it should be recorded as a Security or Short-Term Investment, and you&#x27;d only include dividends received, not its Net Income. In practice treatment varies; some companies still use the equity method if they have &#x27;significant influence&#x27;.</div>\n<div><div>Ответ (RU)</div>Теоретически да: при доле меньше 20% компания учитывается как финансовая инвестиция, и в учёт попадают только полученные дивиденды, а не её прибыль. На практике по-разному: при существенном влиянии некоторые продолжают применять метод долевого участия.</div>\n<div><div>Пояснение</div>Если это просто финансовое вложение, то дивиденды $1 (10% × $10) — доход в ОПУ и реальный приток денег, а стоимость доли может переоцениваться по рынку.</div>\n</div>"}, {"id": 1790385598437, "topic": "620f982081e3e73e", "sec": "IB Accounting (BIWS) EN-RU::6. Advanced Scenarios — Продвинутые сценарии", "q": "Advanced Scenarios · Продвинутые сценарии Walk me through paying $20 of interest on Debt: $10 cash interest and $10 Paid-in-Kind (PIK) interest. Проценты по долгу $20: $10 деньгами и $10 в форме PIK. Что происходит?", "a": ["3 statements · в трёх отчётах (tax 40%) IS / ОПУ Проценты −20 → прибыль до налога −20; ЧП −12 CFS / ОДДС ЧП −12; +10 PIK → деньги −2 BS / Баланс Активы: деньги −2. Пассивы: долг +10, нераспр. прибыль −12 = −2 Answer (EN) IS: both appear — Pre-Tax Income −$20, Net Income −$12. CFS: Net Income −$12, add back $10 non-cash PIK → cash −$2. BS: Cash −$2; Debt +$10 (PIK accrues to Debt), Retained Earnings −$12 → −$2. Ответ (RU) ОПУ: обе части — расход: прибыль до налога −$20, чистая прибыль −$12. ОДДС: чистая прибыль −$12, прибавляем неденежные PIK-проценты +$10 → деньги −$2. Баланс: деньги −$2; долг +$10 (PIK добавляется к телу долга), нераспределённая прибыль −$12 → −$2. Пояснение PIK (Paid-in-Kind) — проценты не платятся деньгами, а прибавляются к сумме долга. Это обычный неденежный расход: уменьшает налог, а «что-то ещё на балансе» — это сам долг. Встречается в LBO и мезонинном финансировании."], "frontHtml": "<div><div>Advanced Scenarios · Продвинутые сценарии</div>\n<div>Walk me through paying $20 of interest on Debt: $10 cash interest and $10 Paid-in-Kind (PIK) interest.</div>\n<div>Проценты по долгу $20: $10 деньгами и $10 в форме PIK. Что происходит?</div></div>", "backHtml": "<div>\n<div><div>3 statements · в трёх отчётах (tax 40%)</div>\n<table><tr><td>IS / ОПУ</td><td>Проценты −20 → прибыль до налога −20; ЧП −12</td></tr>\n<tr><td>CFS / ОДДС</td><td>ЧП −12; +10 PIK → деньги −2</td></tr>\n<tr><td>BS / Баланс</td><td>Активы: деньги −2. Пассивы: долг +10, нераспр. прибыль −12 = −2</td></tr></table></div>\n<div><div>Answer (EN)</div>IS: both appear — Pre-Tax Income −$20, Net Income −$12. CFS: Net Income −$12, add back $10 non-cash PIK → cash −$2. BS: Cash −$2; Debt +$10 (PIK accrues to Debt), Retained Earnings −$12 → −$2.</div>\n<div><div>Ответ (RU)</div>ОПУ: обе части — расход: прибыль до налога −$20, чистая прибыль −$12. ОДДС: чистая прибыль −$12, прибавляем неденежные PIK-проценты +$10 → деньги −$2. Баланс: деньги −$2; долг +$10 (PIK добавляется к телу долга), нераспределённая прибыль −$12 → −$2.</div>\n<div><div>Пояснение</div>PIK (Paid-in-Kind) — проценты не платятся деньгами, а прибавляются к сумме долга. Это обычный неденежный расход: уменьшает налог, а «что-то ещё на балансе» — это сам долг. Встречается в LBO и мезонинном финансировании.</div>\n</div>"}, {"id": 1790385598439, "topic": "620f982081e3e73e", "sec": "IB Accounting (BIWS) EN-RU::6. Advanced Scenarios — Продвинутые сценарии", "q": "Advanced Scenarios · Продвинутые сценарии A company records $100 of Tax Benefits from SBC, with $40 of Excess Tax Benefits. Walk me through the statements (ignore the original SBC issuance). Компания отражает $100 Tax Benefits от SBC, из них $40 Excess. Что происходит?", "a": ["3 statements · в трёх отчётах (tax 40%) IS / ОПУ Без изменений CFS / ОДДС CFO +100 −40 = +60; CFF +40 → деньги +100 BS / Баланс Активы: деньги +100. Пассивы: APIC +100 Answer (EN) IS: no changes. CFS: add back $100 Tax Benefits in CFO and subtract $40 Excess → CFO +$60; add $40 in CFF → cash +$100. BS: Cash +$100; Common Stock & APIC +$100. Ответ (RU) ОПУ: без изменений. ОДДС: прибавляем $100 Tax Benefits в операционном потоке и вычитаем $40 Excess → операционный поток +$60; прибавляем $40 в финансовом → деньги +$100. Баланс: деньги +$100; акционерный капитал и APIC +$100. Пояснение Переклассификация: налоговая выгода зачисляется в капитал (APIC), а часть, связанная с ростом цены акций, показывается как финансовая деятельность. Напомню, что правила изменились в 2016 году — тема для общего понимания."], "frontHtml": "<div><div>Advanced Scenarios · Продвинутые сценарии</div>\n<div>A company records $100 of Tax Benefits from SBC, with $40 of Excess Tax Benefits. Walk me through the statements (ignore the original SBC issuance).</div>\n<div>Компания отражает $100 Tax Benefits от SBC, из них $40 Excess. Что происходит?</div></div>", "backHtml": "<div>\n<div><div>3 statements · в трёх отчётах (tax 40%)</div>\n<table><tr><td>IS / ОПУ</td><td>Без изменений</td></tr>\n<tr><td>CFS / ОДДС</td><td>CFO +100 −40 = +60; CFF +40 → деньги +100</td></tr>\n<tr><td>BS / Баланс</td><td>Активы: деньги +100. Пассивы: APIC +100</td></tr></table></div>\n<div><div>Answer (EN)</div>IS: no changes. CFS: add back $100 Tax Benefits in CFO and subtract $40 Excess → CFO +$60; add $40 in CFF → cash +$100. BS: Cash +$100; Common Stock &amp; APIC +$100.</div>\n<div><div>Ответ (RU)</div>ОПУ: без изменений. ОДДС: прибавляем $100 Tax Benefits в операционном потоке и вычитаем $40 Excess → операционный поток +$60; прибавляем $40 в финансовом → деньги +$100. Баланс: деньги +$100; акционерный капитал и APIC +$100.</div>\n<div><div>Пояснение</div>Переклассификация: налоговая выгода зачисляется в капитал (APIC), а часть, связанная с ростом цены акций, показывается как финансовая деятельность. Напомню, что правила изменились в 2016 году — тема для общего понимания.</div>\n</div>"}, {"id": 1790385598441, "topic": "620f982081e3e73e", "sec": "IB Accounting (BIWS) EN-RU::6. Advanced Scenarios — Продвинутые сценарии", "q": "Advanced Scenarios · Продвинутые сценарии Book Depreciation is $10/year for 3 years; tax Depreciation is $15, $10, $5. Walk me through the BOOK statements in Year 1. Бухгалтерская амортизация $10 в год 3 года, налоговая — $15, $10, $5. Что происходит в бухгалтерской отчётности в 1-м году?", "a": ["3 statements · в трёх отчётах (tax 40%) IS / ОПУ Амортизация −10 → прибыль до налога −10; ЧП −6 CFS / ОДДС ЧП −6; +10 амортизация; +2 отлож. налог → деньги +6 BS / Баланс Активы: деньги +6, ОС −10 = −4. Пассивы: ОНО +2, нераспр. прибыль −6 = −4 Answer (EN) IS: Book Depreciation $10 → Pre-Tax Income −$10, Net Income −$6 (book taxes −$4; cash taxes fall by $6 because tax Depreciation is $15). CFS: Net Income −$6, add back $10 Depreciation, add back $2 Deferred Taxes → cash +$6. BS: Cash +$6, PP&E −$10 → Assets −$4; DTL +$2, Retained Earnings −$6 → −$4. Ответ (RU) ОПУ: бухгалтерская амортизация $10 → прибыль до налога −$10, чистая прибыль −$6 (налог по бухучёту −$4, а денежный налог −$6, так как налоговая амортизация $15). ОДДС: чистая прибыль −$6, +$10 амортизация, +$2 отложенный налог → деньги +$6. Баланс: деньги +$6, ОС −$10 → активы −$4; ОНО +$2, нераспределённая прибыль −$6 → −$4. Пояснение Денежный налог на $2 меньше бухгалтерского — значит, мы «недоплатили» и возникает ОНО $2. Проверка: деньги +6 = экономия реального налога 40% × 15."], "frontHtml": "<div><div>Advanced Scenarios · Продвинутые сценарии</div>\n<div>Book Depreciation is $10/year for 3 years; tax Depreciation is $15, $10, $5. Walk me through the BOOK statements in Year 1.</div>\n<div>Бухгалтерская амортизация $10 в год 3 года, налоговая — $15, $10, $5. Что происходит в бухгалтерской отчётности в 1-м году?</div></div>", "backHtml": "<div>\n<div><div>3 statements · в трёх отчётах (tax 40%)</div>\n<table><tr><td>IS / ОПУ</td><td>Амортизация −10 → прибыль до налога −10; ЧП −6</td></tr>\n<tr><td>CFS / ОДДС</td><td>ЧП −6; +10 амортизация; +2 отлож. налог → деньги +6</td></tr>\n<tr><td>BS / Баланс</td><td>Активы: деньги +6, ОС −10 = −4. Пассивы: ОНО +2, нераспр. прибыль −6 = −4</td></tr></table></div>\n<div><div>Answer (EN)</div>IS: Book Depreciation $10 → Pre-Tax Income −$10, Net Income −$6 (book taxes −$4; cash taxes fall by $6 because tax Depreciation is $15). CFS: Net Income −$6, add back $10 Depreciation, add back $2 Deferred Taxes → cash +$6. BS: Cash +$6, PP&amp;E −$10 → Assets −$4; DTL +$2, Retained Earnings −$6 → −$4.</div>\n<div><div>Ответ (RU)</div>ОПУ: бухгалтерская амортизация $10 → прибыль до налога −$10, чистая прибыль −$6 (налог по бухучёту −$4, а денежный налог −$6, так как налоговая амортизация $15). ОДДС: чистая прибыль −$6, +$10 амортизация, +$2 отложенный налог → деньги +$6. Баланс: деньги +$6, ОС −$10 → активы −$4; ОНО +$2, нераспределённая прибыль −$6 → −$4.</div>\n<div><div>Пояснение</div>Денежный налог на $2 меньше бухгалтерского — значит, мы «недоплатили» и возникает ОНО $2. Проверка: деньги +6 = экономия реального налога 40% × 15.</div>\n</div>"}, {"id": 1790385598443, "topic": "620f982081e3e73e", "sec": "IB Accounting (BIWS) EN-RU::6. Advanced Scenarios — Продвинутые сценарии", "q": "Advanced Scenarios · Продвинутые сценарии Now move to Year 2 (book and tax Depreciation both $10). What happens? Второй год: амортизация в обоих учётах $10. Что происходит?", "a": ["3 statements · в трёх отчётах (tax 40%) IS / ОПУ Прибыль до налога −10; ЧП −6 CFS / ОДДС ЧП −6; +10 амортизация → деньги +4 BS / Баланс Активы: деньги +4, ОС −10 = −6. Пассивы: нераспр. прибыль −6 Answer (EN) IS: Pre-Tax Income −$10, Net Income −$6. CFS: Net Income −$6, add back $10 → cash +$4; no Deferred Tax change since book taxes = cash taxes. BS: Cash +$4, PP&E −$10 → Assets −$6; Retained Earnings −$6. Ответ (RU) ОПУ: прибыль до налога −$10, чистая прибыль −$6. ОДДС: чистая прибыль −$6, +$10 амортизация → деньги +$4; отложенный налог не меняется, так как налоги совпадают. Баланс: деньги +$4, ОС −$10 → активы −$6; нераспределённая прибыль −$6. Пояснение Обычный базовый сценарий с амортизацией: временной разницы в этом году нет."], "frontHtml": "<div><div>Advanced Scenarios · Продвинутые сценарии</div>\n<div>Now move to Year 2 (book and tax Depreciation both $10). What happens?</div>\n<div>Второй год: амортизация в обоих учётах $10. Что происходит?</div></div>", "backHtml": "<div>\n<div><div>3 statements · в трёх отчётах (tax 40%)</div>\n<table><tr><td>IS / ОПУ</td><td>Прибыль до налога −10; ЧП −6</td></tr>\n<tr><td>CFS / ОДДС</td><td>ЧП −6; +10 амортизация → деньги +4</td></tr>\n<tr><td>BS / Баланс</td><td>Активы: деньги +4, ОС −10 = −6. Пассивы: нераспр. прибыль −6</td></tr></table></div>\n<div><div>Answer (EN)</div>IS: Pre-Tax Income −$10, Net Income −$6. CFS: Net Income −$6, add back $10 → cash +$4; no Deferred Tax change since book taxes = cash taxes. BS: Cash +$4, PP&amp;E −$10 → Assets −$6; Retained Earnings −$6.</div>\n<div><div>Ответ (RU)</div>ОПУ: прибыль до налога −$10, чистая прибыль −$6. ОДДС: чистая прибыль −$6, +$10 амортизация → деньги +$4; отложенный налог не меняется, так как налоги совпадают. Баланс: деньги +$4, ОС −$10 → активы −$6; нераспределённая прибыль −$6.</div>\n<div><div>Пояснение</div>Обычный базовый сценарий с амортизацией: временной разницы в этом году нет.</div>\n</div>"}, {"id": 1790385598445, "topic": "620f982081e3e73e", "sec": "IB Accounting (BIWS) EN-RU::6. Advanced Scenarios — Продвинутые сценарии", "q": "Advanced Scenarios · Продвинутые сценарии Finally Year 3 (book $10, tax $5). Walk me through the statements. Третий год: бухгалтерская амортизация $10, налоговая $5. Что происходит?", "a": ["3 statements · в трёх отчётах (tax 40%) IS / ОПУ Прибыль до налога −10; ЧП −6 CFS / ОДДС ЧП −6; +10 амортизация; −2 доплата налога → деньги +2 BS / Баланс Активы: деньги +2, ОС −10 = −8. Пассивы: ОНО −2, нераспр. прибыль −6 = −8 Answer (EN) IS: Pre-Tax Income −$10, Net Income −$6 (cash taxes fall only $2). CFS: Net Income −$6, add back $10, subtract $2 extra cash taxes (catch-up) → cash +$2. BS: Cash +$2, PP&E −$10 → Assets −$8; DTL −$2, Retained Earnings −$6 → −$8. Ответ (RU) ОПУ: прибыль до налога −$10, чистая прибыль −$6 (денежный налог падает только на $2). ОДДС: чистая прибыль −$6, +$10 амортизация, −$2 доплата налога → деньги +$2. Баланс: деньги +$2, ОС −$10 → активы −$8; ОНО −$2, нераспределённая прибыль −$6 → −$8. Пояснение ОНО, созданное в 1-м году, «разворачивается»: компания доплачивает налог. За три года ОНО: +2, 0, −2 = 0 — разница была временной."], "frontHtml": "<div><div>Advanced Scenarios · Продвинутые сценарии</div>\n<div>Finally Year 3 (book $10, tax $5). Walk me through the statements.</div>\n<div>Третий год: бухгалтерская амортизация $10, налоговая $5. Что происходит?</div></div>", "backHtml": "<div>\n<div><div>3 statements · в трёх отчётах (tax 40%)</div>\n<table><tr><td>IS / ОПУ</td><td>Прибыль до налога −10; ЧП −6</td></tr>\n<tr><td>CFS / ОДДС</td><td>ЧП −6; +10 амортизация; −2 доплата налога → деньги +2</td></tr>\n<tr><td>BS / Баланс</td><td>Активы: деньги +2, ОС −10 = −8. Пассивы: ОНО −2, нераспр. прибыль −6 = −8</td></tr></table></div>\n<div><div>Answer (EN)</div>IS: Pre-Tax Income −$10, Net Income −$6 (cash taxes fall only $2). CFS: Net Income −$6, add back $10, subtract $2 extra cash taxes (catch-up) → cash +$2. BS: Cash +$2, PP&amp;E −$10 → Assets −$8; DTL −$2, Retained Earnings −$6 → −$8.</div>\n<div><div>Ответ (RU)</div>ОПУ: прибыль до налога −$10, чистая прибыль −$6 (денежный налог падает только на $2). ОДДС: чистая прибыль −$6, +$10 амортизация, −$2 доплата налога → деньги +$2. Баланс: деньги +$2, ОС −$10 → активы −$8; ОНО −$2, нераспределённая прибыль −$6 → −$8.</div>\n<div><div>Пояснение</div>ОНО, созданное в 1-м году, «разворачивается»: компания доплачивает налог. За три года ОНО: +2, 0, −2 = 0 — разница была временной.</div>\n</div>"}, {"id": 1790385598447, "topic": "620f982081e3e73e", "sec": "IB Accounting (BIWS) EN-RU::6. Advanced Scenarios — Продвинутые сценарии", "q": "Advanced Scenarios · Продвинутые сценарии A company records a $100 Goodwill Impairment that is NOT deductible for cash tax purposes. Walk me through the 3 statements. Обесценение гудвила $100, которое НЕ уменьшает денежный налог. Что происходит?", "a": ["3 statements · в трёх отчётах (tax 40%) IS / ОПУ Обесценение −100 → прибыль до налога −100; ЧП −60 CFS / ОДДС ЧП −60; +100 обесценение; −40 отлож. налог → деньги 0 BS / Баланс Активы: гудвил −100. Пассивы: ОНО −40, нераспр. прибыль −60 = −100 Answer (EN) IS (book): Pre-Tax Income −$100, Net Income −$60; on the tax statements nothing changes, so cash taxes are $40 higher than book taxes. CFS: Net Income −$60, add back $100 → +$40, subtract $40 Deferred Taxes → cash unchanged. BS: Goodwill −$100; DTL −$40, Retained Earnings −$60 → both −$100. Ответ (RU) ОПУ (бухгалтерский): прибыль до налога −$100, чистая прибыль −$60; в налоговом учёте ничего не меняется, поэтому денежный налог на $40 больше бухгалтерского. ОДДС: чистая прибыль −$60, +$100 обесценение → +$40, −$40 отложенный налог → деньги без изменений. Баланс: гудвил −$100; ОНО −$40, нераспределённая прибыль −$60 → обе стороны −$100. Пояснение Когда расход не уменьшает реальный налог, экономии денег нет: деньги 0. Разница между бухгалтерским и налоговым налогом отражается через ОНО/ОНА."], "frontHtml": "<div><div>Advanced Scenarios · Продвинутые сценарии</div>\n<div>A company records a $100 Goodwill Impairment that is NOT deductible for cash tax purposes. Walk me through the 3 statements.</div>\n<div>Обесценение гудвила $100, которое НЕ уменьшает денежный налог. Что происходит?</div></div>", "backHtml": "<div>\n<div><div>3 statements · в трёх отчётах (tax 40%)</div>\n<table><tr><td>IS / ОПУ</td><td>Обесценение −100 → прибыль до налога −100; ЧП −60</td></tr>\n<tr><td>CFS / ОДДС</td><td>ЧП −60; +100 обесценение; −40 отлож. налог → деньги 0</td></tr>\n<tr><td>BS / Баланс</td><td>Активы: гудвил −100. Пассивы: ОНО −40, нераспр. прибыль −60 = −100</td></tr></table></div>\n<div><div>Answer (EN)</div>IS (book): Pre-Tax Income −$100, Net Income −$60; on the tax statements nothing changes, so cash taxes are $40 higher than book taxes. CFS: Net Income −$60, add back $100 → +$40, subtract $40 Deferred Taxes → cash unchanged. BS: Goodwill −$100; DTL −$40, Retained Earnings −$60 → both −$100.</div>\n<div><div>Ответ (RU)</div>ОПУ (бухгалтерский): прибыль до налога −$100, чистая прибыль −$60; в налоговом учёте ничего не меняется, поэтому денежный налог на $40 больше бухгалтерского. ОДДС: чистая прибыль −$60, +$100 обесценение → +$40, −$40 отложенный налог → деньги без изменений. Баланс: гудвил −$100; ОНО −$40, нераспределённая прибыль −$60 → обе стороны −$100.</div>\n<div><div>Пояснение</div>Когда расход не уменьшает реальный налог, экономии денег нет: деньги 0. Разница между бухгалтерским и налоговым налогом отражается через ОНО/ОНА.</div>\n</div>"}, {"id": 1790385598449, "topic": "620f982081e3e73e", "sec": "IB Accounting (BIWS) EN-RU::6. Advanced Scenarios — Продвинутые сценарии", "q": "Advanced Scenarios · Продвинутые сценарии How can you tell whether a Goodwill Impairment will be tax-deductible? Как понять, уменьшает ли обесценение гудвила налог?", "a": ["Answer (EN) You can't know for sure unless the company says so, but Goodwill Impairment from acquisitions is generally NOT tax-deductible — otherwise companies would write down acquisitions just to save taxes. Goodwill from other sources may be deductible, but large impairments are rarely from other sources. Ответ (RU) Точно узнать можно только из раскрытий компании, но обесценение гудвила от приобретений обычно НЕ уменьшает налог — иначе компании списывали бы покупки ради экономии налога. Гудвил из других источников может уменьшать налог, но крупные обесценения почти всегда связаны с приобретениями. Пояснение Логика регулятора простая: неденежный расход, который компания во многом определяет сама, нельзя позволить использовать для снижения налогов."], "frontHtml": "<div><div>Advanced Scenarios · Продвинутые сценарии</div>\n<div>How can you tell whether a Goodwill Impairment will be tax-deductible?</div>\n<div>Как понять, уменьшает ли обесценение гудвила налог?</div></div>", "backHtml": "<div>\n\n<div><div>Answer (EN)</div>You can&#x27;t know for sure unless the company says so, but Goodwill Impairment from acquisitions is generally NOT tax-deductible — otherwise companies would write down acquisitions just to save taxes. Goodwill from other sources may be deductible, but large impairments are rarely from other sources.</div>\n<div><div>Ответ (RU)</div>Точно узнать можно только из раскрытий компании, но обесценение гудвила от приобретений обычно НЕ уменьшает налог — иначе компании списывали бы покупки ради экономии налога. Гудвил из других источников может уменьшать налог, но крупные обесценения почти всегда связаны с приобретениями.</div>\n<div><div>Пояснение</div>Логика регулятора простая: неденежный расход, который компания во многом определяет сама, нельзя позволить использовать для снижения налогов.</div>\n</div>"}, {"id": 1790385598451, "topic": "620f982081e3e73e", "sec": "IB Accounting (BIWS) EN-RU::6. Advanced Scenarios — Продвинутые сценарии", "q": "Advanced Scenarios · Продвинутые сценарии A company has $100 of NOLs in its DTA and now earns Pre-Tax Income of $200. Assume NOLs can be used as a direct tax deduction on the statements. Walk me through them. У компании $100 налоговых убытков в ОНА, теперь прибыль до налога $200. Что происходит при использовании NOL?", "a": ["3 statements · в трёх отчётах (tax 40%) IS / ОПУ Использование NOL −100 → прибыль до налога −100; ЧП −60 CFS / ОДДС ЧП −60; +100 отлож. налог → деньги +40 BS / Баланс Активы: деньги +40, ОНА −100 = −60. Пассивы: нераспр. прибыль −60 Answer (EN) IS: apply the entire NOL balance — Pre-Tax Income −$100, Net Income −$60. CFS: Net Income −$60, add back the NOL usage as 'Deferred Taxes' +$100 → cash +$40. BS: Cash +$40, DTA −$100 → Assets −$60; Retained Earnings −$60. Ответ (RU) ОПУ: используем весь остаток NOL — прибыль до налога −$100, чистая прибыль −$60. ОДДС: чистая прибыль −$60, прибавляем использование NOL как «отложенный налог» +$100 → деньги +$40. Баланс: деньги +$40, ОНА −$100 → активы −$60; нераспределённая прибыль −$60. Пояснение Это упрощённая конвенция гайда (по условию задачи). В реальной отчётности ОНА = убыток × ставка налога ($40, а не $100), и при использовании NOL денежный налог падает на $40, а ОНА уменьшается на $40. Итог по деньгам тот же: +$40 экономии."], "frontHtml": "<div><div>Advanced Scenarios · Продвинутые сценарии</div>\n<div>A company has $100 of NOLs in its DTA and now earns Pre-Tax Income of $200. Assume NOLs can be used as a direct tax deduction on the statements. Walk me through them.</div>\n<div>У компании $100 налоговых убытков в ОНА, теперь прибыль до налога $200. Что происходит при использовании NOL?</div></div>", "backHtml": "<div>\n<div><div>3 statements · в трёх отчётах (tax 40%)</div>\n<table><tr><td>IS / ОПУ</td><td>Использование NOL −100 → прибыль до налога −100; ЧП −60</td></tr>\n<tr><td>CFS / ОДДС</td><td>ЧП −60; +100 отлож. налог → деньги +40</td></tr>\n<tr><td>BS / Баланс</td><td>Активы: деньги +40, ОНА −100 = −60. Пассивы: нераспр. прибыль −60</td></tr></table></div>\n<div><div>Answer (EN)</div>IS: apply the entire NOL balance — Pre-Tax Income −$100, Net Income −$60. CFS: Net Income −$60, add back the NOL usage as &#x27;Deferred Taxes&#x27; +$100 → cash +$40. BS: Cash +$40, DTA −$100 → Assets −$60; Retained Earnings −$60.</div>\n<div><div>Ответ (RU)</div>ОПУ: используем весь остаток NOL — прибыль до налога −$100, чистая прибыль −$60. ОДДС: чистая прибыль −$60, прибавляем использование NOL как «отложенный налог» +$100 → деньги +$40. Баланс: деньги +$40, ОНА −$100 → активы −$60; нераспределённая прибыль −$60.</div>\n<div><div>Пояснение</div>Это упрощённая конвенция гайда (по условию задачи). В реальной отчётности ОНА = убыток × ставка налога ($40, а не $100), и при использовании NOL денежный налог падает на $40, а ОНА уменьшается на $40. Итог по деньгам тот же: +$40 экономии.</div>\n</div>"}, {"id": 1790385598453, "topic": "620f982081e3e73e", "sec": "IB Accounting (BIWS) EN-RU::6. Advanced Scenarios — Продвинутые сценарии", "q": "Advanced Scenarios · Продвинутые сценарии Revenue $1,000 and EBITDA $200 for Jan 1 – Dec 31, 2050; $200 / $50 for Jan 1 – Mar 31, 2050; $300 / $75 for Jan 1 – Mar 31, 2051. What are TTM revenue and EBITDA as of Mar 31, 2051? Посчитайте выручку и EBITDA за последние 12 месяцев (TTM) на 31.03.2051.", "a": ["Answer (EN) TTM = New Partial Period + Twelve-Month Period − Old Partial Period. TTM Revenue = $300 + $1,000 − $200 = $1,100. TTM EBITDA = $75 + $200 − $50 = $225. Ответ (RU) TTM = новый неполный период + полный год − старый неполный период. Выручка TTM = 300 + 1000 − 200 = 1100. EBITDA TTM = 75 + 200 − 50 = 225. Пояснение Логика: берём весь 2050 год, убираем из него 1-й квартал 2050 и добавляем 1-й квартал 2051 — получаем апрель 2050 — март 2051. TTM (или LTM) используют в мультипликаторах, чтобы опираться на самые свежие данные."], "frontHtml": "<div><div>Advanced Scenarios · Продвинутые сценарии</div>\n<div>Revenue $1,000 and EBITDA $200 for Jan 1 – Dec 31, 2050; $200 / $50 for Jan 1 – Mar 31, 2050; $300 / $75 for Jan 1 – Mar 31, 2051. What are TTM revenue and EBITDA as of Mar 31, 2051?</div>\n<div>Посчитайте выручку и EBITDA за последние 12 месяцев (TTM) на 31.03.2051.</div></div>", "backHtml": "<div>\n\n<div><div>Answer (EN)</div>TTM = New Partial Period + Twelve-Month Period − Old Partial Period. TTM Revenue = $300 + $1,000 − $200 = $1,100. TTM EBITDA = $75 + $200 − $50 = $225.</div>\n<div><div>Ответ (RU)</div>TTM = новый неполный период + полный год − старый неполный период. Выручка TTM = 300 + 1000 − 200 = 1100. EBITDA TTM = 75 + 200 − 50 = 225.</div>\n<div><div>Пояснение</div>Логика: берём весь 2050 год, убираем из него 1-й квартал 2050 и добавляем 1-й квартал 2051 — получаем апрель 2050 — март 2051. TTM (или LTM) используют в мультипликаторах, чтобы опираться на самые свежие данные.</div>\n</div>"}, {"id": 1790385598455, "topic": "620f982081e3e73e", "sec": "IB Accounting (BIWS) EN-RU::6. Advanced Scenarios — Продвинутые сценарии", "q": "Advanced Scenarios · Продвинутые сценарии A company acquires another for $1,000 using 50% stock and 50% cash. The target has Assets of $1,000 and Liabilities of $800. Walk me through the combined Balance Sheet immediately after. Компанию покупают за $1000 (50% акциями, 50% деньгами). У цели активы $1000, обязательства $800. Как выглядит объединённый баланс сразу после сделки?", "a": ["Answer (EN) Target Equity = $200 and is wiped out. Add target Assets (+$1,000) and Liabilities (+$800). Subtract $500 cash used → Assets +$500; L&E +$800 liabilities + $500 new stock = +$1,300. Goodwill = Purchase Price − Seller's Book Value = $1,000 − $200 = $800, added to Assets → both sides +$1,300. Ответ (RU) Капитал цели = $200, он исключается. Добавляем её активы (+$1000) и обязательства (+$800). Вычитаем $500 потраченных денег → активы +$500; пассивы: +$800 обязательства + $500 новые акции = +$1300. Гудвил = цена покупки − балансовая стоимость продавца = 1000 − 200 = $800, добавляется в активы → обе стороны +$1300. Пояснение Базовая механика M&A: капитал продавца исключается, гудвил «закрывает» разницу, чтобы баланс сошёлся. В реальности сначала переоценивают активы цели по справедливой стоимости (выделяют нематериальные активы), и гудвил считают от переоценённых чистых активов."], "frontHtml": "<div><div>Advanced Scenarios · Продвинутые сценарии</div>\n<div>A company acquires another for $1,000 using 50% stock and 50% cash. The target has Assets of $1,000 and Liabilities of $800. Walk me through the combined Balance Sheet immediately after.</div>\n<div>Компанию покупают за $1000 (50% акциями, 50% деньгами). У цели активы $1000, обязательства $800. Как выглядит объединённый баланс сразу после сделки?</div></div>", "backHtml": "<div>\n\n<div><div>Answer (EN)</div>Target Equity = $200 and is wiped out. Add target Assets (+$1,000) and Liabilities (+$800). Subtract $500 cash used → Assets +$500; L&amp;E +$800 liabilities + $500 new stock = +$1,300. Goodwill = Purchase Price − Seller&#x27;s Book Value = $1,000 − $200 = $800, added to Assets → both sides +$1,300.</div>\n<div><div>Ответ (RU)</div>Капитал цели = $200, он исключается. Добавляем её активы (+$1000) и обязательства (+$800). Вычитаем $500 потраченных денег → активы +$500; пассивы: +$800 обязательства + $500 новые акции = +$1300. Гудвил = цена покупки − балансовая стоимость продавца = 1000 − 200 = $800, добавляется в активы → обе стороны +$1300.</div>\n<div><div>Пояснение</div>Базовая механика M&amp;A: капитал продавца исключается, гудвил «закрывает» разницу, чтобы баланс сошёлся. В реальности сначала переоценивают активы цели по справедливой стоимости (выделяют нематериальные активы), и гудвил считают от переоценённых чистых активов.</div>\n</div>"}, {"id": 1790385598457, "topic": "620f982081e3e73e", "sec": "IB Accounting (BIWS) EN-RU::6. Advanced Scenarios — Продвинутые сценарии", "q": "Advanced Scenarios · Продвинутые сценарии A company has $100 of Short-Term Investments classified as Available-for-Sale. Their market value rises to $110. Walk me through the 3 statements. Краткосрочные инвестиции $100 (AFS) подорожали до $110. Что происходит?", "a": ["3 statements · в трёх отчётах (tax 40%) IS / ОПУ Без изменений CFS / ОДДС Без изменений BS / Баланс Активы: инвестиции +10. Пассивы: AOCI +10 Answer (EN) IS: no changes — unrealized gains on AFS securities aren't on the IS. CFS: no changes (no cash). BS: Short-Term Investments +$10; AOCI +$10 in Shareholders' Equity. Ответ (RU) ОПУ: без изменений — нереализованная прибыль по AFS в ОПУ не попадает. ОДДС: без изменений (денег нет). Баланс: краткосрочные инвестиции +$10; прочий совокупный доход (AOCI) +$10 в капитале. Пояснение AOCI — «копилка» для переоценок, которые ещё не реализованы: курсовые разницы, переоценка бумаг для продажи. По МСФО 9 аналог — категория FVOCI."], "frontHtml": "<div><div>Advanced Scenarios · Продвинутые сценарии</div>\n<div>A company has $100 of Short-Term Investments classified as Available-for-Sale. Their market value rises to $110. Walk me through the 3 statements.</div>\n<div>Краткосрочные инвестиции $100 (AFS) подорожали до $110. Что происходит?</div></div>", "backHtml": "<div>\n<div><div>3 statements · в трёх отчётах (tax 40%)</div>\n<table><tr><td>IS / ОПУ</td><td>Без изменений</td></tr>\n<tr><td>CFS / ОДДС</td><td>Без изменений</td></tr>\n<tr><td>BS / Баланс</td><td>Активы: инвестиции +10. Пассивы: AOCI +10</td></tr></table></div>\n<div><div>Answer (EN)</div>IS: no changes — unrealized gains on AFS securities aren&#x27;t on the IS. CFS: no changes (no cash). BS: Short-Term Investments +$10; AOCI +$10 in Shareholders&#x27; Equity.</div>\n<div><div>Ответ (RU)</div>ОПУ: без изменений — нереализованная прибыль по AFS в ОПУ не попадает. ОДДС: без изменений (денег нет). Баланс: краткосрочные инвестиции +$10; прочий совокупный доход (AOCI) +$10 в капитале.</div>\n<div><div>Пояснение</div>AOCI — «копилка» для переоценок, которые ещё не реализованы: курсовые разницы, переоценка бумаг для продажи. По МСФО 9 аналог — категория FVOCI.</div>\n</div>"}, {"id": 1790385598459, "topic": "620f982081e3e73e", "sec": "IB Accounting (BIWS) EN-RU::6. Advanced Scenarios — Продвинутые сценарии", "q": "Advanced Scenarios · Продвинутые сценарии Now the securities are classified as Trading instead. Walk me through the 3 statements after their value increases by $10. Те же бумаги, но как Trading. Стоимость выросла на $10. Что происходит?", "a": ["3 statements · в трёх отчётах (tax 40%) IS / ОПУ Нереализ. прибыль +10 → прибыль до налога +10; ЧП +6 CFS / ОДДС ЧП +6; −10 неденежная прибыль → деньги −4 BS / Баланс Активы: деньги −4, инвестиции +10 = +6. Пассивы: нераспр. прибыль +6 Answer (EN) IS: unrealized gains on Trading securities go on the IS — Pre-Tax Income +$10, Net Income +$6. CFS: Net Income +$6, subtract the non-cash $10 gain → cash −$4. BS: Cash −$4, Investments +$10 → Assets +$6; Retained Earnings +$6. Ответ (RU) ОПУ: нереализованная прибыль по торговым бумагам попадает в ОПУ — прибыль до налога +$10, чистая прибыль +$6. ОДДС: чистая прибыль +$6, вычитаем неденежную прибыль −$10 → деньги −$4. Баланс: деньги −$4, инвестиции +$10 → активы +$6; нераспределённая прибыль +$6. Пояснение Интуиция: налог заплатили с «бумажного» дохода, поэтому деньги уменьшились, хотя стоимость активов выросла. Сравни с прошлым вопросом: одинаковое событие, но классификация бумаг полностью меняет картину."], "frontHtml": "<div><div>Advanced Scenarios · Продвинутые сценарии</div>\n<div>Now the securities are classified as Trading instead. Walk me through the 3 statements after their value increases by $10.</div>\n<div>Те же бумаги, но как Trading. Стоимость выросла на $10. Что происходит?</div></div>", "backHtml": "<div>\n<div><div>3 statements · в трёх отчётах (tax 40%)</div>\n<table><tr><td>IS / ОПУ</td><td>Нереализ. прибыль +10 → прибыль до налога +10; ЧП +6</td></tr>\n<tr><td>CFS / ОДДС</td><td>ЧП +6; −10 неденежная прибыль → деньги −4</td></tr>\n<tr><td>BS / Баланс</td><td>Активы: деньги −4, инвестиции +10 = +6. Пассивы: нераспр. прибыль +6</td></tr></table></div>\n<div><div>Answer (EN)</div>IS: unrealized gains on Trading securities go on the IS — Pre-Tax Income +$10, Net Income +$6. CFS: Net Income +$6, subtract the non-cash $10 gain → cash −$4. BS: Cash −$4, Investments +$10 → Assets +$6; Retained Earnings +$6.</div>\n<div><div>Ответ (RU)</div>ОПУ: нереализованная прибыль по торговым бумагам попадает в ОПУ — прибыль до налога +$10, чистая прибыль +$6. ОДДС: чистая прибыль +$6, вычитаем неденежную прибыль −$10 → деньги −$4. Баланс: деньги −$4, инвестиции +$10 → активы +$6; нераспределённая прибыль +$6.</div>\n<div><div>Пояснение</div>Интуиция: налог заплатили с «бумажного» дохода, поэтому деньги уменьшились, хотя стоимость активов выросла. Сравни с прошлым вопросом: одинаковое событие, но классификация бумаг полностью меняет картину.</div>\n</div>"}];